local S = {}

S.guides = {
    { name = 'About this data', group = 'Server', desc = 'Where the DriftwoodXI data in VanaGuide came from, how it was assembled, and what it lacks. Source: https://xi.driftwoodgaming.com/robots.txt, https://xi.driftwoodgaming.com/custom, https://xi.driftwoodgaming.com/features, https://xi.driftwoodgaming.com/news, https://xi.driftwoodgaming.com/commands, https://xi.driftwoodgaming.com/addons, https://github.com/DriftwoodGaming/DriftwoodXI-Content', steps = { { title = 'What was fetched', note = '• 151 pages of xi.driftwoodgaming.com were retrieved on 2026-10-28; 148 are used (home page and the /features and /news indexes skipped).\n• Used: /custom, /commands, /addons, /download, /download/linux, 33 add-on pages and 110 news posts.\n• GitHub DriftwoodGaming/DriftwoodXI-Content: README.md, content.json (launcher add-on feed) and ashita.json; add-on zips not downloaded.\n• No sitemap.xml exists; pages were found through site navigation.\n• robots.txt blocks /reset and /delete with no Crawl-delay; those paths, /register and all account pages were never requested.' }, { title = 'How it is written', note = '• Each bullet comes from a page in that guide\'s Source list.\n• Each page belongs to one topic; news posts carry dates, so trust the newest post when two disagree.\n• Gear tab: 34 items the pages give a price or source for; ids, levels and jobs taken from standard LandSandBoat data.' }, { title = 'Not covered', note = '• The site publishes no quest walkthroughs, drop tables, recipes or mob data; those tabs use standard LandSandBoat data.\n• Sets named only by family (Outfitter artifact sets, Driftmark Karieyh, Orvail and Thurandaut sets, Mythic weapons, unnamed Empyreans) are absent from the Gear tab.\n• Home page live player counts and the Discord server were not used.\n• Text is (c) DriftwoodXI with no open licence stated.' } } },
    { name = 'What is custom here', group = 'Server', desc = 'Summary of every DriftwoodXI system and number that differs from retail FFXI. Source: https://xi.driftwoodgaming.com/custom', steps = { { title = 'What is custom here', note = '• Custom 99/99 server with faster rates and many custom systems.\n• You control your own alt characters as trusts (alt-trusts); expansion content is raised 50+ levels.' }, { title = 'Weapon Burst — your weapon casts', note = '• Augment on a wielded weapon (main hand, off hand or ranged; never ammo or stackables) that rolls once per attack round, hit or miss, to cast a real spell on your target.\n• Earn Burst Tokens in the Gauntlet (/arena): 50 floors, up to 18 seats; clearing floor N gives each real player N tokens; a full clear totals 1,275.\n• Cost: 5,000 Burst Tokens + 750 Drift Coins on the Drift Exchange shelf in /quests, below the rotating daily offers.\n• The Exchange shows the price and the item\'s four slots before the spend button appears.\n• One burst per weapon; you may change the element in its slot.\n• Only one burst resolves per round even with three burst weapons, but each still rolls.\n• Alt-trusts\' weapons burst too, from the gear they wear.\n• The spell uses the wielder\'s magic skill, stats and gear, not the weapon\'s; rates are per round at 480 delay.\n• Fire: Fire 20%, Fire II 10%, Fire III 5%, Fire IV 3% (38% total), hits your target.\n• Ice: Blizzard I/II/III/IV at 20/10/5/3% (38%).\n• Wind: Aero I/II/III/IV at 20/10/5/3% (38%).\n• Elemental bursts: damage from INT vs target INT, Magic Attack Bonus, Magic Damage+; landing from Elemental Magic skill, Magic Accuracy and the INT gap.' }, { title = 'X-Magic — your spells cast twice', note = '• Ring augment: a spell you cast may trigger a free second spell at once (no MP, no recast).\n• Same price and shelf as Weapon Burst: 5,000 Burst Tokens + 750 Drift Coins in /quests.\n• The shelf offers four augments per Vana\'diel day on the daily-offer rotation; the Augments tab lists all of them.\n• Rings only, either hand, one X-Magic per ring; two of the same kind raise the chance, not the damage.\n• The follow-up is a real spell (damage, resists, magic bursts, enmity) but cannot proc again; max one per cast.\n• Alt-trusts get it from rings they wear.\n• Full chance on casts of about 1.33 s or longer; shorter casts scale it down proportionally; Fast Cast and haste count toward cast time.\n• Follow-up uses your skill, stats and gear; cures and buffs never resist; enemy spells resist on the listed skill, Magic Accuracy and stat gap.\n• Elements (on an enemy-targeted cast): Fire II 10%, Blizzard II 10%, Thunder II 9%, Aero II 9%, never the element just cast; 38% total.\n• Grace (on an ally/self cast): Cure III 14%, Regen 10%, Protect 8%, Shell 8%; 40% total; Cure III uses MND, VIT, Healing Magic skill, Cure Potency; others are flat by tier.\n• Ruin (on an enemy-targeted cast): Bio 14%, Dia 14%, Gravity 10%, Addle 10%; 48% total; Enfeebling skill lands Dia/Gravity/Addle (MND for Dia and Addle, INT for Gravity); Dark Magic skill and INT drive Bio.' }, { title = 'Job balance — how each job differs from retail', note = '• Same as retail apart from server-wide numbers: DRG, BLU, PUP, DNC, SCH, GEO, RUN.\n• All job ability recasts get a further 15% cut (Boost 30 s becomes 25 s; Barrage 3 min becomes 2:33).\n• WAR: Warcry 60 s (retail 30 s); Great Axe S+ (A+); Axe S- (A).\n• MNK: Boost +25% attack per use (12.5%); Boost base recast 30 s (15 s); Impetus crit cap 35% (50%); Formless Strikes lasts 30 s (3 min) with 5 min base recast (10 min); Chakra heals 2x HP.\n• WHM: Club S- (B+); Divine magic S- (A).' }, { title = 'Expansions — how much of Vana\'diel is open', note = '• All 6 expansions are open; each opens only after play-verification; the launcher\'s Expansions tab shows the same list.\n• Base game (2002): three nations, original jobs, nation storylines.\n• Rise of the Zilart (2003): Zilart missions, Tu\'Lia, Ru\'Aun, six advanced jobs.\n• Chains of Promathia (2004): Tavnazia, Sea, Sky, Promyvion.\n• Treasures of Aht Urhgan (2006): 48 missions, Whitegate, BLU/COR/PUP; monsters +60 levels.\n• Wings of the Goddess (2007): 54 missions, [S] zones, DNC/SCH; monsters +70 levels, up to 170.\n• Seekers of Adoulin (2013): Ulbuka, Colonization Reives, GEO/RUN; monsters level 150-180.\n• A Crystalline Prophecy, A Moogle Kupo d\'Etat, A Shantotto Ascension and Abyssea arrive with their surrounding expansions.' }, { title = 'Progression and the numbers', note = '• Rates: EXP, gil, capacity points, tabs and fame x3; drops x2; Fields/Grounds of Valor pages 1.5x and enabled everywhere; weapon skill and skillchain points x10 (Magian trials included).\n• Jobs start at level 1; limit break quests removed; support job equals main job level; six jobs unlocked at start, the rest accepted at level 1.\n• Every swing rolls a combat skill-up, and every roll under your cap succeeds.\n• Merits (dwmerits window): Weapon Skill category 15 to 70 total; each job ability group 10 to 20; HP, MP and seven attributes 30 upgrades each; lowering a merit refunds its point.\n• Ascension: limit points past full merits are banked permanently and buy Mastery tiers (HP, MP, attributes, accuracy, attack, damage taken, regen).\n• Item level cap brackets: 104, 109, 114, now 119.' }, { title = 'Your account is your party', note = '• One client, 16 characters, 6 fighting together.\n• DWSquad: register up to 5 of your characters and summon them as party members; they use their own gear and jobs, earn their own EXP, and refill HP/MP when they level mid-fight.\n• DWGambits: ordered rule sets per member (e.g. best Cure on an ally under 40% HP), chosen weapon skills and TP thresholds, standing distance.\n• Squads join alliances up to 18; battlefields that refuse trusts accept your own characters; SMN, DRG, BST and PUP members bring real pets.\n• DWMerc: list a character with an hourly rate and its rule sets; others hire it as a trust while you are offline and pay you gil.' }, { title = 'Content built for here', note = '• All entered from a window, not by travel.\n• Gauntlet (DWArena): 50 floors, 18 seats, alt-trusts allowed; floor N pays N Burst Tokens plus EXP and capacity points.\n• Raid: 18 boss trials in 13 venues, five tiers from Easy to Promyvion; Chain Trial (all in one arena) or Circuit (boss after boss) with a Grand Circuit leaderboard; enter from anywhere; reaches into CoP.\n• Nemesis: 240 famous NMs (Sky gods, Sea Jailers, Zeni NMs, Salvage chariots added 2026-09-10), each 100 levels above retail, in a private arena.\n• Unleashed: every 2 hours on the even hour Eastern, a Legend-tier NM appears at an outdoor site and the server is told where; 10 minutes to gather; no claim, so anyone in the zone can attack, heal or buff.\n• Politics (DWPolitics): six seats (Crown, four Mayors, Royal Treasurer) chosen by account votes on a 4-week season; climb town, then Jeuno, then Crown; public records and an uneditable Chronicle.\n• Drift Board (DWQuest): 10 daily and 9 weekly contracts on the Vana\'diel clock, accepted anywhere; plus a server-wide contract advanced by every credited kill.' }, { title = 'The economy, and your time', note = '• /warehouse (DWWarehouse): 1,000 account-shared slots, earnable to 2,000 and extendable with gil, usable anywhere.\n• /bags (DWBags): reach every bag on every character without logging out.\n• DWAH: real-price listings, gil-escrowed buy orders, selling anywhere with no fee, account wallet.\n• DWCPX: every nation\'s conquest shelf and merchant in one window, paid in points or gil, mounts included.\n• Drift Coins (from contracts) buy: Exchange rotating augments; Outfitter artifact, relic and Empyrean +2 sets; Jeweler Promathia-era accessories; Arms Dealer relic and Empyrean weapons; Artisan crafting-guild key items and Lu Shang\'s Fishing Rod.\n• Crafting: all crafts to 70 and three to 110 per character; HQ chance x2; harvesting tools never break; /craft (DWCraft) shows the crafter ledger; /fishing (DWFishing) plans a 0-110 route.\n• A Rare drop your main already has goes to the next character on your account.\n• Spoils: any EXP-giving mob may drop an equipment piece with 1-4 random augments straight to your bags, scaled to the mob\'s level, about half the time for a job in your squad.\n• Aggro and link radius are halved; anything that gives EXP checks as Easy Prey or higher.' }, { title = 'The client and the launcher', note = '• You supply your own FFXI copy.\n• Install Ashita downloads a checksum-verified Ashita v4 with the DriftwoodXI add-on set, configures it and keeps launcher and add-ons updated; it can also verify game files against a published manifest and target any FFXI install.\n• Alternate graphics: XIPivot ships with NextHD textures and XICombinedMaps toggles; enabled packs download and overlay without changing stock files.\n• Your controller mapping and camera settings persist; streamer mode hides your login name; a Custom commands box replaces default.txt.\n• Linux: a manual guide is on the site and the launcher ships an AppImage.\n• Only add-ons on the posted allowed list are permitted; others can be requested and added by name.' }, { title = 'None of it is sold', note = '• No cash shop, now or planned.\n• One account per player, 16 characters per account.' } } },
    { name = 'Commands', group = 'Server', desc = 'Reference list of DriftwoodXI\'s typed ! commands and the / add-on windows, sorted by topic. Source: https://xi.driftwoodgaming.com/commands', steps = { { title = 'How to read this page', note = '• DriftwoodXI offers 47 typed commands, per-job orders for squad members, and 33 add-on windows.\n• Commands beginning with ! go in the chat box and need no add-ons, from any chat mode.\n• Commands beginning with / open an add-on window; the launcher\'s Default set loads all of them.\n• Each window has a ! equivalent that covers everything the window does.\n• Type a command name followed by help to list its options in game.' }, { title = 'Your squad', note = '• !squad (/squad): register up to five of your own characters as party members, call or dismiss them, control them, set their combat rules and reach their bags.\n• Squad control: !squad call | dismiss | list | xp | buffs; !squad engage | disengage | come | rest.\n• Slots and stance: !squad set <slot> <character> | clear <slot>; !squad behavior <aggressive|defensive|passive|off>.\n• Rules: !squad rules presets | use <member> <set> (a preset exists for every job); !squad rules help; !squad rules audience <set> <rule> melee|mages|ranged|all picks which job groups a song rule targets.\n• Items: !squad who | bag <char> | find <text> | send <char> <item> | fetch <char> <item>; !squad use <char> <item> reads a scroll, feeds, or heals a downed alt.\n• Automaton: !squad unlock <char> <part> fits a part from that alt\'s bag; !squad autoname <char> [id] names it (no argument lists names).\n• Gear: !squad gear <char> | equip <char> <slot> <item> | tidy <char> | stack [char].\n• Storage: !squad stash <char> <bag#> <slot#> <itemid> [qty] moves one cell to the warehouse; !squad stashall <char> <bag#> [count] moves a whole bag or nothing (count only previews); !squad trash <char> <bag#> <slot#> <itemid> <qty> destroys a cell permanently.\n• !squad hints [char] lists possible upgrades; !squad restock <char> [apply] upgrades from the account warehouse; !squad help shows everything.\n• The /squad window handles membership; storage is in /bags and rules in /gambits.\n• !war … !run: each job abbreviation commands the squad member on that job (e.g. !blm casts, !whm heals).\n• !allwar … !allrun: commands every member of that job at once, matching main OR sub job (!allwhm also reaches a WAR/WHM).\n• !jobs (/jobs): change main/support jobs for you and squad members anywhere and save lineups; trusts out are dismissed and recalled. Usage: !jobs; !jobs set <char|me> <main> [sub|none]; !jobs save <name> | use <name>; !jobs list | delete <name>.\n• !trustengage 0 = retail (you must land a melee swing first); !trustengage 1 = trusts engage when you do; bare shows the setting.\n• !trustfollow <1-15> sets the first trust\'s follow distance in yalms (halves allowed); !trustfollow default restores stock; the others space behind it. The squad window has a slider.\n• !padd <character> sends a party invite via the server, since the Invite button greys out around squads.\n• !pally <character> invites their party into an alliance (up to three parties, 18 with squads); both must be party leaders.\n• !join accepts and !decline refuses a pending party or alliance invite (needed when a squad hides the dialog).\n• !pleave takes your party out of its alliance (leaders only); a lone remaining party dissolves the alliance.\n• !alliancesync [<character>|off] level syncs the entire alliance to one member; only the alliance leader can set it, the target must be level 10+ and not a trust. Syncing sends summons home; recalled ones come back synced. Off fades over 30 seconds.' }, { title = 'Getting around', note = '• !port (/port): teleport to anything already unlocked: home points, survival guides, outposts, teleport spells, Unity warps, Voidwatch rifts, Aht Urhgan Runic Portals.\n• Port fares are set by office holders, from 1/5 to 20x stock; gil above stock is split half to the holder, half destroyed (see /politics Revenue).\n• !home warps to your starting nation\'s home point.\n• !mh or !moghouse opens the Mog House menu where you stand.' }, { title = 'Gear and storage', note = '• !warehouse (/warehouse): 1,000 server-side slots shared by the account; +100 each from the support job quest and first-time nation ranks, up to 2,000; up to 1,000 more at 100,000 gil per slot.\n• !optimizegear equips your best owned gear for the current job; !optimizegear preview shows changes only. Not usable while engaged.\n• !squad restock <char> lists warehouse upgrades for a squad member; add apply to send them. In /bags it is the Gear tab\'s Optimize from Warehouse button; nothing moves until Apply.' }, { title = 'Crafting, contracts and coin', note = '• !cpx (/cpx): Conquest Point Exchange for all three nations\' gate guard shelves, allied sundries, and every regular merchant (1,400+ items), from anywhere.\n• !market (/dwah): player market from anywhere; no listing fee, buy orders hold your gil in escrow, claim proceeds on any character.\n• !craft (/craft): !craft skills | points | rules; !craft find <text> [page]; !craft book <craft> [page]; !craft craftable [warehouse] [craft] [page]; !craft recipe <id|name> | shopping <id|name>; !craft ladder <craft> [target]; !craft tally [reset] | alts.\n• !drift (/quests): Drift Board with 10 daily and 9 weekly contracts per level band paying Drift Coins (DC).\n• Contracts: !drift accept d1 | abandon d1 (d2–d10, w1–w9; d4/w4 CoP hunts, d9/w7 crafting, d10 fishing, w8 gathering, w9 Unleashed rally); !drift board 2 views band 1–5; !drift accept d1 2 takes a lower band\'s contract without a job change; !drift balance.\n• Augments: !drift augments (four daily offers plus two fixed shelves); !drift augment x1 <item>; !drift augment b1 <weapon> (Weapon Burst b1–b10, 5,000 Burst Tokens + 750 DC); !drift augment m1 <ring> (X-Magic: m1 Elements, m2 Grace, m3 Ruin, m4 Siphon, m5 Veil, same price).\n• Outfitter: !drift shelf war; artifact 25 DC, AF+1 100 DC, relic 125 DC, Empyrean +2 200 DC; !drift buy 21.\n• ArmsDealer: !drift arms dynamis (level 75 Dynamis ultimates, 250 DC); also artifact (25 DC), empyrean (1,000 DC), mythic (twenty level-99 non-afterglow Mythics, 1,000 DC each); !drift armsbuy 1101.\n• !drift pops: NM pop items for Dynamis hundred-pieces and Job Testimonies; !drift popbuy 2401 (each testimony must be a different job).\n• Jeweler: !drift jeweler; Wyrmking earrings 100 DC, Sea earrings 200 DC, Promathia rings 300 DC; !drift jewelbuy 3101.\n• Artisan: !drift artisan; guild key items 25–300 DC at the guild\'s required rank, Lu Shang\'s Fishing Rod 500 DC, Blue Magic Self-Destruct 50 DC and Final Sting 100 DC; add a guild word (e.g. cooking) or bluemagic; !drift artisanbuy 5101.\n• Special: !drift special; non-retail job unlocks 100 DC each (while that expansion is open), rename 200 DC, Zilart+Promathia story skip 500 DC, their DWPort waypoints 100 DC (after both stories), ToAU skip 250 DC (to Eternal Mercenary with key items, titles, rewards, Imperial Standing), ToAU waypoints 100 DC; WotG and SoA skips 250 DC each and waypoints 100 DC each while open (final reward left to choose).\n• !drift specialbuy rename Pld Roland (also story, toau, wotg, soa, waypoints, toauwp, wotgwp, soawp, or a job word); every purchase is priced first, then !drift confirm buys.\n• /quests feed off stops the colored kill feed (moved to chat, Window 2 on stock config); /quests rewards off does the same for FoV/RoE payouts.\n• !merc (/merc): list your characters for hire or hire others\' into your party.\n• !fame (/fame): fame level, points and progress for all 16 areas.\n• !sagheera: her Ancient Beastcoin ledger (Port Jeuno) from anywhere; !sagheera shop | buy <number>; !sagheera refund [amount] (default all); !sagheera claim collects a finished Artifact/relic +1 (no higher upgrades).\n• !imperial: convert Imperial Standing to Imperial Pieces at Ugrihd\'s (Aht Urhgan Whitegate) prices; !imperial rates; !imperial buy <bronze|silver|mythril|gold> [count]; max one stack per line, failures spend nothing.\n• !fish (/dwfishing): shows skill and the guild-rank skill cap and the catch that raises it; !fish next | rank; !fish route gives a 0–110 plan.' }, { title = 'Combat and the field', note = '• !scan (/dwscan): target\'s level and /check, drop table at server rates, resistances, immunities, aggro/link, and related quests; !scan 0 8 computes drops at Treasure Hunter 8. NMs and battlefield mobs hide level and difficulty.\n• !raid (/raid): 18 boss trials across 13 venues (Throne Room, Horlais Peak, Waughroon Shrine, Balga\'s Dais, Full Moon Fountain, Cloisters of Gales/Flames/Frost/Storms, four CoP shrines), tiers Easy to Savage plus a story-locked Promyvion tier; no orb or travel; 39 arenas run at once and full venues overflow to the next free one; clears pay Driftmarks for gear up to iLvl 109.\n• !arena (/arena): The Gauntlet in Qu\'bia Arena, up to 18 seats including alt-trusts; three foes spawn per minute, levels 101–150 (floors 1–50); each floor pays its number in Burst Tokens plus EXP and capacity points; death has no penalty.\n• !nemesis / !nem (/nemesis): 240 famous NMs (Leaping Lizzy to Kirin) at wild level +100, cap 160, in a private arena. Fees per player: Field 5,000 gil + 1 Job Testimony; Dungeon 10,000 + 2 different; Legend 30,000 + 3 different. Each player rolls the real drop table once at TH-0 (server drop multiplier applies). Also one to four random augments and trophies toward an iLvl 119 +1. Verbs: enter 12, buy 12, confirm, trophies, restart.\n• !unleashed / !unl (/unleashed): every two hours on even hours Eastern (4 PM, 6 PM, 8 PM…) a Legend-tier NM appears outdoors; location is announced. Passive for 10 minutes, then active; no claim, anyone in zone can join; near-immune until four different accounts engage; HP scales with online count and it regenerates per engaged character. !unl history.\n• !spoils (/spoils): EXP-paying kills have a small chance to give a normal (non-Rare/Ex) gear piece with 1–4 random augments directly to bags, rolled per player; pool of ~4,000 items levels 1–99 matched to mob level, about half picked for squad jobs; tougher mobs roll higher augments.\n• !tod (/tod): live respawn status for every timed NM (up/dead, time since death, seconds left); timers of 2+ hours persist through restarts.\n• !esper (/esper): EXP kills pay Magicite into 30 counters (8 elements, 22 jobs) for the mob\'s element, its job and yours; 10x for true NMs (unique, timer of an hour+). Magicite plus Esper Cores create the 31 FFVI Espers; a 32nd, Driftwood, needs all 31 mastered and unlocks a second slot.\n• !politics (/politics): elected Crown of Vana\'diel, Mayors of Bastok, San d\'Oria, Windurst and Jeuno, and Royal Treasurer on a four-week cycle: nominations week, campaign week, 72-hour secret ranked-choice vote, count, governing. A full nation mayor term is required before running for Jeuno, and a full Jeuno term before the Crown.\n• !geteffects lists status effects and remaining time on you or your target.\n• !signet gives your nation\'s Signet anywhere at your current rank\'s duration.\n• !sanction: free Sanction anywhere (normally 100 Imperial Standing); 3 hours plus 20 minutes per mercenary rank past the first; requires the mission "Immortal Sentries" (Naja Salaheem).\n• !sigil: free Sigil anywhere (normally 50 Allied Notes per perk); 3 hours plus 15 minutes per Allied Forces medal; requires the Bronze Ribbon of Service ("The Fighting Fourth", "Steamed Rams" or "Snake on the Plains").\n• !merits (/merits): server totals Weapon Skills 70, each job group 20, Attributes 210, Others 20, HP/MP 75; typed raise/lower beyond stock menu caps.\n• !toau (/toau): !toau lists BLU/PUP/COR levels; !toau blu <name> and !toau blu <name> set head_butt cocoon (also unset, clear) - squad BLUs cast only set spells; !toau pup <name> frame sharpshot | head valoredge | attach strobe | detach 3 | clear | deactivate; !toau cor and !toau cor <name> roll chaos_roll. Spells and attachments unlocked by one character apply account-wide.' }, { title = 'Your account and the server', note = '• !addons lists every add-on with its slash shortcut; a dead shortcut means it is disabled in the launcher\'s Addons tab.\n• !chars lists your account\'s characters with jobs and levels.\n• !build prints the server build info.\n• !leaderboard (/leaderboard): boards for total job levels, gil, kills, each craft and combined, buy-order fills, playtime, deaths, distance and more; no GMs or deleted characters; ties share rank 1. !leaderboard gil shows one board.' }, { title = 'The windows', note = '• /dw (dwhub): hub opening every add-on; /dw rail docks a compact button column in your chosen order.\n• /squad (dwsquad), /bags (dwbags), /warehouse (dwwarehouse), /dwah (dwah), /cpx (dwcpx), /jobs (dwjobs), /gambits (dwgambits, squad rules via dropdowns), /port (dwport).\n• /merc (dwmerc): also an arena where listed mercenaries duel 1v1 for a wager.\n• /tracker (dwtracker): quest and mission journal showing your current step.\n• /quests (dwquest), /fame (dwfame), /merits (dwmerits), /toau (dwtoau), /craft (dwcraft).\n• /parse (dwparse): party damage, healing, accuracy, crit and threat meter.\n• /dwchat (dwchat): color-coded, condensed chat log; off by default.\n• /dwcon (dwcon): con colors over nearby enemies and your target\'s real effects.\n• /dwscan (dwscan), /dwfishing (dwfishing), /raid (dwraid), /arena (dwarena), /nemesis (dwnemesis), /politics (dwpolitics), /unleashed (dwunleashed), /spoils (dwspoils), /tod (dwtod), /esper (dwesper), /leaderboard (dwleaderboard).\n• /report (dwreport): file a bug in game with your state attached.\n• /dwmacro (dwmacro): keeps your macro book and set through zoning and logout.\n• /dwengage (dwengage): auto-targets the party\'s next enemy when yours dies.' }, { title = 'Machine channels', note = '• Add-on windows talk to the server through: !dwa, !dwb, !dwc, !dwd, !dwe, !dwf, !dwg, !dwh, !dwi, !dwj, !dwk, !dwl, !dwm, !dwn, !dwo, !dwp, !dwq, !dwr, !dws, !dwt, !dwu, !dwv, !dww, !dwx, !dwy, !dwz, !dwsp, !dwto, !dwes.' } } },
    { name = 'Commands: news', group = 'Server', desc = 'DriftwoodXI\'s custom ! commands (squad, shared bags, rule sets, gear, quality-of-life) and what a new character starts with; newer posts override older ones. Source: https://xi.driftwoodgaming.com/news/every-command-on-one-page, https://xi.driftwoodgaming.com/news/your-login-commands-are-back, https://xi.driftwoodgaming.com/news/custom-commands-and-modules', steps = { { title = 'Every command, on one page (2026-08-12)', note = '• Full command list: xi.driftwoodgaming.com/commands (Ctrl+F searchable).\n• Covers 20 typed commands, e.g. !squad, !jobs, !port, !craft, !drift, !merc, !scan, !raid, !warehouse; these need no add-ons.\n• Also lists job-tag orders (!blm stone, !whm cure3 me, !war provoke) and all 19 add-on windows (/squad, /bags, /warehouse, /craft, etc.).\n• Each add-on window has an equivalent ! command; the typed version can do everything.' }, { title = 'Your login commands are back (2026-08-12)', note = '• Launcher 0.21.0: each addon set has a Custom commands box (Addons tab > Sets panel).\n• Enter one command per line (e.g. /fps 1, binds, camera tweaks); they run each login after that set\'s addons load.\n• Lines from your old default.txt were moved into the box; /load lines are rejected (use the toggles).\n• Sets are per-account; the launcher now warns when you edit a set no account or profile launches.\n• Your own default.txt is not changed.' }, { title = 'Custom commands (2026-07-27)', note = '• All custom commands begin with ! and are typed in chat.\n• All are open to every player; no GM, key item or quest required.' }, { title = 'Small commands', note = '• !mh or !moghouse: Mog House menu anywhere.\n• !home: warp to your starting nation\'s home point.\n• !chars: every character on the account with job and level.\n• !geteffects [name]: active effects and time left (yours or another player\'s).\n• !trustengage 0: trusts/squad wait for your first melee hit (retail); !trustengage 1: they start when you engage.\n• !build: shows the map server build; include it in bug reports.' }, { title = 'The squad', note = '• Summon up to 5 of your own characters as party members.\n• !squad set <1-5> <character> / !squad clear <1-5>: assign or empty a slot.\n• !squad list: registered members, who is out, job tags.\n• !squad call / !squad dismiss: summon or send home everyone.\n• !squad xp: experience each member has earned to its own character.\n• !squad engage / disengage / come: attack your target, stand down, regroup on you.' }, { title = 'Talking to one member', note = '• Members respond to job tags (!blm, !whm, !war); duplicates numbered by slot (!blm, !blm2).\n• !blm stone: cast on your target.\n• !whm cure3 me: target by name, me, another member\'s tag, or slot number.\n• !war provoke / !war fastblade: abilities and weapon skills use the same form.\n• !blm alone: what that member can do now; !whm spells / abilities / ws: full lists.\n• !pld engage / disengage / come / rest: controls one member.\n• !whm behavior passive: set one member\'s profile.' }, { title = 'Rule sets (gambits)', note = '• Ordered rules like "ally under 40% HP → cast the biggest Cure I can afford"; 14 preset sets ship with the server.\n• !squad rules: what each summoned member runs.\n• !squad rules presets [page]: the 14 presets, one per role.\n• !squad rules use <member> <set>: assign; all = everyone; when <job> ties it to a job.\n• !squad rules list / show <set>: your saved sets / one set in priority order.\n• !squad rules new <name> / copy <set> <name> / rename / delete <set>: manage sets.' }, { title = 'Account bags', note = '• One inventory spanning all your characters.\n• !squad who: your characters and bag fullness.\n• !squad bag <char> [where] [page]: view one character\'s bags.\n• !squad find <text>: search all bags on the account.\n• !squad send <char> <item> [qty] / !squad fetch <char> <item> [qty]: push to or pull from another character.\n• !squad box [char]: items waiting for pickup.' }, { title = 'Gear', note = '• Squad members auto-equip from their own bags whenever called.\n• !squad gear <char>: chosen gear and what it beat.\n• !squad equip <char> <slot> <item>: pin; use auto to unpin, none to leave empty.\n• !squad unpin <char>: clear all pins.\n• !optimizegear: run the same picker on your current character, scored for your main job; !optimizegear preview shows changes only.' }, { title = 'Window add-ons', note = '• Both install from the launcher Addons tab and send the same typed commands.\n• /dwbags (or /bags): searchable account-wide bags, transfers, per-member gear panel.\n• /gambits (or /dwgambits): dropdown rule-set editor with priority ordering.\n• !dwq and !dwg are the raw machine commands these add-ons send; useful for debugging.' }, { title = 'New character starting kit', note = '• All maps.\n• Hub home points unlocked: three nations, Jeuno and old-world town hubs; story-gated ones (Sky, Sea, [S] zones, Tavnazia, etc.) must be visited.\n• Key items: Pouch of Weighted Stones, Loadstone, Portal Charm, Bracelet of Verve (headcount-locked gates such as Garlaige\'s Banishing Gates and Quicksand Caves weight plates).\n• 5,000 gil.\n• Starter jobs WAR, MNK, WHM, BLM, RDM, THF; the other 9 unlock via their quests, all acceptable at level 1.\n• Unlocks on one character apply to all on the account at login: maps, home points, outpost warps, survival guides, mounts, learned spells, jobs, weapon skills.' }, { title = 'Merits, job points and trusts', note = '• Merit points from level 75, job points at 99.\n• No Genkai/limit break quests; level cap is 99 from the start.\n• Trust: San d\'Oria, Trust: Bastok, Trust: Windurst quests open at level 5 and grant the nation permit; more trusts come from trading cipher items.\n• Squad members are your own characters (own jobs, gear, experience, rule sets); trusts are game-controlled NPCs.\n• Spells are bought, dropped or learned; weapon skills unlock by skill level.' } } },
    { name = 'Add-ons and the allowed list', group = 'Server', desc = 'Which Ashita add-ons and plug-ins DriftwoodXI permits, how they are judged, and how to open the server\'s own add-ons. Source: https://xi.driftwoodgaming.com/addons, https://xi.driftwoodgaming.com/features/dwchat, https://xi.driftwoodgaming.com/features/dwcon, https://xi.driftwoodgaming.com/features/dwhub, https://xi.driftwoodgaming.com/features/dwleaderboard, https://xi.driftwoodgaming.com/features/dwmacro, https://xi.driftwoodgaming.com/features/dwparse, https://xi.driftwoodgaming.com/features/dwreport, https://xi.driftwoodgaming.com/features/dwscan, https://xi.driftwoodgaming.com/features/dwtracker, https://xi.driftwoodgaming.com/news/allowed-addons-and-plugins, https://xi.driftwoodgaming.com/news/nine-addons-and-how-to-open-them', steps = { { title = 'The rule', note = '• 158 entries allowed: 144 Lua add-ons, 14 native plug-ins (Ashita).\n• Listed = allowed in any combination; unlisted = against the terms of use.\n• Unlisted usually means never reviewed; ask and approved items get added.\n• Everything the launcher installs is already allowed; the same list is on the launcher\'s Allowed tab.' }, { title = 'The four questions', note = '• An add-on must answer no to all four:\n• 1. Does it play with nobody at the keyboard?\n• 2. Does it reach unearned or unvisited content?\n• 3. Does it reveal what the game hides from that job or player?\n• 4. Does it override a server decision?\n• Purely visual, audio, timing or layout changes pass automatically.' }, { title = 'DriftwoodXI\'s own', note = '• dwah, dwbags, dwcon, dwcpx, dwcraft, dwengage, dwfame, dwfishing, dwmerits, dwtoau, dwgambits, dwjobs, dwarena, dwnemesis, dwunleashed, dwhub, dwspoils, dwtod, dwchat, dwesper, dwpolitics, dwleaderboard, dwmacro, dwmerc, dwparse, dwport, dwquest, dwraid, dwreport, dwscan, dwsquad, dwtracker, dwwarehouse (all LUA).\n• Each also has a typed command equivalent.' }, { title = 'Interface, HUD and windows', note = '• LUA: HXUI, XIUI, xivbar, statustimers, timers, tTimers, recast, partybuffs, tparty, distance, targetlines, crosshair, clock, zonename, move, imguistyle, hideui, hideparty, hideconsole, cleancs, minimapmon, mapdot, partyfinder, FancyTrusts, GlamourUI, trainmon, Balloon.\n• DLL: minimap, Nameplate.\n• mapdot only draws entities already sent to your client; off-job zone tracking is banned.\n• partyfinder is allowed but does nothing here.\n• GlamourUI: install from the release zip (repo download lacks files).\n• trainmon counts Fields/Grounds of Valor regime kills from the chat log.' }, { title = 'Combat information and parsers', note = '• LUA: actionparse, simplelog, checker, mobdb, chains, petinfo, easyTH, LootScope, TrackMeBooty, RollTracker, blumon, geocompass, filterscan, points, gainz, ventures, sparks.\n• filterscan only filters a widescan your job can already do.' }, { title = 'Gear, jobs and macros', note = '• LUA: luashitacast, equipmon, invmon, itemwatch, find, blucheck, blusets, pupsets, trimspells, quicksets, fastswap, macrofix, tHotBar, Upcast.\n• DLL: LegacyAC, FindAll, Shorthand, Sequencer.\n• quicksets: server equip limits still apply.\n• Sequencer: allowed only when you press the key; self-restarting or chat-triggered sequences are banned.\n• tHotBar: install from the release zip (repo download leaves the font submodule empty).\n• Upcast sends the highest known tier as a normal /ma or /ja line.' }, { title = 'Chat, sound and logging', note = '• LUA: timestamp, filters, filterless, chatfix, instantchat, stfu, tokens, logs, links, ime, customcolors, namecolors, chatmon, chime, changecall, autorespond, Fancychat.\n• chatfix is allowed but the launcher won\'t load it: it breaks chat on this server (drops first letter, misroutes tells).\n• autorespond (away tell replies) is allowed.' }, { title = 'Menus, travel and convenience', note = '• LUA: enternity, stepdialog, instantah, ahgo, ahcolors, allmaps, cartographer, sellit, craftmon, autojoin, cfhblock, debuff, casper, nolock, ButterFeet, config, VanaCompass.\n• ahgo opens the AH window remotely, but only works in zones with an auction house.\n• debuff, casper, nolock, ButterFeet are client-side only; server still checks speed, range and cancels.' }, { title = 'Windows, logins and sessions', note = '• DLL: Multisend.\n• LUA: activemon, autologin, logincmd, hideobs.' }, { title = 'Cosmetic, camera and models', note = '• LUA: xicamera, noname, renamer, chamcham, clearcolor, singlerace, sexchange, bigmode, NoMount.\n• DLL: toon, screenshot, XIPivot.\n• bigmode is allowed but fails on load with the shipped Ashita, so the launcher omits it.\n• XIPivot: DAT overlays go in polplugins\\DATs; manage in game with /pivot.' }, { title = 'Performance and plumbing', note = '• LUA: fps, freemem, affinity, aspect, drawdistance, mipmap.\n• DLL: addons, thirdparty, hardwaremouse, winefix.' }, { title = 'Not allowed', note = '• Unlisted items are banned by default; refusal categories:\n• 1. Unattended play: fighting, healing, gathering, crafting, selling or travel bots, command repeaters, chat-triggered runners, external heal/fishing bots.\n• 2. Unearned access: door/gate openers, warps to unvisited places, unlocked travel, field Mog House functions, acting while dead.\n• 3. Hidden information: invisible/GM-hidden entities, off-job zone tracking, reading other players beyond what they show.\n• 4. Overriding the server: editing combat state, forged packets, spoofed distance/recast/TP/results, attacks on players or server.\n• 12 add-ons/tools are named as not allowed (door openers, warp forgers, hidden-entity renderers, off-job trackers, bots).' }, { title = 'Asking about an add-on', note = '• Ask in Discord or use /dwreport in game with a source link and what it does for you.\n• Do not run it while waiting for staff\'s answer.\n• Launcher Addons tab flags banned add-ons and marks unreviewed ones Ask first.' }, { title = 'Server add-on features', note = '• DWChat (/dwchat): colour-coded battle lines and folded spam; off by default.\n• DWCon: pearl beside each enemy nameplate in /check colour; silver for NMs and battlefield mobs.\n• DWHub (/dw): launcher window for all DW add-ons with Open and Load buttons; /dw <word> searches (e.g. /dw market).\n• DWLeaderboard (/leaderboard or /lb): rankings for job levels, gil, kills, crafts, market buy orders, playtime, deaths, distance, Nemesis kills.\n• DWMacro: fixes macros losing settings on job/area change or relog.\n• DWParse: damage parser; since 1.1.0 its Threat tab shows server enmity per player.\n• DWReport: in-game bug reports showing what is sent.\n• DWScan: target a monster and Scan for drops, resistances, aggro, level, /check difficulty and spawn level range.\n• DWTracker: accepted quests and missions with next-step instructions; includes Aht Urhgan content.' }, { title = 'Allowed list posted (2026-08-01)', note = '• From this date, unlisted add-ons are against the terms of use.\n• List is on the launcher Allowed tab and at xi.driftwoodgaming.com/addons.\n• If you only use what the launcher installs, no action is needed; check anything added via Install from GitHub.' }, { title = 'Opening the main add-ons (2026-07-30)', note = '• dwhub: /dw — index of all DW add-ons.\n• dwsquad: /squad — fill 5 slots with your characters, call or dismiss.\n• dwbags: /bags — account-wide bags and transfers without logging in the other character.\n• dwwarehouse: /warehouse — 1,000 shared slots, Stash All, crafting kits, Trash.\n• dwah: /dwah — AH listings with prices, sell from anywhere with no listing fee, escrowed buy orders, claim proceeds on any character.\n• dwcpx: /cpx — Conquest Point Exchange (all three nations, every rank, allied sundries) plus 1,400+ regular merchant items, from anywhere.\n• dwjobs: /jobs — change main/support job for you and squad slots anywhere; save named lineups.\n• dwgambits: /gambits — rule editor with 43 ready-made sets.\n• dwport: /port — all unlocked teleports (home points, survival guides, outposts, teleport spells); locked ones shown greyed.\n• dwmacro and dwengage run in the background with no window.' }, { title = 'When a command does nothing', note = '• Unknown command means the add-on is off.\n• In the launcher: Addons tab, choose your launch set, enable it (all are on in the Default set).\n• In game: /addon load <name>, e.g. /addon load dwhub, dwsquad, dwbags, dwwarehouse, dwah, dwcpx, dwjobs.\n• !addons prints the add-on list in game; /servmes reopens the login welcome message.\n• Report problems with /report or at discord.gg/DriftwoodGaming.' } } },
    { name = 'Your squad (alt-trusts)', group = 'Server', desc = 'How DriftwoodXI\'s squad system works: summoning your own alts as trusts, writing their combat rules, hiring them out, and the patch changes that affect them. Where posts disagreed, the latest one is used. Source: https://xi.driftwoodgaming.com/features/dwengage, https://xi.driftwoodgaming.com/features/dwgambits, https://xi.driftwoodgaming.com/features/dwmerc, https://xi.driftwoodgaming.com/features/dwsquad, https://xi.driftwoodgaming.com/news/heavenward-howl-carol-ii-and-squad-gear, https://xi.driftwoodgaming.com/news/dread-beasts-and-squad-tutoring, https://xi.driftwoodgaming.com/news/mercenary-battles-and-faster-seals, https://xi.driftwoodgaming.com/news/nemesis-eased-jobs-for-sale-and-your-squads-bows, https://xi.driftwoodgaming.com/news/squad-weapon-skills-unblocked, https://xi.driftwoodgaming.com/news/alliances-for-your-squads, https://xi.driftwoodgaming.com/news/squad-enters-the-burning-circle, https://xi.driftwoodgaming.com/news/ten-sets-that-fight-with-both-jobs, https://xi.driftwoodgaming.com/news/pick-your-squads-weapon-skills, https://xi.driftwoodgaming.com/news/your-squads-pets-come-along-now, https://xi.driftwoodgaming.com/news/the-fight-finds-you, https://xi.driftwoodgaming.com/news/your-characters-keep-working, https://xi.driftwoodgaming.com/news/write-how-your-squad-fights, https://xi.driftwoodgaming.com/news/squad-your-own-characters', steps = { { title = 'DWSquad: set up a squad', note = '• Up to five characters from your own account can be registered to slots 1-5 and summoned as party members (ownership is checked on every action).\n• Members use the best gear they carry, their levelled jobs and the spells they know; gear is re-picked at every summon for the current job.\n• Register with !squad set 1 Yakapo (and so on), then check !squad list.\n• !squad list shows who is registered, who is out, jobs, levels and each member\'s command tag; the tag is shown nowhere else.\n• Summon with !squad call out in the field; send them home with !squad dismiss.\n• All five slots work from the start; Rhapsodies of Vana\'diel does not limit the count.' }, { title = 'Squad commands', note = '• !squad set <1-5> <character> - register a slot.\n• !squad clear <1-5> - unregister a slot.\n• !squad list - roster, who is out, tags.\n• !squad call / !squad dismiss - summon or dismiss everyone.\n• !squad engage - all attack your target; !squad disengage - all stop and stay stopped.\n• !squad come - regroup on you (also releases disengaged members).\n• !squad rest - stop and recover HP/MP with a readout.\n• !squad xp - each member\'s experience progress.\n• Individual orders use the member\'s tag, e.g. !whm cure3 me, !war provoke.' }, { title = 'Macros', note = '• Squad commands are chat lines, so a macro is /say followed by the command; a mistyped command is spoken aloud.\n• Suggested page: /say !squad call, /say !squad engage, /say !squad disengage, /say !whm cure3 me, /say !war provoke, /say !squad come.' }, { title = 'Experience and tutoring', note = '• While a member is out, your experience is copied to it at 100% as a bonus; you lose nothing.\n• Members get what you were actually credited, not the chat figure; one award can raise at most one level and the excess is lost.\n• Only experience earned while members are out counts; a dead member stops earning, and a capped member earns nothing.\n• Levels transfer but combat skills do not; a squad-levelled character logs in with low weapon skills. Gear still scales.\n• !squad tutor converts unspent merits to squad experience: each merit is 10,000 experience split evenly (rounded down) across members out: 1 = 10,000, 2 = 5,000, 3 = 3,333, 5 = 2,000 each.\n• Capped members still take a share and gain nothing; the command names them. Tutor with one member out to give it the full amount.\n• !squad tutor with no number previews merits and recipients.' }, { title = 'Account-wide unlocks and door key items', note = '• Home points, maps, outpost warps, teleports, travel key items, spells, unlocked jobs and weapon skills copy to every character on the account at its next login.\n• Every character starts with four key items for headcount doors: Pouch of Weighted Stones (Banishing Gates, Garlaige Citadel), Loadstone (weight plates, Quicksand Caves), Portal Charm (sealed portal, Inner Horutoto Ruins), Bracelet of Verve (operating levers, Halvung).\n• Other key-item doors (Yagudo Torch, Temple Knight Key, Paintbrush of Souls, Moongate Pass, Gates of Halvung) must still be earned.' }, { title = 'Loot, zones and small print', note = '• Alt-trusts never lot; every drop goes to you.\n• No squad in towns or safe zones (Mog Garden, Adoulin, Whitegate, Al Zahbi etc.), Limbus, Walk of Echoes, Provenance or Mordion Gaol.\n• !squad call is refused if you or your party is engaged or has hate; call before pulling.\n• All trusts spawn with Summon Sickness for 60 seconds: -25% damage dealt, +25% damage taken, -25% cure potency.\n• A summoned character cannot log in (you get disconnected); dismiss it first.\n• Members vanish at zone lines; one !squad call brings them back with the same behavior profile.\n• Names show unchanged (no room for job tags in 15 characters).\n• Still untuned: Bard songs, Geomancer indi-spells, Ninja Utsusemi and most of Dancer; they get basic movement, weapon skills and self-heals.' }, { title = 'Alliances (2026-08-14)', note = '• Squads may now join alliances: each player plus up to five alts is one party, up to three parties and 18 characters.\n• Two full squads make 12; a normal six-player party can ally with a squad party; six-seat rule still applies per party.\n• Stock trusts are no longer dismissed when an alliance forms.\n• The client greys out invite buttons with summons out, so use typed commands: !padd <character> (party invite), !pally <character> (alliance invite), !join (accept), !decline.\n• Alliance magic like Curaga and alliance buffs reach allied squad members; single-target help works on them too.\n• Level sync still targets players only; battlefield rules unchanged.\n• The search window\'s join-request button does not work on this codebase; use the typed commands.' }, { title = 'Battlefields (2026-08-13)', note = '• Battlefields that block trusts now admit your squad, orb fights included; regular trusts are still blocked.\n• Enter the burning circle first (entry dismisses trusts), then !squad call inside.\n• Players plus members must fit the fight\'s cap (3-cap = you + 2); members are taken in slot order.\n• Members are level-capped like you (a 75 WHM becomes WHM 30 in a BCNM30).\n• Calling after the fight starts is refused.\n• Mercenary guests follow the same battlefield rules; squad pets are refused at battlefield entry.' }, { title = 'Pets (2026-08-06)', note = '• Summoner: casts avatars it has learned, picks the best itself, or pin one with !smn avatar shiva.\n• Dragoon: Call Wyvern, using the character\'s wyvern name.\n• Beastmaster: Call Beast uses the jug in its ammo slot; if none, fix with !squad send and !squad equip; Ready moves follow the Sic/Ready timer.\n• Puppetmaster: Activate uses the character\'s real automaton build and keeps maneuvers matched to the frame.\n• Commands: !drg callwyvern, !smn shockstrike, !smn assault / !smn retreat, !bst petskills, !<tag> summon, !<tag> dismisspet, !squad behavior defensive.\n• Rule keyword petout means summon the pet and keep it out; evoker, lancer, wrangler and artificer sets include it.\n• Pets use the member\'s synced level and leave when the member is dismissed, dies or zones. Astral Flow pacts are unavailable.' }, { title = 'Weapon skills (2026-08-06 and 2026-08-17)', note = '• Quest weapon skills (e.g. Decimation) unlocked by any character on the account work for every member meeting weapon, job and skill needs.\n• Member weapon-skill caps now match a real player of that job and level (ranged included), so e.g. Raging Rush (200 skill) appears at the normal level.\n• Choose up to four weapon skills per rule set, in order; the first opens on full TP and all may close skillchains: !squad rules posture My Samurai tpskill tachi: gust, tachi: jinpu (use any to reset).\n• !squad rules posture My Samurai tpwhen attp holds TP for a skillchain but spends it once it hits the hold amount.\n• !squad rules posture My Samurai tphold 2000 sets that amount (1000-3000); random never fires below it and opener waits for a partner to reach it.\n• The /gambits posture bar has the same controls (first slot = opener, (any) clears); share codes carry picks and hold amount; older codes still import.' }, { title = 'DWGambits: rule sets', note = '• A rule set is an ordered list of who / when / what rules; members check it top to bottom every 2-3 seconds in combat and do the first match.\n• Example: !squad rules add My Medic party hp<40 cure casts the strongest Cure the member can afford at that moment.\n• Use a shipped set: !squad rules use whm medic, !squad rules use pld vanguard; list them with !squad rules presets.\n• Copy one to edit: !squad rules copy medic My Medic; or start empty: !squad rules new My Medic.\n• More examples: party status:sleep cure1; party nostatus:protect protectra retry:60; enemy nostatus:dia dia; posture My Medic swing never.\n• Earlier rules win; manage with !squad rules show, !squad rules move My Medic 4 to 1, !squad rules del My Medic 6.\n• who words: self party master enemy tank melee caster ranged hate fallen.\n• when words: hp<40 hp>=80 mp>=50 tp>=1000 lvl>=50 hpmissing>=400 status:sleep nostatus:protect erasable family:undead.\n• /gambits opens a point-and-click editor that issues the same commands; unusable rules are greyed with the reason.' }, { title = 'Shipped sets', note = '• 40 sets ship free.\n• Basics: aggressive (cure late, all offensive abilities), defensive (cure early, defensive abilities; the default), passive (does nothing), off (no rules but still melees and uses TP), vanguard (PLD hate tank), medic (WHM healing/buffs, no offense), battlemage (RDM cure/debuff/nuke, keeps half MP for cures).\n• Dual-job sets (2026-08-07): aegis PLD/NIN, oracle WHM/SCH, disruptor BLM/DRK, phantom NIN/WAR, deadeye COR/RNG, warmonger SAM/WAR, beastdancer BST/DNC, chanter BRD/WHM, nightblade THF/NIN.\n• Support jobs run at main-job level, so sets can use both jobs\' abilities.\n• Pet sets: wrangler (BST), lancer (DRG), evoker (SMN/WHM support), artificer (PUP counter-tank).' }, { title = 'Share codes and limits', note = '• !squad rules export My Medic prints a code; !squad rules import <code> loads it, optionally followed by a new name.\n• Sample code (Pocket Healer, six-rule backup healer for any cure job): !squad rules import dwg1At2AQEGfwANUG9ja2V0IEhlYWxlcgYQVQQIISUERIIQWMQIISlQQJUeCUqSBLjwylUQLkeA63Y\n• Long sets export as two lines; both are needed. Imported rules are server-validated.\n• Limits: 24 rules per set (shipped sets exempt), 16 sets per account, 2 conditions per rule.\n• Sets belong to the account; assign per job with !squad rules use Yakapo My Medic when whm.\n• Edits apply instantly to members out. !squad rules shows what each member runs; !squad rules help shows full grammar.' }, { title = 'Rule set gotchas', note = '• Rules only run in combat, so no buffing while idle.\n• Weapon skills are posture settings, not rules: tp off, tpwhen, tpuse.\n• party picks the first passing member in fixed order, so put emergency rules above normal ones.\n• timer:30 counts whenever the rule is checked; retry:30 counts from when it fired; use retry for rate limits.\n• Rules for unlearned spells are kept and reported; !squad rules report <member> lists live vs waiting rules.\n• Report misbehaving rules with the set from !squad rules export.' }, { title = 'DWMerc: hiring a mercenary', note = '• Browse with !merc board or /merc; inspect with !merc info Yuna.\n• !merc hire Yuna 2 shows a quote; repeat the line or type !merc confirm to pay.\n• Payment is upfront and non-refundable; hours run from payment even if you dismiss or log off.\n• !merc call Yuna adds it to your party; pick one of the owner\'s loadouts; it obeys tags and behavior commands; drops are yours.\n• Any level may hire any level; the mercenary syncs down with its gear.\n• When hours expire mid-fight it finishes the fight; the next call is refused.\n• Hired mercenaries run sub job at main level and use the character\'s merit, mythic, empyrean, relic and quest weapon skills and learned abilities (owners must re-list once to capture them).' }, { title = 'DWMerc: listing and earnings', note = '• From a different character on your account (the listed one must be offline): !merc list Ayame 5000 8 My Medic = 5,000 gil/hour, up to 8 hours, My Medic rules.\n• Up to three rule sets per listing; the hirer picks one and cannot edit it.\n• Gear, level, spells and rules are frozen at listing; re-list to update.\n• One contract per character at a time; listing is locked and off the board while contracted.\n• Your squad can still summon that character free. You cannot hire your own listing.\n• !merc earnings shows each contract; !merc claim pays the balance to your online character.\n• The house takes 35% of each contract (removed from the economy). Owners get no XP from being hired.\n• Report gil issues with !dwr.' }, { title = 'Mercenary Battles (2026-09-16)', note = '• New Battle tab on the mercenary board: a listed mercenary fights another player\'s one-on-one for a wager, in Ru\'Lude Gardens, five minutes after the challenge is answered.\n• Owners do not control the fight; the mercenaries follow their rule sets.\n• Requires a listed mercenary (/merc or !merc list <character> <rate> <hours> <set>); it stays hireable; one live battle per character.\n• !merc battle withdraw <number> cancels an unanswered challenge with full refund; !merc battle help lists commands.\n• Hall of Records: win 3 points, draw 1, loss 0; view on the Battle tab or !merc battle records.\n• Arena takes 10% of the pot when there is a winner; the Royal Treasurer can set it with !politics battle <pct> (5-20, once per 20 hours, Crown can veto).\n• Update dwmerc, dwpolitics and dwscan in the launcher.' }, { title = 'DWEngage auto-target (2026-08-03)', note = '• When your target dies, the server picks the nearest enemy with hate on your party (players, trusts, pets) in any direction within about 28 yalms and turns you to it with weapon drawn.\n• Slept mobs and other players\' mobs are never chosen; /assist is unchanged.\n• The in-game Auto Target option still controls it; off = no retargeting.\n• The dwengage addon is installed and on by default; /dwengage toggles it per session; disable it permanently in the launcher\'s Addons tab.' }, { title = 'Patch 2026-10-15: Heavenward Howl, Carol II, squad gear', note = '• Update dwwarehouse in the launcher; the rest is server-side.\n• Heavenward Howl: Endrain (bright moon, drains HP up to 15% of melee damage) or Enaspir (dark moon, MP up to 5%); strength follows moon phase; both are in the gambit status picker.\n• Carol II (BRD 90+): all eight elements, +100 resistance and a chance to nullify that element.\n• Adloquium (SCH): Regain on you or an ally; Accession spreads it. Animus Augeo / Minuo (SCH): Enmity +20 / -10 for 3 minutes.\n• Different-element Carols and different-stat Etudes now stack; re-singing refreshes that song. Carol is in the gambit status picker.\n• Squad members now proc weapon additional effects (Algol +1, Aspir Knife +1, Nadrs +1, Sirocco Kukri +1, Sonic Knuckles +1, Nemesis Blind Knife, Lockheart +1, others) and gear spikes (Suzaku\'s Sune-Ate +1, Nemesis Wyvern Helm).\n• Squad SMN get perpetuation reduction gear (Nirvana, Glyphic Horn, Glyphic Doublet, Campestres\'s Cape); BLU alts without Dual Wield skip off-hand swords.\n• Gear fixes: Tempus Fugit (+1) Defense and Haste; Moonbeam Ring HP+100, Accuracy+5, Attack+5, Store TP+3, Damage taken -4%; Arcana Breaker and A l\'Outrance additional effects; Trilling Dagger +10% light magic damage and Attack+10 while silenced (+1: +15%); Charm+ gear (Atlaua\'s Ring) works; Yain: Ichi and Pax lower enmity.\n• Blue Magic bursts (Everyone\'s Grudge, Acrid Stream, Blazing Bound, Leafstorm, Thermal Pulse, Charged Whisker, Osmosis) show damage again.\n• DWWarehouse: listing shows row and item ID; !warehouse find <text>; /wh hover shows the !warehouse pull command; !warehouse sendto <char> <row> and !warehouse vendor <row> move the whole row if no quantity is given.\n• DWQuest: wild wyverns such as Skoffin (Bhaflau Thickets) count for Wyvern kill contracts.' }, { title = 'Patch 2026-10-05: Dread Beasts', note = '• Ten of each Dread Beast spawn per Wings of the Goddess zone, fightable once that expansion opens; designed as long fights with better pay.\n• Listed: Dread Ladybug (East Ronfaure [S]), Dread Gnole (Jugner Forest [S]), Dread Monoceros (Batallia Downs [S]), Dread Wivre (Grauberg [S]), Dread Peiste (Pashhow Marshlands [S]), Dread Skywyrm (Rolanberry Fields [S]), Dread Rafflesia (Fort Karugo-Narugo [S]).\n• Boompadu and other Acrolith NMs use Detonating Grip, Dire Straight, Sinker Drill and Dismemberment again (Sinker Drill learnable); arm loss changes available moves.' }, { title = 'Patch 2026-09-16: other changes', note = '• Beastmen\'s Seal, Kindred\'s Seal and Kindred\'s Crest drop cooldown per party cut from 5 to 2 minutes; geodes and avatarites stay at 5.\n• Lucid Wings and party-wide temporary items (mists, powders, Cleric\'s Drink, Fanatic\'s Powder, Fool\'s Powder, Altana\'s Repast) now affect alt-trusts.\n• Jump, Spirit Jump and Soul Jump give TP to alt-trust Dragoons, with wyvern bonus.\n• Drift Board Outfitter Costume page: 24 level-1 all-job glamour pieces at 50 Drift Coins each; list with !drift shelf costume.\n• Four Fei\'Yin Shadows lottery camps now work; /scan names the placeholder and its window for lottery pops.\n• DWRaid fuse chains announce each bomb\'s fuse: 300, 240, 180, 120, 90 seconds.' }, { title = 'Patch 2026-09-13: Nemesis, Drift Board, squad fixes', note = '• Nemesis fights cap at level 160. Fees: Field 5,000 gil + 1 Job Testimony; Dungeon 10,000 + 2 different; Legend 30,000 + 3 different.\n• Drift Board payouts up about 20%: family daily 10 coins, bounty 30, weekly 50+, server-wide contract 72.\n• Special tab sells each non-retail job unlock for 100 Drift Coins: Paladin, Dark Knight, Beastmaster, Bard, Ranger, Summoner, Samurai, Ninja, Dragoon.\n• DWCon target debuff bar now reads effects from the server.\n• Squad Ninjas no longer cast Ichi over Ni shadows; squad ranged attacks use the character\'s own stats and merits; party area buffs now need range for trusts and pets.\n• dwgambits 1.14.2 fixes saving Sings-to and Seconds-left on Bard rules.\n• Newly allowed addons: Upcast, tTimers, Balloon.\n• Daily limits per account: 300 fishing catches, 150 chocobo digs, reset at Japanese midnight.' }, { title = 'Other notes (2026-08-14 and 2026-08-17)', note = '• Curio Vendor Moogle equipment prices are now ten times higher; medicine, ammo, tools, food, scrolls and keys unchanged.\n• Server contracts pay every contributor even if offline; on your next login you get a one-time message with the kill and Drift Coins earned.' } } },
    { name = 'Rates and progression', group = 'Server', desc = 'DriftwoodXI\'s server rates, the DWJobs and DWMerits add-ons, the Ascension limit-point bank and Mastery pages, and patch notes, ordered add-ons first and then newest patch first; when two posts disagree, trust the newer one. Source: https://xi.driftwoodgaming.com/features/dwjobs, https://xi.driftwoodgaming.com/features/dwmerits, https://xi.driftwoodgaming.com/news/ascension-iii-spend-your-job-points, https://xi.driftwoodgaming.com/news/ascension-ii-larceny-and-black-mage-melee, https://xi.driftwoodgaming.com/news/ascension-your-limit-points-are-a-currency, https://xi.driftwoodgaming.com/news/they-notice-you-later, https://xi.driftwoodgaming.com/news/if-it-pays-it-counts, https://xi.driftwoodgaming.com/news/every-swing-counts, https://xi.driftwoodgaming.com/news/one-account-sixteen-characters, https://xi.driftwoodgaming.com/news/launch-balance-pass, https://xi.driftwoodgaming.com/news/rates-and-progression, https://xi.driftwoodgaming.com/news/welcome-to-driftwoodxi', steps = { { title = 'DWJobs', note = '• Add-on that changes the main and sub job of any of your characters, wherever you are in Vana\'diel.' }, { title = 'DWMerits', note = '• Open with /merits; it replaces the stock merit menu and lets you assign past its caps.\n• Real category totals: Weapon Skills 70, each job group 20 on every job, Attributes 210, Others 20, HP/MP 75.\n• Shows each entry\'s true cap and next-step cost, plus raise/lower buttons.\n• Ships in the launcher\'s Default set; load mid-session with /addon load dwmerits.\n• Typed equivalents: !merits, !merits bank, !merits ascension, !merits ascend vitality, !merits convert all, !merits jp whm.\n• Job Points tab: any job\'s job points, capacity points, each category with next cost and a raise button, and the gift ladder with unlocked gifts highlighted.' }, { title = 'Ascension III (2026-10-12)', note = '• Update dwmerits via the launcher; the rest of the patch is server-side.\n• Open the Ascension III tab on /merits or type !merits ascension 3.\n• Paid with job points, not limit points: 500 job points per rank, every rank.\n• Eight lines, ten ranks each: 5,000 job points per line, 40,000 for the page.\n• Choose the paying job under Pay with; any job with points can pay, and the tab defaults to your current job.\n• A job can hold only 500 unspent job points, so one full job buys one rank.\n• Spent job points leave that job and no longer count toward its mastery or gifts; the tab warns if the job is not mastered.\n• Ranks are permanent, work everywhere, and pass to every squad member you call.\n• Relentlessness: +1% double attack per rank.\n• Keenness: +1% critical hit rate and +1% critical hit damage per rank.' }, { title = 'Ascension III patch - other changes', note = '• Unleashed world bosses drop Esper Cores 10% of the time (was 20%); pity counter unchanged.\n• Magicite is 20% cheaper at every tier.\n• Gambit status picker now includes Etude and Scherzo.\n• X-Magic: Song\'s follow-up message no longer wrongly reports "gains the effect of KO".' }, { title = 'Ascension II (2026-09-17)', note = '• Update dwmerits and dwmerc via the launcher; the rest is server-side.\n• Open the Ascension II tab or type !merits ascension 2; lines are bought with gil like page one. Page one was repriced and already-bought ranks were kept.\n• Bastion: +10 defense, +1 evasion per rank, 20 ranks.\n• Warding: +1 magic defense, +1 magic evasion per rank, 20 ranks.\n• Attunement: +1 to all eight elemental resistances per rank, 20 ranks.\n• Composure: +1 critical hit evasion, +5 critical defense per rank, 20 ranks.\n• Celerity: +1% gear haste, +1% fast cast per rank, 10 ranks.\n• Sorcery: +10 magic damage, +1% magic critical rate per rank, 10 ranks.\n• Serenity: +1 subtle blow, +1% cure potency per rank, 10 ranks.\n• Persistence: +2% enhancing and enfeebling duration per rank, 10 ranks.' }, { title = 'Duration bug fixes (2026-09-17)', note = '• A milliseconds/seconds mix-up was fixed in several places.\n• Larceny stealing Invincible no longer leaves it on the thief for 8+ hours.\n• Modus Veritas now halves a Helix instead of stretching it to about 50 hours.\n• Dancer steps on an already-stepped target add 30 seconds instead of always granting the 2-minute cap.\n• Emetic Discharge and Wanion now transfer ailments with correct durations and ticks.\n• Some monster two-hours (e.g. Bozzetto Breadwinner\'s Hundred Fists) no longer end after a fraction of a second.\n• The Abyssea conflux surveyor\'s visitant buffer is 4 seconds again, not 4 ms.\n• Two GM time-extension commands no longer add 1,000x too much.' }, { title = 'Black Mage weapon ranks (2026-09-17)', note = '• Staff: A+ (was B-), cap 424 at 99.\n• Scythe: B- (was E), cap 388 at 99.\n• Dagger: B- (was D), cap 388 at 99.\n• No other skills or jobs changed; Black Mage squad members use the new caps automatically.' }, { title = 'Squads and mercenaries (2026-09-17)', note = '• Squad members\' melee accuracy, defense and evasion now come from their own skill, stats and gear, the same as a player\'s.\n• Manual weapon-skill rules in /squad can use TP as a condition, e.g. Check me, act on the enemy / TP at least 1750 / Geirskogul.\n• Blue Mage members can use Unbridled Learning: Unbridled spells need no set slot and are cast only while the effect is active.\n• Ten menu-abbreviated Blue/Bard spells (e.g. Quad. Continuum) can be chosen in the gambit editor and typed at !blu.\n• Squad Summoner\'s Elemental Siphon now requires a spirit; it no longer drains a summoned avatar\'s MP every five minutes.\n• Mercenary listings now freeze the entire rule set, so hand-called weapon skills and count-gated targets work and disabled rules stay off.\n• End a hire early with !merc release <name> or the Release button in /merc; owner keeps full pay, hirer gets no refund, and it asks for confirmation twice.\n• Mercenary duel contestants now move into melee range.' }, { title = 'Dynamis NMs (2026-09-17)', note = '• Named monsters in all Dynamis zones now spawn immediately each time their placeholder dies.\n• Use /report for problems.' }, { title = 'Ascension limit-point bank (2026-09-01)', note = '• At 99 the limit bar still awards a merit at 10,000 as before; every limit point earned is also banked permanently, even with a full bar or capped merits.\n• The bank is per character, not per account.\n• Spend it on Mastery tiers (permanent, inherited by every squad member you call) or on merit points at 10,000 each.\n• Mastery tiers grow in cost (tier 3 costs three times tier 1).\n• Vitality: +20 max HP per tier, 25 tiers.\n• Spirit: +15 max MP per tier, 25 tiers.\n• Prowess: +1 STR, DEX, VIT, AGI, INT, MND, CHR per tier, 20 tiers.\n• Precision: +2 accuracy, ranged accuracy, magic accuracy per tier, 20 tiers.\n• Ferocity: +2 attack, ranged attack, magic attack per tier, 20 tiers.\n• Bulwark: -1% damage taken per tier, 10 tiers.\n• Vigor: +1 Regen and +1 Refresh per tier, 10 tiers.\n• Devastation: +1% weapon skill damage per tier, 15 tiers.\n• A full sheet takes roughly 10,000 kills; buying works anywhere, applies instantly and does not heal.\n• Merits from the bank: Buy 1, Buy 5 or Fill wallet on the Ascension tab, or type !merits convert 5.\n• Promathia content is tuned +50; Treasures of Aht Urhgan is planned with a +60 treatment.' }, { title = 'Aggro and link radius halved (2026-08-07)', note = '• Detection ranges are halved: sight about 15 to 7 yalms, sound 8 to 4, magic 20 to 10.\n• Low-HP and ability detection use a 10-yalm window (was 20).\n• Link radius is halved (e.g. 10 to 5 yalms).\n• Unchanged: senses once a monster is engaged, the con/experience rule, the 25-level ignore threshold, ambushers like antlions and worms, room-wide linking families, Sneak and Invisible, and resting still drawing attention.\n• Aggro and link are now separate settings and may be adjusted further.' }, { title = 'Con matches experience (2026-08-06)', note = '• Any monster that gives experience cons Easy Prey or better; only monsters giving nothing con Too Weak.\n• Experience is paid down to 25 levels below you.\n• With Signet (or Sanction/Sigil in their regions), any experience-giving kill can drop crystals.\n• Beastmen and Kindred seals, geodes and weapon skill points (latent trials) follow the same rule.\n• Drift Board contract kills credit if they give experience; offer pools now pull from every family, zone and ecosystem available at each level band.\n• Experience amounts and Decent Challenge and higher cons are unchanged.\n• Aggressive monsters within that 25-level band can aggro you again.' }, { title = 'Skill-ups (2026-07-28)', note = '• Every swing rolls for a skill-up whether it hits or misses, and every roll below cap succeeds.\n• Gain size scales with distance below cap: large when far under, tenths near the cap.\n• Dual wielding two weapon types trains both.\n• Every cast trains its magic school while under cap.\n• Evasion, Parry, Shield and Guard train when monsters swing at you, in normal combat.\n• Skill caps are retail and still gated by level.' }, { title = 'One account, sixteen characters (2026-07-28)', note = '• One account per player; each account has 16 character slots.\n• Register characters into your squad and summon up to five as party members, using their own gear, jobs and gambit rules, earning experience to themselves.\n• The DWMerc addon lists your characters as hireable trusts for other players at a rate you set.\n• Squad storage lets you search and move items across all bags on the account without logging in each character.\n• Multi-boxing a second account is against the rules and is investigated by staff.\n• Household members sharing a connection each get their own account; tell staff so it is noted.\n• After a crash or disconnect your character stays in the world about 30 seconds.' }, { title = 'Rates at a glance (2026-07-27)', note = '• Progression 3x: gil (first clear of each quest), experience, capacity, tabs, fame.\n• Drops and monster gil 2x.\n• Combat power 1.5x for all magic schools and weapon skills.\n• Items (potions, ethers) 3x.\n• Movement 1.5x retail, on foot and mounted.\n• Death costs half of retail from level 31; Raise recovers its normal share.\n• Lottery NMs: 5x retail spawn chance, half the cooldown.\n• Crafting: all crafts to 70, three chosen crafts to 110, HQ 2x.\n• Dynamis every 3 hours (lowered again in the August 30 patch); ENMs daily.\n• No tool breaks, 1-second healing ticks, no party level-gap penalty, 15% faster ability cooldowns, Sneak and Invisible last 3x as long.\n• No cash shop.' }, { title = 'Full rate table (2026-07-27)', note = '• 3x gil, bayld, experience, capacity points and tabs; quest gil triples only on first clear, repeats pay retail.\n• Fields of Valor and Grounds of Valor enabled everywhere, experience rewards 1.5x.\n• Fame 3x.\n• Weaponskill and skillchain points for latents 10x, Magian trials included.\n• All held-currency caps raised.\n• Max merits held raised to 99.\n• Multiple experience rings usable, recharge restrictions removed.\n• Party experience is measured against the highest-level member; no level-gap penalty within range.\n• Experience paid down to 25 levels below you; above you it rises up to a cap at 12 levels over.\n• No TP loss while healing.' }, { title = 'Starting out and jobs', note = '• New characters get 5,000 gil, all maps, all outpost warps and the hub home point crystals.\n• All inventories start at 80 slots.\n• Starter jobs: WAR, MNK, WHM, BLM, RDM, THF; the other nine live-expansion jobs unlock by quests that can be taken at level 1.\n• The remaining seven jobs arrive with Aht Urhgan, Adoulin or Wings of the Goddess.\n• Sub job unlocks at level 1 and equals your main job level.\n• Level cap 99 with no Genkai chain; merits open at 75, job points at 99.\n• Talk to Maat in Ru\'Lude Gardens to receive Limit Breaker and Job Breaker without fighting.' }, { title = 'Launch (2026-07-04)', note = '• LandSandBoat-based server, launched with the base game and Rise of the Zilart.\n• Further expansions open only after they are play-verified on the server.\n• No cash shop or pay-to-win.' } } },
    { name = 'Expansions, quests and missions', group = 'Server', desc = 'DriftwoodXI\'s add-on windows and expansion news, summarised: what each expansion added, how to reach it, job unlocks, raid mechanics, commands, and a Chains of Promathia finishing walkthrough. Where posts disagree, the most recent post applies. Source: https://xi.driftwoodgaming.com/features/dwfame, https://xi.driftwoodgaming.com/features/dwquest, https://xi.driftwoodgaming.com/features/dwtoau, https://xi.driftwoodgaming.com/features/dwtod, https://xi.driftwoodgaming.com/news/seekers-of-adoulin, https://xi.driftwoodgaming.com/news/wings-of-the-goddess, https://xi.driftwoodgaming.com/news/nemesis-restart-this-battle-and-gambits-for-wings-of-the-goddess, https://xi.driftwoodgaming.com/news/treasures-of-aht-urhgan, https://xi.driftwoodgaming.com/news/the-special-shelf, https://xi.driftwoodgaming.com/news/septembers-retail-patch, https://xi.driftwoodgaming.com/news/finishing-chains-of-promathia, https://xi.driftwoodgaming.com/news/the-drift-board, https://xi.driftwoodgaming.com/news/dwfame-your-fame-at-a-glance, https://xi.driftwoodgaming.com/news/one-expansion-at-a-time, https://xi.driftwoodgaming.com/news/content-unlocked', steps = { { title = 'DWFame', note = '• Addon with a bar per fame area showing level, points and points to the next level, read from the server.\n• Guide tab names the quickest repeatable fame quest for each area; a chat line appears on level-up.\n• Open with /fame; !fame prints the same numbers in chat.' }, { title = 'DWQuest', note = '• The Drift Board: daily and weekly contracts that fund the Exchange, Outfitter, Pop-Items shelf, Jeweler and Artisan.\n• Open with /quests from any zone; no NPC is involved.' }, { title = 'DWToAU', note = '• ToAU job setup for squad members: Blue Mage spell set, Puppetmaster automaton, Corsair rolls.\n• Open with /toau.' }, { title = 'DWTod', note = '• Searchable list of every notorious monster with its own respawn timer, showing server state: up, dead, time since death, time until respawn.\n• Open with /tod.' }, { title = 'Seekers of Adoulin is open (2026-10-27)', note = '• Sixth expansion: Eastern and Western Adoulin, the Ulbuka frontier zones and Colonization Reives, open to all.\n• Adds Geomancer, Rune Fencer, DWRaid boss Balamor on a new top difficulty (Adoulin), an [SOA] Drift Board weekly, and a fixed 2-hour Unleashed schedule.\n• Adoulin monsters were remapped from retail 99–139 to level 150–180; built for a level 99 with a geared squad. Both city zones are safe.\n• Update through the launcher for the new raid, quest and Unleashed windows.' }, { title = 'Seekers of Adoulin is open — How to get there', note = '• Talk to Darcia in Lower Jeuno.\n• Option 1: take the Geomagnetron, attune it at any geomagnetic fount (e.g. Gusgen Mines, Ordelle\'s Caves, Maze of Shakhrami), then return to her for the charter permit.\n• Option 2: pay 1,000,000 gil and skip attuning.\n• With the permit, use the Lower Jeuno waypoint to Ceizak Battlegrounds and walk into Adoulin.' }, { title = 'Seekers of Adoulin is open — How far the story goes', note = '• Missions are scripted to the end, but some later battles were never built; on foot the story halts at 3-6-3, Stonewalled.\n• Finish SoA Missions (Special shelf, 250 Drift Coins) sets the log to The Light Within, pays the mission EXP, starts the next story step and grants the Western Adoulin waypoint.\n• Blocked earlier than 3-6-3: use /report where you stand.' }, { title = 'Seekers of Adoulin is open — Two new jobs: Geomancer and Rune Fencer', note = '• Each costs 100 Drift Coins on the DWQuest Special shelf; buying completes the unlock quest with the job emote. Geomancer includes its bell, Rune Fencer its sword.\n• On foot: Geomancer via Dances with Luopans (Western Adoulin); Rune Fencer via Children of the Rune (Eastern Adoulin). Geomancy scrolls are sold in Adoulin.\n• Squad members can play both jobs (RUN keeps runes and wards; GEO places its luopan and bubble on you); DWGambits presets ship for both.' }, { title = 'Seekers of Adoulin is open — DWRaid: Balamor and the Adoulin difficulty', note = '• Balamor - The Trial of the Deathborne Xol, at the top of Ra\'Kaznar Turris.\n• Deathborne Tithe: on a timer he calls out one party member; 5 seconds later that player and anyone close take dark damage equal to a share of max HP. Spread out.\n• Every player hit heals him, and each living Sycophant increases the heal; kill the Sycophants.\n• A stun at the call cancels it: no damage and no heal.\n• He is the hardest boss on the board.\n• Adoulin difficulty (above Wings): 120 Driftmarks per clear, 240 for the first clear of the day. Needs any account character to have finished the SoA story; every party member needs access to the rung.\n• Balamor is also available on Easy through Wings under each tier\'s usual rules.\n• Command: !raid enter balamor adoulin' }, { title = 'Seekers of Adoulin is open — DWQuest: the [SOA] weekly', note = '• 25 kills of a creature family found only in Adoulin zones; pays 115 Drift Coins; offered to levels 81–99 while the expansion is open.\n• The [COP], [TOAU] and [WOTG] weeklies are unchanged.' }, { title = 'Seekers of Adoulin is open — Unleashed: every two hours, on the hour', note = '• An Unleashed world boss now spawns every 2 hours on the even hour, US Eastern (2:00, 4:00, 6:00 PM…), adjusted for daylight saving.\n• When one is killed or escapes, the server announces the next spawn time and the Unleashed window counts down.' }, { title = 'Seekers of Adoulin is open — Also today', note = '• SoA waypoints row (Special shelf, 100 Drift Coins) unlocks all SoA DWPort destinations for characters with the story finished.\n• DWPort adds SoA destinations as you reach them; DWTracker tracks SoA missions step by step.\n• Colonization Reives spawn in the frontier zones.' }, { title = 'Seekers of Adoulin is open — What is not open yet', note = '• Delve, Skirmish, Incursion, Vagary and Sinister Reign (not on any server).\n• SoA story past 3-6-3 on foot (use the skip).\n• Abyssea and the add-on scenarios.' }, { title = 'Wings of the Goddess is open (2026-10-05)', note = '• Fifth expansion: storyline, quests and all past-era [S] zones, set during the Crystal War.\n• Adds Dancer and Scholar, DWRaid bosses Lilith, Dark Ixion and Cait Sith with a new Wings difficulty, a [WOTG] weekly, and active Dread Beasts.\n• All WotG monsters were raised 70 levels, up to 170; endgame for a level 99 with a geared squad, not retail tuning. Past-era cities are safe.\n• Update through the launcher for the new raid and quest windows.' }, { title = 'Wings of the Goddess is open — How to get in', note = '• Touch a Cavernous Maw in Batallia Downs, Rolanberry Fields or Sauromugue Champaign to start the first mission and enter the past.' }, { title = 'Wings of the Goddess is open — Choose San d\'Oria', note = '• The story has you join one nation; later missions wait on that nation\'s first few quests.\n• Recommended path: San d\'Oria, fully scripted and the longest. Bastok is mostly present with more steps skipped. Windurst ends after its third quest.\n• Start the San d\'Oria line with Mainchelite in Southern San d\'Oria [S].\n• Already chose another nation: the main story can still be finished; only nation quests are affected.\n• Fights that were never built are skipped by the relevant NPC moving you on; if still stuck, /report.' }, { title = 'Wings of the Goddess is open — Two new jobs: Dancer and Scholar', note = '• Each costs 100 Drift Coins on the DWQuest Special shelf; buying completes the unlock quest with the job emote. Scholar includes its grimoire.\n• On foot: Dancer via Lakeside Minuet (Jeuno), Scholar via A Little Knowledge.' }, { title = 'Wings of the Goddess is open — DWRaid: three new bosses and the Wings difficulty', note = '• All three fights are in La Vaule [S]. Wings difficulty sits above Aht Urhgan.\n• Lilith Ascendant - The Trial of the Twin Goddess: after a warning, Fatal Allure hits anyone facing her with heavy HP loss and terror; turn away or stun her. At 50% HP she becomes Lilith Ascendant, hits harder and uses Allure twice as often. Imps join on harder difficulties.\n• Dark Ixion - The Trial of the Black Stallion: when he lowers his horn, deal a set amount of damage within a few seconds. Success stuns him; failure brings Wrath of Zeus and harder hits for the rest of the fight.\n• Cait Sith - The Trial of the Goddess\'s Die: Level ? Holy; she calls her roll before it lands. Odd hits players near her, even hits players far away; heavy damage plus silence. Stun during the roll to cancel it.\n• Wings difficulty: 100 Driftmarks per clear, 200 for the first clear of the day. Needs any account character to have finished the WotG story; every party member needs rung access.' }, { title = 'Wings of the Goddess is open — DWQuest: the [WOTG] weekly', note = '• 25 kills of a creature family found only in WotG zones; pays 95 Drift Coins; offered to levels 81–99 while the expansion is open.' }, { title = 'Wings of the Goddess is open — The Dread Beasts are awake', note = '• Ten Dread Beasts, one kind in each of ten [S] zones: aggressive, never link, take minutes to kill.\n• Rewards include every kind of Magicite for Espers.\n• The Dread Skywyrms in Rolanberry Fields [S] were initially untargetable.' }, { title = 'Wings of the Goddess is open — Also today', note = '• Special shelf: WotG story skip (250 Drift Coins) and WotG waypoints row (100 Drift Coins), covering every WotG /port destination including the Cavernous Maws.\n• DWPort adds WotG destinations as reached; DWTracker tracks WotG missions and quests.' }, { title = 'Wings of the Goddess is open — What is not open yet', note = '• Campaign battles and Allied Notes.\n• Walk of Echoes beyond the story missions that use it.\n• Windurst nation quests after the third.\n• Seekers of Adoulin was closed at this point (it opened 2026-10-27).' }, { title = 'Nemesis Restart this Battle, and DWGambits ready for Wings of the Goddess (2026-09-27)', note = '• Nemesis gains Restart this Battle, refighting the same monster in the same arena without leaving.\n• DWGambits: Dancer and Scholar rework, eleven new conditions, a storm-of-the-day and helix-of-the-day rule, and a searchable condition picker.\n• Esper fixes and closed exploits.' }, { title = 'Nemesis Restart this Battle, and DWGambits ready for Wings of the Goddess — Nemesis: Restart this Battle', note = '• Once everyone has opened the chest, a 1-minute window opens; the battle timer counts it down.\n• Press Restart this Battle (top button of the Nemesis window) or type !nemesis restart.\n• Each player pays their own entry fee again (same gil and Job Testimonies); the fight begins when all remaining players have pressed.\n• The same monster reappears 10 seconds later at the entry spot with a fresh 15 minutes.\n• Each restarted fight gives its own trophy, chest and Esper credit.\n• Missing part of the fee: the button lists what is short; the arena closes when the minute ends. !nemesis leave exits at any point in the window.\n• Legend monsters cannot be restarted (their 2-hour lockout starts at the kill).\n• Fix: a kill in the final minutes no longer lets the battle clock expire during chest opening.' }, { title = 'Nemesis Restart this Battle, and DWGambits ready for Wings of the Goddess — DWGambits: ready for Wings of the Goddess', note = '• Scholar: a stratagem is consumed by the spell it modifies (previously one Accession turned a minute of cures party-wide at double MP).\n• Stratagems above the member\'s level now state why they cannot fire; rules waiting on Light Arts, Dark Arts, an Addendum or Tabula Rasa state what they need.\n• New rules: Keep the day\'s storm up; Helix of the day. Lorekeeper and grimoire presets retuned.\n• Dancer: waltzes consume Contradance; ally waltzes target only allies in range; the waltz ladder works under Trance at any TP.\n• New conditions include stratagem charges, daze level, my TP, my MP, other healer in the party and time in the fight.' }, { title = 'Nemesis Restart this Battle, and DWGambits ready for Wings of the Goddess — Espers and other fixes', note = '• Espers: an unreadable Esper record at login now waits rather than being overwritten; skill floors no longer stack past the cap across Espers; lent spells and abilities obey level caps and level sync; reading a scroll for a spell an Esper lends now saves it.\n• Raid circuits no longer post a false "10 minutes remaining".\n• Entering a Raid or the Gauntlet no longer resets a pet\'s call timer.\n• Treasure pool and Spoils deliveries to another account character are verified before being reported delivered.\n• Update through the launcher for the new Nemesis, Esper and DWGambits windows.' }, { title = 'Treasures of Aht Urhgan is open (2026-09-21)', note = '• Fourth expansion: zones, all 48 missions scripted, quests live; Aht Urhgan Whitegate and Nashmau function as towns (auction counters, mog house, home points, survival guides).\n• Every ToAU monster was raised 60 levels; open-field mobs are roughly level 120–150.' }, { title = 'Treasures of Aht Urhgan is open — How to get in', note = '• Talk to Faursel in Lower Jeuno (Tenshodo HQ area) and accept The Road to Aht Urhgan (no level requirement).\n• Get the Boarding Permit for 500,000 gil or by trading one of several accepted item sets (all from open content).\n• Take the boat from Mhaura with the Boarding Permit and a 100-gil ferry ticket; it arrives in Aht Urhgan Whitegate, not Al Zahbi.\n• ToAU home points, survival guides, Unity and Voidwatch rifts and the six Runic Portal staging points unlock once you hold the permit.' }, { title = 'Treasures of Aht Urhgan is open — Three new jobs', note = '• Blue Mage, Corsair and Puppetmaster cost 100 Drift Coins each on the DWQuest Special shelf.\n• On foot: the Blue Mage quest stays inside Whitegate; Corsair and Puppetmaster go through Arrapago Reef (level 128–149 here), so the shelf is the practical route for those two.' }, { title = 'Treasures of Aht Urhgan is open — The forge has a second rung', note = '• The DWRaid shop\'s Reforge tab (formerly Relic Reforge) now has two rungs.\n• 109: Dynamis relic, Outfitter AF +1 or Empyrean +2 → its item level 109 version; price unchanged.\n• 119: a reforged item level 109 piece → its +1 at item level 119; 5,000 Driftmarks (6,000 for body).\n• Covers all 22 jobs including Geomancer and Rune Fencer. The input piece and its augments are consumed. Both rungs require CoP finished on the account.\n• Server item level cap raised from 114 to 119; Antonia in Upper Jeuno sells Arasy item level 119 weapons for 3,000,000 gil each.' }, { title = 'Treasures of Aht Urhgan is open — Imperial Standing', note = '• Kills under Sanction in ToAU regions earn Imperial Standing.\n• !imperial converts it to Imperial bronze, silver, mythril and gold pieces, which Ghatsad takes for a Puppetmaster frame.\n• Automaton attachments, Corsair cards and dice are sold for gil in Nashmau.' }, { title = 'Treasures of Aht Urhgan is open — Also today', note = '• Drift Board: [TOAU] daily and weekly kill contracts while the expansion is open.\n• DWTracker covers ToAU missions and quests.\n• ArmsDealer adds a Mythic Weapons case: level 99 Mythics without afterglow, 1,000 Drift Coins each.' }, { title = 'Treasures of Aht Urhgan is open — What is not open yet', note = '• Nyzul Isle, Einherjar, Salvage, ZNM, the Mythic weapon quests, Besieged, Pankration, the Chocobo Circuit.\n• Assault: only the first few missions work. The Commissions Agency menu shows all fifty, but an unbuilt one is refused with nothing consumed.' }, { title = 'Rename your characters, skip the two stories, and refresh the chat log (2026-09-11)', note = '• DWQuest shops gain a Special tab (services, not items).\n• Rename, 500 Drift Coins: choose an account character and a new name. Lobby rules apply (letters only, 3–15 characters, unused, not banned); the old name is released.\n• Rise of the Zilart + Chains of Promathia story skip, 1,000 Drift Coins: sets finisher mission state (full Zilart chain, The Last Verse in both logs). No key items, rank, quest rewards or titles.\n• All Zilart and Promathia DWPort waypoints, 250 Drift Coins: home points, survival guides, outposts and story pass; requires both stories finished.\n• Purchases are quoted first and charged only on confirm.\n• Commands: !drift special; !drift specialbuy rename Pld Roland; !drift specialbuy story; !drift specialbuy waypoints; then !drift confirm. Needs dwquest 1.28.0.\n• GM panel (dwgmpanel 1.3.4): Logs tab chat log has a Refresh button beside Search that reloads the current channel\'s newest lines.' }, { title = 'September\'s Retail Patch (2026-09-10)', note = '• Square Enix released a retail update on September 9 (client build 30260904_1).\n• Update the client: after the next server patch, August-build clients are refused at login. Open the PlayOnline Viewer, log in and start FINAL FANTASY XI; the patch downloads before the title screen.\n• Launchers before 0.32.6 misread the patched item file: job capes show donor names, augments are blank and DWPolitics titles are missing. Launcher 0.33.0 also carries the matching Ashita fix.\n• Verify Game Files now uses a list rebuilt from a patched client; earlier mass "differ/missing" results came from the old list. Do not delete DAT files based on Verify; use PlayOnline\'s own file check instead.' }, { title = 'Finishing Chains of Promathia (2026-09-04)', note = '• The Promyvion DWRaid tier and item level 109 shelf need CoP finished on the account: CoP log at "The Last Verse" (8-5).\n• Winning Dawn (8-4) leaves the log on "Dawn"; it advances only after you turn in Apocalypse Nigh to Gilgamesh in Norg.\n• Required order: Storms of Fate, then Shadows of the Departed, then Apocalypse Nigh.\n• DWTracker highlights the step you are on.' }, { title = 'Finishing Chains of Promathia — Part 1. Dawn (mission 8-4)', note = '• In the Garden of Ru\'Hmet, stand on the central platform next to the Cermet Portal (about x -419, z 379) and accept travel to the Empyreal Paradox.\n• Examine the Transcendental Radiance (x 540, z -598) for a scene, then examine it again to enter.\n• Fight Promathia (two forms): level cap 75, up to 6 players, trusts allowed, 30 minutes; Prishe and Selh\'teus assist.\n• Let every post-fight scene play (you are moved twice); the last grants key item Tear of Altana and drops you in Al\'Taieu. No Tear means re-enter the Paradox.\n• Wait for midnight Japan time (15:00 UTC; 11:00 AM US Eastern in summer, 10:00 AM in winter), real-time.\n• View all five farewells in any order; nothing tells you which are missing.\n• Louverance: talk to Hinaree in Southern San d\'Oria (x -302, z 98, by the well), zone into Uleguerand Range for a scene, then return and enter the square just east of Hinaree.\n• Chebukki siblings: talk to Chipmy-Popmy in Port Windurst (x -183, z 74); go to Bibiki Bay, ride the Manaclipper to Purgonorgo Isle and examine the "??? Warmachine" (x -345, z -977). This one is most often missed.\n• Shikaree sisters: zone into Mhaura.' }, { title = 'Finishing Chains of Promathia — Part 2. Storms of Fate', note = '• Go to the palace doors in Ru\'Lude Gardens and accept the quest.\n• In Misareaux Coast, examine the Dilapidated Gate to Riverne Site #B01 (x -260, z 280) for a scene.\n• In Riverne Site #B01, head to the Unstable Displacement in the far north-west (x -613, z 693). Some displacements en route need a Giant Scale (dropped by Riverne wyverns); carry a couple.\n• Examine the Unstable Displacement for a scene, then again to enter.\n• Fight Bahamut: up to 18 players, no level cap, trusts allowed, 30 minutes. Reward: key item Whisper of the Wyrmking.\n• Return to the Ru\'Lude Gardens palace doors for the scene; quest complete.' }, { title = 'Finishing Chains of Promathia — Part 3. Check your Zilart missions', note = '• Shadows of the Departed requires your Rise of the Zilart log on mission 17, Awakening, with both optional scenes seen.\n• Complete Rise of the Zilart through mission 16, The Celestial Nexus.\n• Zone into Norg once for the Gilgamesh scene.\n• In Lower Jeuno, examine the Neptune\'s Spire door (x 38, z -17) for the Aldo scene.\n• If Zilart is untouched, do it first; all its fights are open here.' }, { title = 'Finishing Chains of Promathia — Part 4. Shadows of the Departed', note = '• Wait one Vana\'diel day after Storms of Fate (ends at the next Vana\'diel midnight, under an hour of real time).\n• At the Ru\'Lude Gardens palace doors, watch the scene and receive key item Note written by Eshantarl.\n• Examine the Memory Flux in Promyvion-Dem (x 220, z 340), Promyvion-Holla (x 100, z -140) and Promyvion-Mea (x 260, z 180). Promyvions have no level cap here.\n• Return to the palace doors for the scene; quest complete.\n• Zone out of Ru\'Lude Gardens at least once before starting the next quest.' }, { title = 'Finishing Chains of Promathia — Part 5. Apocalypse Nigh', note = '• Wait one Vana\'diel day after Shadows of the Departed.\n• At the Ru\'Lude Gardens palace doors, watch the scene and accept the quest.\n• Zone into Sealion\'s Den from Misareaux Coast for a scene.\n• In the Grand Palace of Hu\'Xzoi, examine the Gate of the Gods (x -20, z -280); the scene sends you to the Garden of Ru\'Hmet.\n• Cross on the central platform to the Empyreal Paradox; examine the Transcendental Radiance for a scene, then again to enter.\n• Fight Kam\'lanaut and Eald\'narche together: up to 6 players, no level cap, trusts allowed, 30 minutes. A scene follows and you arrive in Al\'Taieu.\n• In Lower Jeuno, talk to Aldo at Neptune\'s Spire (x 21, z -62); you must be home-nation Rank 5 or higher.\n• Wait one Vana\'diel day. Optional same-day scene: the Oaken Door in Norg (x 102, z -12).\n• In Norg, talk to Gilgamesh (x 122, z -12) and choose an earring: Static, Magnetic, Hollow or Ethereal. Keep one inventory slot free.\n• Done: CoP and Zilart logs both read "The Last Verse"; the Promyvion tier and 109 shelf unlock for every account character within seconds.' }, { title = 'Finishing Chains of Promathia — When a scene does not play', note = '• Farewells do nothing before midnight Japan time.\n• The Ru\'Lude Gardens scene after the farewells needs all five; the usual missing one is the Purgonorgo Isle Warmachine.\n• That scene is at the upper-level palace doors, not the zone entrance.\n• Before the 2026-09-04 update, discarding a Rajas, Sattva or Tamas ring from the Jeweler (or losing one from a full recycle bin) locked the farewells for 27 days; fixed, and affected characters were cleared.\n• Vana\'diel-day waits are enforced; check the in-game clock and return after Vana\'diel midnight.\n• Shadows of the Departed needs Zilart on Awakening with both scenes; Apocalypse Nigh needs Rank 5 for Aldo.\n• Still stuck: give a GM your character name and the scene you expected.' }, { title = 'The Drift Board: contracts in your pocket (2026-08-05)', note = '• Six contracts at all times, opened with /quests from anywhere (no NPC).\n• Three dailies, rerolled each Vana\'diel day (57.6 real minutes): kill 5 of a family; kill 10 of anything in a zone; a wildcard (5 weapon-skill kills, 5 kills between dusk and dawn, or 3 kills during weather).\n• Three weeklies, rerolled each Vana\'diel week (7.68 real hours): family and zone types at 5x size, plus an ecosystem contract (25 Beasts, 25 Undead, 25 Vermin).\n• Contracts match your level band; everyone in a band gets the same six.' }, { title = 'The Drift Board: contracts in your pocket — Community contract', note = '• One server-wide contract: one ecosystem, a target in the thousands, one week.\n• Contribute past a small threshold to qualify; on completion every contributor is paid at once, even if offline.' }, { title = 'The Drift Board: contracts in your pocket — How contracts work', note = '• Accept with one click wherever you are.\n• Progress updates as each mob dies; contracts are account-wide, so any of your characters\' kills count.\n• Reward is paid on the final kill, with no hand-in.\n• Kills count under the Fields of Valor credit rule; mobs too weak for FoV credit give nothing.\n• A contract accepted just before rotation still gets a full period.' }, { title = 'The Drift Board: contracts in your pocket — Drift Coins', note = '• Contracts pay Drift Coins, separate from gil, conquest points and sparks.\n• They buy instant augments applied to gear in any account character\'s bags, from a storefront that rotates each Vana\'diel day.' }, { title = 'The Drift Board: contracts in your pocket — Opening it and chat commands', note = '• Toggle with /quests, /dwquest or !drift.\n• The launcher installs dwquest in the Default addon set; otherwise enable it in the launcher\'s Addons tab or use /addon load dwquest.\n• Chat equivalents: !drift (board), !drift accept d1, !drift abandon a1, !drift balance (coins and recent ledger lines).' }, { title = 'DWFame: all your fame, one window (2026-08-04)', note = '• Bars for San d\'Oria, Bastok, Windurst, Jeuno, Selbina/Rabao, Norg, all nine Abyssea zones and Adoulin: fame level, exact points, points still needed.\n• Guide tab: quickest repeatable route per area with quest, NPC, exact items and counts, and payout per turn-in.\n• Chat notice when a level is gained, per character (e.g. "San d\'Oria fame reached level 5!").\n• "Closest next level" sort option.\n• Derived areas are labelled on their bars: Jeuno climbs as the three nation fames climb, and Selbina/Rabao has no separate counter, being the mean of San d\'Oria and Bastok fame.' }, { title = 'DWFame: all your fame, one window — Opening it and chat commands', note = '• Toggle with /fame, /dwfame or !fame.\n• The launcher installs dwfame in the Default addon set; otherwise enable it in the launcher\'s Addons tab or use /addon load dwfame.\n• !fame prints all sixteen areas with levels, points and distances; !dwf sync shows the raw records.' }, { title = 'One expansion at a time: where DriftwoodXI is going (2026-07-30)', note = '• At posting: base game and Rise of the Zilart at level cap 99; other expansions closed, and character select shows what is included.\n• Opened since: Chains of Promathia 2026-08-27, Treasures of Aht Urhgan 2026-09-21 (later posts add WotG 2026-10-05 and SoA 2026-10-27). The Expansions tab is the live list.\n• Expansions open one at a time after testing on the server; no release dates are announced.\n• DriftwoodXI is free to play with no cash shop.' }, { title = 'Content unlocked: Dynamis, Garrison, Sky and friends (2026-07-27)', note = '• Status (updated 2026-09-21): base game with three nations to Rank 10, Rise of the Zilart ZM1–17 with Sky and Tu\'Lia, Chains of Promathia, Treasures of Aht Urhgan: open.\n• Closed then: ACP/AMK/ASA add-on scenarios, Abyssea, Wings of the Goddess, Seekers of Adoulin, Rhapsodies, Voracious Resurgence. (WotG and SoA have since opened per later posts.)\n• Endgame entry requirements are lowered so small groups can run it.' }, { title = 'Content unlocked — Dynamis', note = '• Re-entry: 3 hours as of 2026-08-30 (originally 6 hours).\n• Level requirement: 30.\n• Hundred-piece currency can be broken down to singles.\n• Open: the three city zones, Beaucedine, Xarcabard and the Dreamlands (Valkurm, Buburimu, Qufim); the Dreamlands do not need CoP missions here. Dynamis - Tavnazia was held for CoP.' }, { title = 'Content unlocked — Garrison', note = '• Enabled; rank requirement 1.\n• An outpost becomes available again 10 minutes after a run.\n• Each character may do one garrison per conquest week.' }, { title = 'Content unlocked — Everything else', note = '• Voidwalker notorious monsters roam the original zones.\n• Magian Trials enabled with 10x weaponskill and skillchain points.\n• Trusts earned through their quests as on retail (nation permits from level 5, cipher items for the rest); five can be called at once, as the Rhapsodies key items are given out here.\n• Fields of Valor and Grounds of Valor everywhere: 1.5x page EXP, 3x tabs.\n• Explorer Moogles from level 1; home point teleport crystals enabled.\n• Gobbie Mystery Box: opens at character age 5 days, 10 points per day (changed 2026-08-04 from 1 day and 50 points).' }, { title = 'Reporting problems', note = '• Use /report in game; it sends your current state with the report.\n• Discord: discord.gg/DriftwoodGaming.' } } },
    { name = 'Crafting and gathering', group = 'Server', desc = 'Driftwood XI crafting, fishing, gathering and market rules plus the DWCraft and DWFishing tools, summarised from the add-on pages and news posts (newest post first; a later post overrides an earlier one). Source: https://xi.driftwoodgaming.com/features/dwcraft, https://xi.driftwoodgaming.com/features/dwfishing, https://xi.driftwoodgaming.com/news/s-ranks-a-raised-aht-urhgan-and-ammunition-for-crafters, https://xi.driftwoodgaming.com/news/the-artisan-lu-shang-and-a-walk-back, https://xi.driftwoodgaming.com/news/summoners-by-name-and-digging-doubled, https://xi.driftwoodgaming.com/news/five-fixes-and-every-craft, https://xi.driftwoodgaming.com/news/using-port-and-craft, https://xi.driftwoodgaming.com/news/your-crafting-ledger, https://xi.driftwoodgaming.com/news/crafting-gathering-and-fishing', steps = { { title = 'DWCraft', note = '• Open with /craft.\n• Lists each craft\'s level, rank and next rank test.\n• Shows the specialization budget: points spent above the free cap of 70, points remaining, and which craft is charged first if you overspend (budget later raised to 3,200; see 2026-08-24).\n• Displays house crafting rules pulled from live server settings.' }, { title = 'DWFishing', note = '• One window covering the fishing system; its first tab, ROUTE, is a costed plan from skill 0 to 110.\n• The route names which rod to buy and its vendor, the bait, the exact spot to fish, rough casts per stretch, and when to move on.' }, { title = 'S ranks and skill changes (2026-09-23)', note = '• New skill ranks above A+: S-, S and S+; ten jobs received at least one, and no other job ranks changed.\n• WAR: Great Axe S+, Axe S-.\n• WHM: Divine magic S-, Club S-.\n• BLM: Elemental magic S+, Dark magic S.\n• RDM: Enfeebling magic S+.\n• THF: Dagger S+.\n• PLD: Sword S.\n• BST: Axe S+.\n• RNG: Archery S+, Marksmanship S+.' }, { title = 'Aht Urhgan enemies raised (2026-09-23)', note = '• 389 enemies across eleven Aht Urhgan zones that the ToAU +60 skipped are now raised (e.g. Nostokulshedra, formerly 88-89 in Arrappago Reef); some now reach level 149.\n• Apex and Locus camps keep their previous levels.\n• Mission Shield of Diplomacy: Karababa now fights at her opponent\'s level +5 (she was 73 beside a level 130 Khimaira).' }, { title = 'Ammunition recipes (2026-09-23)', note = '• Nine previously unobtainable rounds are craftable; each synth gives 33, HQ gives 66 or 99; all nine are in the DWCraft recipe book.\n• Woodworking, Earth Crystal:\n• Adaman Bolt: Woodworking 81, Smithing 31; Holly Lumber + Adaman Bolt Heads.\n• Dark Adaman Bolt: Woodworking 81; Holly Lumber + Dark Adaman Bolt Heads.\n• Darkling Bolt: Woodworking 71, Alchemy 31; Holly Lumber + Darkling Bolt Heads.\n• Fusion Bolt: Woodworking 81, Goldsmithing 11; Holly Lumber + Fusion Bolt Heads.\n• Antlion Arrow: Woodworking 81, Bonecraft 41; Arrowwood Lumber + Antlion Arrowheads + Colibri Fletchings.\n• Alchemy and Smithing, Fire Crystal:\n• Adaman Bullet: Alchemy 81, Smithing 31; Adaman Ingot + Firesand.\n• Dark Adaman Bullet: Smithing 81; Dark Adaman Ingot + Firesand.' }, { title = 'Magic changes (2026-09-23)', note = '• Absorb-Attri (DRK level 91) now works; scroll costs 96,000 gil from Mazween in Aht Urhgan Whitegate (alongside Absorb-TP and Absorb-Acc) and is also on the Conquest Exchange (/cpx).\n• Absorb-Attri takes one beneficial effect from the target, or two with Nether Void active.\n• Artisan tab in /quests has a Blue Magic page: Self-Destruct for 50 Drift Coins, Final Sting for 100 (no enemy here uses them).\n• Spaekona\'s Coat and its upgrades now return 2% of elemental magic damage as MP, per target, magic bursts included; squad Black Mages benefit too.' }, { title = 'Addon updates (2026-09-23)', note = '• DWChat 1.1.0: completes its planned features.\n• DWCon 1.3.0: compact target status grid using game icons with timers; hover for name, time and power; options for Compact/Classic, icon size, icons per row, timer position, name display and backdrop darkness.\n• DWTOD 1.0.1: polls visible rows once a minute and again at countdown zero; requests no longer appear in chat.\n• DWQuest 1.36.0: Artisan Blue Magic page.\n• DWCraft 1.7.3: the nine ammunition recipes.\n• DWHub 1.0.4: updated DWChat description.' }, { title = 'Other fixes (2026-09-23)', note = '• Purchases at the Conquest Exchange, DWQuest shops, DWRaid shop and market are refused, without charge, while crafting, fishing, zoning or in a cutscene.\n• Gil in an open trade window can no longer pay for Conquest Exchange purchases or Port fares.\n• The warehouse no longer sells items no shop buys.\n• Ghatsad asks for the chosen automaton frame\'s materials, cancelled offers no longer lock you, trading with all five heads unlocked works, and he responds at level 60+.\n• Unity warp to Aydeewa Subterrane now lands on the floor.\n• Self-ammo weapons (Death Penalty, Gastraphetes, Annihilator, Yoichinoyumi, 119 III forms from Oboro) plus ammo pouches and quivers now dispense ammunition.\n• Never-used items are usable immediately regardless of server uptime.\n• Assault Imperial Agent Rescue: gates now take hits; Mamool Ja warders\' thrown weapons and Firespit break them, so stand with your back to a gate.\n• Western Altepa Desert: all nine Phorusrhacos now spawn together, including at Picolaton\'s camp.' }, { title = 'Hand-to-Hand and Polearm back to A+ (2026-09-21)', note = '• MNK Hand-to-Hand and DRG Polearm returned to A+ (retail value) after two days at A.\n• Stored skill was never changed; a capped MNK read 417 during that time and 424 after the next restart.\n• Characters levelled past 62 during those two days may have a few normal skill-ups to earn.\n• WHM Club remains A+.' }, { title = 'The Artisan tab (2026-09-21)', note = '• New Artisan tab in /quests sells all 45 crafting guild key items (Patissier through Mooching) for Drift Coins instead of guild points.\n• Guild cost up to 10,000 GP: 25 coins; up to 20,000: 50; up to 40,000: 100.\n• Serpent Rumors (95,000 GP): 250 coins; Mooching (115,000 GP): 300 coins.\n• A full guild set costs 275-400 coins; Fishing costs 700.\n• Guild rank requirements still apply in that guild\'s craft; unavailable rows are greyed, with the reason on hover.\n• Needs dwquest 1.34.0, which the launcher updates automatically; use /report if a row seems wrongly greyed.' }, { title = 'Lu Shang\'s Fishing Rod (2026-09-21)', note = '• Option 1: Artisan tab, 500 Drift Coins, no rank needed, one per character while you hold one.\n• A broken rod is repaired by Irmilant in Rabao; the tab sends you there instead of selling another.\n• Option 2: trade 5,000 carp (was 10,000) to the brothers in Port San d\'Oria; your existing tally counts, and if already over 5,000 your next trade completes it.\n• Daily catch limit raised from 300 to 500 for everyone.\n• Ebisu is still a quest; buying Serpent Rumors from the Artisan tab makes it easier to start.' }, { title = 'Chocobo digging and squad fixes (2026-09-11)', note = '• Chocobo digging skill-up chance doubled to 30 in 100 (retail 15); each rise is still 0.1 and daily dig count is unchanged.\n• DWGambits rules \'Summon and keep the pet out\' and \'Release the pet\' can now name a specific avatar; \'Their best avatar\' keeps the old behaviour.\n• A named release dismisses only that avatar; a bare release dismisses whatever pet is out.\n• Example set: `` Self > missing effect > Haste > Summon and keep the pet out > Garuda Self > missing effect > Haste > Use a blood pact > Hastega II Self > has effect > Haste > Release the pet > Garuda Self > always > Summon and keep the pet out ``\n• An avatar a release rule would dismiss is never summoned next, so sets cannot loop.\n• Self > always > Avatar\'s Favor rules now install and wait for a pet instead of being discarded, and the aura reaches the party.\n• Hug stance placed squad members 0.3 yalm from the mob, inside Trick Attack\'s 0.5-yalm minimum; fixed so Trick Attack transfers hate again.\n• Avalanche Tzar (Ice trial): the detonation clock starts when the arena opens and is now counted down aloud from arrival.\n• DWPort now allows Ru\'Aun Gardens warps for Rise of the Zilart finishers (it had checked a CoP quest flag).\n• Apocalypse Nigh and two Waughroon Shrine fights had arena-three spawns placed far under the floor; fixed.\n• DWBags Bags tab: choose a bag and press Send All to WH; it shows item count and free warehouse slots, confirms, then moves all or nothing; worn, priced, placed, currency and linkshell items stay and are counted.' }, { title = 'Every craft to 110 and other fixes (2026-08-24)', note = '• Specialization budget is now 3,200 points, enough to take all eight crafts to 110 on one character; the three-craft limit is gone.\n• Guild rank-up tests are unchanged (Expert still earned per craft); the /craft ledger shows the new budget.\n• /hidetrust now also hides trusts\' pets; your own and other players\' real pets are unaffected.\n• BST Ready charges are now consumed; COR Quick Draw and SCH Stratagems had also been free and are fixed.\n• The 15% faster ability cooldown bonus now applies once (it had stacked twice on Familiar, Unleash, the Waltzes and two-hours with recast gear).\n• The \'DEBUG: Please Report\' status icon (seen from PLD Rampart) is fixed.\n• Item tooltips in DWBags, DWWarehouse, Market, Armory and Outfitter now list augments by name and rank, including other characters\' bags and the warehouse.\n• Elemental resists show as tags: FiR, IcR, WiR, EaR, LtR, WaR, LiR, DkR (e.g. FiR:20 = Fire Resist +20, DkR:-10 = Dark Resist -10).' }, { title = '/port and /craft setup (2026-08-02)', note = '• Both addons ship with the server, are enabled in the Default set, and are fetched by the launcher; nothing to install.\n• If a window does not open, enable it in the launcher\'s Addons tab or type /addon load dwport (or /addon load dwcraft).' }, { title = '/port', note = '• Open with /port or !port; the header Home button is the free !home warp.\n• Home points tab: every attuned crystal; free within your nation\'s group, cheaper elsewhere with Rhapsody in White.\n• Survival guides tab: every registered book, 1,000 gil each.\n• Outposts tab: every region your outpost warp reaches; most are unlocked from the start.\n• Teleport tab: six Teleport spells and three Recalls; if you or a squad White Mage meets the requirements (crystal, spell, level, MP), one click casts it and spends the MP.\n• The search box covers all tabs at once (e.g. \'jeuno\' finds home point, survival guide and outpost).\n• Star a destination to pin it to the top of its tab across sessions.\n• Your last five trips appear as buttons under the header; each button shows its fee, and your gil is in the header.' }, { title = '/craft tabs and commands', note = '• Open with /craft or !craft; five tabs.\n• Ledger: real level, rank, rank cap and where the next guild test unlocks for each craft.\n• Recipe Book: search all synths by name or material, per craft or all; each row shows can make, the skill gap, a missing key item, a blocking held Rare, or a material count like 1/2.\n• Ladder: pick a craft, enter a target (blank = rank cap), press Plan.\n• Tally: attempts, breaks, NQ vs HQ by tier, items made, materials used, skill gained and gil spent; persists across zoning, resets on Reset or logout.\n• Alts: read-only grid of every account character against every craft.\n• Typed commands: !craft skills, !craft points, !craft rules, !craft find <text>, !craft book cooking, !craft recipe <id or name>, !craft shopping <id or name>, !craft ladder cooking 60, !craft tally, !craft tally reset, !craft alts, !craft help.\n• The window only reports server values; it never performs synths, trades or guild turn-ins.\n• Skill-ups use the modern rule: recipes up to 10 levels below your skill still give skill-ups, which the Ladder tab relies on.' }, { title = 'Base crafting rules', note = '• All crafts level freely to 70; above 70 a specialization budget applies (originally 1,200 points for three crafts at 110, now 3,200 for all eight); Fishing never counts.\n• HQ chance is 2x retail.\n• Craft skill-up chance is 3x retail and skill-up amount 2x.\n• Day and moon have no effect on crafting.' }, { title = 'Gathering and fishing rules', note = '• Harvesting, excavation, logging and mining tools have a 0% break chance.\n• Harvesting, excavation, logging, mining and digging succeed 75% of the time.\n• 100 chocobo digs per day (changed from 200 to 50, then to 100); Burrow and Bore are granted.\n• Fishing is enabled with a 5x skill-up rate.' }, { title = 'Auction house and fame', note = '• Up to 70 AH listings per character.\n• AH listing fee is capped at 1,000 gil.\n• An ffxiahbot broker keeps the AH stocked.\n• Fame gain is 3x.' } } },
    { name = 'Gear and drops', group = 'Server', desc = 'Driftwood XI gear and loot systems: DWSpoils and Runes, the +2 forge, Drift Board shops, augments, caskets and drop rates, newest patch notes first; later notes override earlier ones. Source: https://xi.driftwoodgaming.com/features/dwspoils, https://xi.driftwoodgaming.com/news/disenchant-turn-old-gear-into-runes, https://xi.driftwoodgaming.com/news/artifact-and-empyrean-plus-two-armour, https://xi.driftwoodgaming.com/news/relic-plus-two-armour, https://xi.driftwoodgaming.com/news/runes-bank-an-augment-and-put-it-where-you-want, https://xi.driftwoodgaming.com/news/relic-mythic-empyrean-effects, https://xi.driftwoodgaming.com/news/empyrean-weapons-and-oboro, https://xi.driftwoodgaming.com/news/the-armor-ladder-and-the-jeweler, https://xi.driftwoodgaming.com/news/x-magic-and-the-endgame-loop, https://xi.driftwoodgaming.com/news/your-weapon-casts-now, https://xi.driftwoodgaming.com/news/the-conquest-point-exchange, https://xi.driftwoodgaming.com/news/relics-at-the-armsdealer, https://xi.driftwoodgaming.com/news/the-outfitter, https://xi.driftwoodgaming.com/news/the-driftmark-armory, https://xi.driftwoodgaming.com/news/the-drift-exchange, https://xi.driftwoodgaming.com/news/the-exchange-gets-a-window, https://xi.driftwoodgaming.com/news/rare-drops-go-to-your-other-characters, https://xi.driftwoodgaming.com/news/drops-gil-and-treasure-hunter, https://xi.driftwoodgaming.com/news/treasure-caskets-reworked', steps = { { title = 'DWSpoils (/spoils)', note = '• Open the window with /spoils.\n• Any kill that grants experience has a small chance to award a gear piece carrying 1–4 random augments, or a Rune.\n• The award lands directly in your bags; there is no treasure pool or lotting.\n• Each real player in the party rolls separately for their own award.' }, { title = 'Disenchant (2026-10-18)', note = '• New Disenchant tab in /spoils, next to Runes.\n• Pick an augmented piece and one of its augments; that augment becomes one Rune in your account wallet.\n• The piece and all its other augments are destroyed; you get a warning and must confirm twice.\n• The list covers gear from all characters on the account (current character first, Find box available) and never shows equipped items.\n• Eligible: any piece with at least one augment that has a Rune, i.e. the Super Auged list plus Break Damage Limit (99 kinds); augments without a Rune appear greyed out.\n• Only one Rune per piece, however many qualifying augments it has.\n• Rank is not kept: applying the Rune rolls a fresh rank across the target item\'s range.\n• Disenchants are not announced server-wide.' }, { title = 'DWAH Wanted buy orders (2026-10-18)', note = '• A new buy order privately pings online players who own the item, saying where their copy is (bags, other containers or warehouse); the buyer stays anonymous and you never get pinged for your own account\'s orders.\n• Pings only fire for orders of at least 2,000 gil and, once the item has a few recent sales, at least half its usual price.\n• Limits: one ping per item per day, at most four lines per hour.\n• At login, one line reports how many open buy orders want items you hold, naming up to three.\n• /dwah has a Most wanted strip: the five largest open orders by gil and how many you could sell; click one to open its Orders tab.\n• Commands: /dwah notify off|on (or !market notify off|on), /dwah orders, /dwah orders <item id>.' }, { title = 'Other 2026-10-18 changes', note = '• Merit abilities (level 75) granted through your support job now draw on your merits at the support job\'s level when the main job doesn\'t qualify.\n• No Foot Rise no longer shows a phantom finishing move.\n• Magical ranged weapon skills (Trueflight, Wildfire, Leaden Salute, etc.) now add Magic Damage before the weapon skill multiplier.\n• They now consume one round each; Recycle, its merits and Unlimited Shot can still save it, and squad members also use one round per shot.\n• Fixed: a timed-out Cloister of Gales raid trial now ends and ejects everyone.\n• Fixed: the empty /quest window ("The server did not answer"); it now explains the problem and recovers on Refresh.\n• Update dwspoils and dwah through the launcher; server changes are already live.' }, { title = '+2 armour at the DWRaid forge (2026-10-09, 2026-10-11)', note = '• Open the forge from the DWRaid window or with !raid reforge, holding the +1 (item level 119) of any Artifact, Relic or Empyrean piece.\n• Fee: the +1 itself, 3x its driftmark price and 1 Esper Core — 13,500 driftmarks for most pieces, 16,200 for a body.\n• Esper Cores drop from the Unleashed.\n• 335 +2 pieces across 22 jobs (all 110 Relic +1 pieces added 10-09; Artifact and Empyrean added 10-11).\n• The +1 is consumed with its augments, so move augments off first.\n• The forge checks your driftmarks and Cores before taking anything, and refunds everything if it fails.\n• Every +2 now has the same appearance as its +1.' }, { title = 'Armour line fixes', note = '• 10-09: every 119 Artifact/Relic/Empyrean +1 and +2 now gives the stats its description lists; existing +1s are fixed automatically.\n• Newly active lines include faster casting for enhancing, enfeebling, healing, blue magic and Utsusemi; counter crit rate, Double Shot damage, Magic Burst accuracy, Banish damage vs undead; plus Mana Wall, Migawari, Sekkanoki, Spirit Link, Feather Step, Efflux, Klimaform, Perpetuance, Gain-spell potency and Waltz potency received.\n• 10-11: Ebers Mitts with Divine Caress — the -na target (not the White Mage) now gets temporary protection from that ailment.\n• Wicce Chausses: -ja spells and Comet on one target build a bonus to that element\'s damage, capped at 25%.\n• Arbatel Pants: Penury and Parsimony now trigger Conserve MP\'s free cast.\n• Amini Bragues: True Shot now counts for ranged shots and ranged WS.\n• Peltast\'s Cuissots: the Jump attack bonus now functions.\n• Chasseur\'s Gants +2 (Allies\' Roll) and Ebers Pantaloons +2 (Divine Benison) now give the full amount.\n• Gear bonuses to Allies\' Roll, Valiance/Vallation duration, Pflug, Chain Affinity and Sentinel\'s Scherzo now work.' }, { title = 'Misc fixes (2026-10-09, 2026-10-11)', note = '• Sub Scholar at 99 has five stratagem charges (the 10-09 cut to two was reverted on 10-11).\n• After an R0 or crash, selecting the same character takes over the stuck session (no 15–20 minute lockout).\n• Squad gear latents work, e.g. Berserker\'s Torque Regain and HP drain.\n• Gambit conditions added: Main job is, Sub job is, Main or sub job is.\n• Sub Blue Mage sets blue magic at the real sub job level.\n• The Gauntlet: defeated monsters vanish for everyone.\n• Castle Zvahl Keep [S] teleporter pads work, opening the Throne Room path for Wings of the Goddess mission 37.\n• Mog House: a table holding flowerpots can be moved again.\n• Ark Angels: you can re-enter a friend\'s battle for a fight you already won.\n• Tebhi is visible again in Castle Oztroja (Beastmaster Artifact quest).\n• Squad beastmasters\' Snarl shifts hate to the jug pet; squad pets earn summoner credit against the Unleashed.\n• Gnoles use Plenilune Embrace and Call of the Moon, letting Blue Mage learn Plenilune Embrace.\n• Survival guides in past-era [S] zones are usable by any character who has opened a Cavernous Maw.\n• Home point or warp trips starting inside a Mog House and ending in that same city no longer drop you into a void.\n• !sigil gives a free Allied Forces\' Sigil anywhere (requires an Allied Forces medal); !sanction food now notes its longer food duration only applies in Aht Urhgan areas.' }, { title = 'Runes (2026-09-28)', note = '• Every experience kill also rolls for a Rune, separate from the DWSpoils roll (spoils odds unchanged); finds are announced server-wide with the gear type they fit.\n• 98 kinds, one per Super Auged augment, named by the augment\'s number in Roman numerals (Rune LXXVIII = HP, Rune XXXVII = Magic Evasion).\n• Runes are account-owned; any of your characters can spend them.\n• Fit rules match Super Auged: Dual Wield only on one-handed weapons, a weapon skill Rune only on that weapon type, a pet Rune only on gear a pet job can wear.\n• Applied at a random rank in the item\'s Super Auged range; it fills a free slot, or re-rolls the slot if the item already has that augment (no duplicates).\n• /spoils tabs: My Spoils, Runes, Hall of Four, Super Auged. Runes tab shows how many you hold and the min/max roll; Apply lists fitting gear in your bags.\n• Commands: !spoils runes; !spoils runegear XLV (shows fits, possible roll and the exact spend command).' }, { title = 'Other 2026-09-28 changes', note = '• Mastering an Esper now needs about 3,000 incredibly tough kills (3x); mastered Espers stay mastered and old progress counts toward the new total.\n• The 10x bonus in DWEsper and DWSpoils now only pays for real NMs: respawn timer of 1 hour or more, a placeholder spawn, or a popped NM (not e.g. Promyvion Strays).\n• Duplication exploits closed; gil placed in an open trade window cannot be spent elsewhere until the trade closes.\n• Fixed squad-only characters that were capped at level 50, held only 30 inventory slots and had no satchel.\n• The Throne Room hosts both Fell Shadow Lord raids and Nemesis fights; when occupied you are placed in a free arena rather than sent to town.\n• Addon windows drop far fewer updates.' }, { title = 'Relic, mythic and empyrean effects (2026-09-11)', note = '• Squad members wielding relic, mythic or empyrean weapons now get aftermath.\n• All 99 II and 119 II relics give the afterglow aftermath (previously plain level 99 aftermath).\n• Nine relics regain their additional effect above level 75.\n• Gjallarhorn 80/85/90/95 gain Charisma and instrument skill; Yoichinoyumi and Annihilator 119 III (quiverless, from the Dealer Moogle) gain the damage lines their bundled versions have.\n• Burtgang 99 now has aftermath; Tupsimati 95\'s wrong melee aftermath is fixed; Dealer Moogle 119 III Gastraphetes and Death Penalty get the right aftermath tier plus Barrage accuracy, Quick Draw damage and WS damage lines.\n• Gandiva and Armageddon now grant ranged aftermath at every step from 85 to 119 III.\n• Left alone: Aegis and Gjallarhorn 99 II (no aftermath or WS); Tizona\'s additional effect and Aymur\'s job line (no reliable source).' }, { title = 'Empyrean and Relic weapons at the Arms Dealer (/quests)', note = '• Empyreans (Almace, Caladbolg, Verethragna and others): 1000 Drift Coins; Daurdabla and Ochain: 1500. Sold at level 99 without afterglow.\n• Trade the weapon plus 300 Riftborn Boulders to Oboro in Port Jeuno for item level 119 (1000 Drift Coins + 7,500 Driftmarks total).\n• 119 to 119 III with afterglow: another 10,000 Riftborn Boulders (250,000 Driftmarks); 257,500 Driftmarks overall.\n• Daurdabla and Ochain stop at 99; the other fourteen go all the way.\n• Relics: level 75 for 250 Drift Coins; Magian Moogle trials take them 75 to 99, including Dynamis bosses.\n• Suggested relic route: do the Magian trials to 99 II (afterglow), which needs 250 Vials of Umbral Marrow (page 9 of the /raid shop, 100 Driftmarks each = 25,000).\n• Finished relic: 250 Drift Coins + 32,525 Driftmarks. A non-afterglow 99 still gets 119 from Oboro for 300 Plutons, but its III step costs the full 10,000 stones.\n• Oboro tallies stones handed in early; talk to him to see your balance.' }, { title = 'Armour ladder, Jeweler, blue magic display', note = '• Outfitter (/quests, Outfitter tab) prices: Artifact = 25 DC; Artifact +1 (lv 74) = 100 DC; Relic = 125 DC; Empyrean +2 (lv 85) = 200 DC.\n• The last three forge to item level 109 at the Driftmark forge (/raid, Reforge tab) for 1500 driftmarks, body 2250; requires Chains of Promathia finished on the account.\n• Upgrades follow retail lines (Fighter\'s +1 to Pummeler\'s, Warrior\'s to Agoge, Ravager\'s +2 to Boii, etc.).\n• Geomancer and Rune Fencer sets (Azimuth, Erilaz, Geomancy, Runeist) are sold complete on the Driftmark shop elite page: 1800, body 2700.\n• Jeweler tab on the Drift Board (Drift Coins, all Rare/Ex): Abyssal, Beastly, Bushinomimi, Knight\'s, Suppanomimi earrings 100; Brutal, Loquacious, Stealth earrings 200; Rajas, Sattva, Tamas rings 300. Typed: !drift jeweler, !drift jewelbuy.\n• /toau Blue Mage tab: hovering a spell shows description, set stat bonuses, job trait and points needed, level, MP cost and blue magic points.\n• Squad Blue Mages now receive the stat bonuses and job traits of their set spells.' }, { title = 'X-Magic (2026-08-31)', note = '• Ring augment from the Drift Exchange: each spell has a chance to trigger a free extra spell (no MP, no recast).\n• Choose one of five kinds when buying: Elements, Grace, Ruin, Siphon, Veil.\n• Elements (~38%): from an enemy-targeted spell, a tier-II nuke of another element (Fire, Blizzard, Aero, Thunder).\n• Grace (~40%): from an ally/self spell, Cure III, Regen, Protect or Shell.\n• Ruin (~48%): from an enemy spell, Bio, Dia, Gravity or Addle.\n• Siphon (~35%): from an enemy spell, Aspir or Drain.\n• Veil (~40%): from any spell, always on you: Stoneskin, Phalanx, Aquaveil or Blink.\n• Rates assume a 4-second cast; the chance scales with actual cast time (a 1-second cast gets about a quarter).' }, { title = 'Merit Points (2026-08-31)', note = '• Weapon Skill category combo total 15 to 70, so every weapon skill can be maxed; squad members inherit WS merits.\n• Both job ability merit groups 10 to 20 points on every job, judged at each member\'s own job.\n• HP, MP and the seven attributes cap at 30 upgrades (was 15): +300 HP, +300 MP, +30 attribute. Upgrade cap by level: 80-84 → 15, 85-89 → 18, 90-94 → 22, 95-98 → 26, 99 → 30.\n• Critical Hit Rate merits now apply to squad members\' normal attacks too.\n• Lowering a merit refunds its point.\n• Merits are still set in your Mog House.' }, { title = 'Mounts, gambits, Relic Reforge (2026-08-31)', note = '• /cpx Goods tab has a Mounts section, payable in gil or Conquest Points; you buy the unlock item/key item and trade it to Mapitoto in Upper Jeuno (needs Chocobo License or Trainer\'s Whistle).\n• DWGambits Stance options added: Hug the Mob (about 1 yalm out, e.g. for Sneak Attack onto your tank), 18 feet back, 24 feet back.\n• Relic Reforge is the last tab of the /raid shop: Dynamis armour to iLvl 109 for 1,500 driftmarks (bodies 2,250).\n• Only lists items in your bags; Reforge, read the quote, confirm within 60 seconds. Worn gear is refused; failures refund.\n• Requirements: Chains of Promathia completed by any character on the account (counted retroactively) and the item level cap. GEO and RUN use the Outfitter instead.\n• Typed: !raid reforge, !raid reforge <item id>, !raid confirm.' }, { title = 'Pop-Items shelf (2026-08-31)', note = '• Fourth Drift Board storefront, priced in items (hundred-piece + testimony): five tiers, twenty keys.\n• Curiosities 1+1: old camped NMs, ranging from Delkfutt\'s giants up to the Chaos Elemental.\n• Hunts 3+2: Hakutaku, Tarasque, Ullikummi, Wulgaru.\n• Sky 6+3: Seiryu, Suzaku, Byakko, Genbu (sold as the gem-and-stone pair).\n• Kings 9+4: Fafnir, Behemoth, Adamantoise. Kings HQ 20+5: Nidhogg, King Behemoth, Aspidochelone.\n• Payment comes from your bag only, not the warehouse; a refusal lists what is missing.\n• Take the pop item to the ??? in the named zone.\n• Not sold: Kirin\'s four seals, the Pandemonium Key, sea pop items.\n• Typed: !drift pops, !drift popbuy <row number>, !drift confirm.' }, { title = 'Dynamis timer, bags, fixes (2026-08-31)', note = '• Dynamis cooldown is 3 hours (was 6), one shared timer for all Dynamis zones.\n• /bags rows (yours and offline alts\') add Stash (straight to account warehouse; retrieve via /warehouse) and Trash (asks first, warns in red for rare, ex or augmented).\n• Typed: !squad stash, !squad trash (trash needs an explicit quantity).\n• Wyvern Elemental and Healing Breath now reach alt-trusts, choosing the neediest member in range.\n• Players now trigger the "target was hit" events for spells, abilities and weaponskills.\n• Kill feed is colour-coded in Window 2; /quests feed off turns it off.' }, { title = 'Weapon Burst (2026-08-30)', note = '• Weapon augment: each attack round has a chance to cast a real spell on the target; it can magic burst inside a skillchain window.\n• Rate is normalized by weapon delay, so every weapon gets about the same procs per minute.\n• One per weapon (you can swap its element); main hand, off hand or ranged only, never ammo or stackables; at most one burst per round; squad weapons burst too.\n• Fire, Ice, Wind, Earth, Thunder, Water: that element\'s tier I–IV, about 38% per round, weighted to lower tiers.\n• Light (30%): Fire II, Thunder II or Aero II. Dark (30%): Stone II, Water II or Blizzard II.\n• Shield (40%): Blink, Stoneskin, Aquaveil or Haste on you. Enfeeble (60%): the enemy gets Poison, Blind, Paralyze or Slow.\n• Earn Burst Tokens in the Gauntlet: type /arena with your squad or a group of up to 18 players; 50 floors; clearing floor N pays each real player N tokens plus 160 EXP and 120 capacity points per floor.\n• Cost: 5,000 Burst Tokens + 1,000 Drift Coins, on the permanent shelf of the Drift Exchange (/quests, Exchange tab).\n• Typed: !drift exchange (shelf and token balance); !drift augment b1 Ridill (prices a Fire burst for Ridill; confirm to buy).\n• Examining the weapon in the native menu shows an augment number; the /quests window shows the name.' }, { title = 'Conquest Point Exchange (2026-08-29)', note = '• Type /cpx. Nation tabs (San d\'Oria, Bastok, Windurst) by rank; buy from any nation and any rank with your own CP at guard prices.\n• Rank still gives +100 Warehouse slots per rank and triples the mission completion bonus.\n• Allied Sundries tab: Instant Warp and Instant Reraise scrolls, Return, Homing and Warp rings, trust ciphers. EXP bands stay with the gate guards.\n• Weapons, Armor, Scrolls and Goods tabs: 1,400+ merchant and guild items, priced in gil (max-fame best price) or CP at 2 gil per point.\n• Hover shows a full item card; Search covers all shelves; buy with Buy then Confirm. Item-level release schedule still applies.\n• Typed: !cpx, !cpx find bronze, !cpx buy 104609 gil 12, !cpx confirm.\n• Part of the Default addon set; otherwise enable dwcpx in the launcher Addons tab or /addon load dwcpx.' }, { title = 'ArmsDealer relics (2026-08-20)', note = '• /quests, ArmsDealer tab, Dynamis Weapons case: all fifteen level 75 relics, 250 Drift Coins each, Rare/Ex.\n• H2H: Spharai. Dagger: Mandau. Sword: Excalibur. GS: Ragnarok. Axe: Guttler. GA: Bravura. Polearm: Gungnir. Scythe: Apocalypse. Katana: Kikoku. GK: Amanomurakumo. Club: Mjollnir. Staff: Claustrum. Marksmanship: Annihilator. Archery: Yoichinoyumi. Bard horn: Gjallarhorn.\n• Click Buy, then Confirm before the timer runs out. Typed: !drift arms dynamis, !drift armsbuy <number>, !drift confirm.\n• Same patch: lots of item-level gear that showed stats but applied none now applies them; some procs and set bonuses are still pending.' }, { title = 'Outfitter, daily coins, no one-shots (2026-08-19)', note = '• /quests Outfitter tab: level 50-60 artifact armour for all twenty classic jobs, 25 Drift Coins per piece, Rare/Ex (movable to your own characters via DWBags or the Warehouse only).\n• Artifact quests still award the same pieces free.\n• The first login on your account each real day (JP midnight reset) pays 50 Drift Coins to the account purse.\n• Enemy ancient magic deals half damage.\n• Monsters no longer use self-destruct moves (Self-Destruct, goblin bomb backfire, Final Sting, Meltdown, Mine Blast and similar).\n• Exceptions: a Beastmaster\'s charmed bomb or bee keeps Self-Destruct/Final Sting, and scripted battlefield bosses still explode.\n• The launcher updates dwquest; !drift help lists typed commands.' }, { title = 'Driftmark armory (2026-08-18)', note = '• /raid (or !raid shop) Driftmark shop has five pages: Supplies; One-handed & shields; Two-handed; Ranged & ammo (stacks of 99); Armor.\n• Armour sets: Karieyh (heavy jobs), Orvail (mages), Thurandaut (others).\n• All item level 100 or higher; the +1 is sold where one exists. Ingots are retired.\n• Approximate prices: one-hander 1,500 Driftmarks, two-hander 2,000, armour 600–900, ammo 40 per stack.' }, { title = 'Drift Exchange augments (2026-08-06)', note = '• A daily set of four augment offers, rerolled by the Vana\'diel clock, is applied directly to gear in your bags or an offline alt\'s bags.\n• !drift augments (today\'s offers); !drift slots Bronze Sword (slots used); !drift augment x1 Bronze Sword (quote); !drift confirm (only command that spends).\n• Each item has four augment slots; when full, name a slot to overwrite, e.g. !drift augment x1 Bronze Sword #2 (that augment is lost).\n• An item cannot take the same augment twice.\n• Target an alt with @Name, e.g. !drift augment x1 @Yakapo Ash Staff.\n• Augmented items become account-exclusive: no auction house, trade or bazaar; delivery box only to your own characters.\n• /quests Exchange tab: offers, prices, countdown to next roll, On: dropdown for alts, and a picker showing only eligible gear with used-slot counts.\n• Ineligible: equipped, enchanted, weapon-skill weapons, items priced in your bazaar, non-equipment.\n• Picking asks for a quote, then Confirm; full items show a Replace button per slot. !drift gear lists augmentable gear.' }, { title = 'Rare drops go to your other characters (2026-08-02)', note = '• If your current character already holds a dropped Rare, it goes to the first character in your list without one; chat names who got it and which bag.\n• Lost only once every character on the account has a copy.\n• Bag follows that character\'s layout (!squad bagpref); full bags send it to the delivery box, collected at next summon (!squad box).\n• Pass still discards the item; leaving it alone sends it to the next character. No squad needed.\n• !squad fetch <character> <item> pulls it to your current character.\n• Applies when looting alone (squad trusts take no pool share); real parties are unchanged.' }, { title = 'Drops, gil, Treasure Hunter, NMs', note = '• All drop rates x2.\n• Every enemy drops 5 gil per mob level, plus naturally dropped gil doubled.\n• Treasure Hunter uses the retail curve.\n• Lottery NMs pop 5x as often from placeholders, with spawn cooldowns halved.\n• Coffer illusion time 1–5 minutes (retail 30–60).\n• ENM key items recharge in 24 hours.\n• Dynamis re-entry 3 hours.' }, { title = 'Treasure caskets (2026-07-27)', note = '• 2.5% chance (about 1 in 40) per experience kill in the 60 casket zones; 75% are the locked brown chest (about 1 kill in 53); the rest are blue temp-item chests.\n• Lock: two-digit combination with higher/lower clues plus examine hints; 8 attempts; chest lasts 3 minutes.\n• Locked chests fill all four slots from the zone table, with a 5% per-slot chance of a regional item from elsewhere.\n• Every weapon and armour piece rolls its own unique augments.\n• Any item: HP, MP, seven base stats, elemental resistance.\n• Armour: DEF, Evasion, Magic Evasion, Regen, Refresh, Fast Cast, Cure potency, Subtle Blow, physical/magic/breath damage taken down, Enmity up/down, spell interruption down; rarely Treasure Hunter+1 or Gilfinder.\n• Melee weapons: damage, Accuracy, Attack, crit rate and damage, Double/Triple Attack, Store TP, Zanshin, Weapon Skill Accuracy, own weapon skill bonus. Ranged: similar list built on Rng. Atk. and Rng. Acc.\n• Clubs and staves add Magic Accuracy, Magic Attack Bonus, Magic Damage, healing/elemental/enfeebling recast reduction and magic crit rate. Shields: Shield skill, Shield Mastery.\n• Augment count by mob level: two weak ones at low level, three from around 33, four from the mid-60s, full ranges by 75.\n• Crafting material slots give 4; arrowheads, bolt heads and fletchings come in stacks of 99.' } } },
    { name = 'Endgame content', group = 'Server', desc = 'Summary of DriftwoodXI\'s custom endgame systems (Arena, Esper, Nemesis, Raid, Unleashed) and their patch notes, newest first; later notes supersede earlier ones. Source: https://xi.driftwoodgaming.com/features/dwarena, https://xi.driftwoodgaming.com/features/dwesper, https://xi.driftwoodgaming.com/features/dwnemesis, https://xi.driftwoodgaming.com/features/dwraid, https://xi.driftwoodgaming.com/features/dwunleashed, https://xi.driftwoodgaming.com/news/nemesis-warehouse-testimonies-and-gambit-clipboard, https://xi.driftwoodgaming.com/news/magicite-rebalance-and-bug-fixes, https://xi.driftwoodgaming.com/news/aht-urhgan-raids-alexander-raubahn-gessho, https://xi.driftwoodgaming.com/news/break-damage-limit, https://xi.driftwoodgaming.com/news/nemesis-plus-one-gear-super-auged-and-a-window-dock, https://xi.driftwoodgaming.com/news/espers-magicite-and-attunement, https://xi.driftwoodgaming.com/news/unleashed, https://xi.driftwoodgaming.com/news/the-circuit-and-the-grand-circuit, https://xi.driftwoodgaming.com/news/chain-trials-and-three-new-bosses, https://xi.driftwoodgaming.com/news/any-arena-any-boss, https://xi.driftwoodgaming.com/news/the-end-game-balancing-act-part-one, https://xi.driftwoodgaming.com/news/nemesis, https://xi.driftwoodgaming.com/news/wind-pair-and-seven-fixes, https://xi.driftwoodgaming.com/news/stone-and-tide-six-trials, https://xi.driftwoodgaming.com/news/the-raid-grows', steps = { { title = 'DWArena', note = '• Gauntlet: alliance wave survival, floors 1-50, in Qu\'bia Arena (three battlegrounds).\n• Open with /arena: shows which battlegrounds are live and for how long, warps the whole party/alliance (up to 18 seats; alt-trusts can be summoned inside) and returns you to your starting tile.' }, { title = 'DWEsper', note = '• Open with /esper: every kill gives Magicite; 32 Espers to create and attune, lending spells and abilities to any job.\n• Intended as the long-term progression after Ascension and job mastery.' }, { title = 'DWNemesis', note = '• Open with /nemesis: 240 famous NMs (Leaping Lizzy to Kirin), solo or party, in a private arena at wild level +100 (cap 160).\n• Spawned from home-zone data, so same look, behaviour and drops; own chest, 1-4 random augments, trophies toward each NM\'s item level 119 +1.' }, { title = 'DWRaid', note = '• Raid board window: 18 boss trials over 13 venues, enterable from anywhere, now including Chains of Promathia content.\n• Below the base item level, each element has its own boss.' }, { title = 'DWUnleashed', note = '• Open with /unleashed: a Legend-tier Nemesis NM spawns on each even-numbered hour, US Eastern time, all day at one of 22 outdoor sites near an outpost or home point.\n• Server announces the monster, zone and landmark (no coordinates); no claim or party needed, and every participating account is paid at the kill.' }, { title = '2026-10-24: Warehouse testimonies, DWGambits clipboard, Adoulin prep', note = '• Nemesis Job Testimonies can now be drawn from your account\'s DWWarehouse as well as your bag, including for Restart this Battle.\n• Fee unchanged: Field 1, Dungeon 2, Legend 3 different job testimonies; each job counts once across bag + warehouse.\n• The job you hold most of is spent first; bag copy before warehouse copy.\n• Cancelled/failed entries refund testimonies to the warehouse; any character\'s banked testimonies count; each takes one warehouse slot.\n• On by default per character; turn off with the checkbox in /nemesis or !nemesis wh off (!nemesis wh on to re-enable).' }, { title = 'DWGambits changes (2026-10-24)', note = '• Rule clipboard: right-click a rule number > Copy rule, then Paste below on a row menu or Paste rule next to Add rule; works on shipped presets.\n• Missing effect picker gained 53 rows (all player spell/JA/ward effects), e.g. remaining BRD songs (Prelude, Sirvente, Dirge, Mambo, Mazurka, Hymnus, Operetta, Aubade, Pastoral, Fantasia, Capriccio, Round, Gavotte, Nocturne), Regain, Pax, Migawari, Store TP, Brazen Rush, Flee, Cascade, Apogee, Shining Ruby, Earthen Armor.\n• Crusade row renamed Enmity Boost (Crusade).\n• Best of family ladders: 72 to 115 (Holy, Diaga, Banishga, Cura, Reraise, Enlight, Temper, Flurry, ancient magic, ninjutsu nukes, Tonko, Lullabies, Prelude, Mambo, Operetta, Mazurka, per-stat Etude, per-element Carol).\n• Scherzo: squad bard now walks to you to sing it; multiple Carol/Etude ladder rules each sing their own element.' }, { title = 'Seekers of Adoulin groundwork (2026-10-24)', note = '• Adoulin is not open and has no date; prep is not reachable yet.\n• Adoulin zones will be about level 150-180 (retail 99-139).\n• Prepared: an [SOA] weekly (25 kills of Adoulin-only families, 115 DC) and a final DWRaid tier, Adoulin, for accounts that finished the SoA story.\n• Finish SoA Missions skip audited: pays mission EXP, starts the next story step, grants the Western Adoulin waypoint.\n• Weekly lists re-sorted: [COP] can offer Bugard, Cluster, Diremite, Flytrap, Fomor, Hippogryph, Taurus again; [TOAU] can offer Chigoe, Colibri, Flan, Frog, Imp.' }, { title = 'Other fixes (2026-10-24)', note = '• Spirit Bond now splits wyvern damage taken (after its own reduction) evenly with you; your share ignores your Damage Taken/Phalanx, Stoneskin can absorb it, and it can KO you.\n• Mount Zhayolm Home Point #1 no longer drops you under the map.\n• Poroggo count as Frog family for DWQuest; Frog contracts moved from [WOTG] to [TOAU] weekly.\n• Refused NPC trades now return items (fixes re-popping Animated weapons in Dynamis - Xarcabard).\n• Moonbeam Cape now applies DEF 30, HP +250, Damage Taken -5%.\n• The 23 Oct disconnect at the Misareaux Unleashed was a network outage between servers.\n• Update addons through the launcher for the new Nemesis and DWGambits windows.' }, { title = '2026-10-04: Magicite rebalance', note = '• Recipe = 1 element Magicite type + 2 job Magicite types; every job now appears in 2-4 recipes (previously BLM was in 9 and MNK, BLU, PUP, GEO, RUN in none).\n• WAR and BLM appear most (most common drops); RUN, GEO, PUP, DNC, SCH, DRG least (earned mostly by playing them).\n• Eight Espers changed element to reduce demand for rare Ice/Light/Thunder; e.g. Kirin, Unicorn, Seraph Light to Water; Phantom Dark to Wind; Cactuar Earth to Wind; Ragnarok Ice to Fire.\n• Prices, tiers and grants unchanged; existing Espers unaffected.' }, { title = 'Bug fixes (2026-10-04)', note = '• Squad can cast job point gift spells (tier VI nukes, Aspir III, Death, Full Cure, Utsusemi: San) once your JP on that job unlocks them.\n• Unleashed messages are plain text so they display fully; Unleashed, Nemesis and raid bosses are exempt from day/night and weather despawns.\n• !raid next and !raid enter accept full fight/trial names or any unambiguous part (e.g. !raid next Moonlit Carbuncle).\n• EXP, limit and capacity lines always go to the battle window (gil lines unchanged).\n• Taking a Promyvion stream clears you and pets from strays\' hate lists.\n• BST Ready moves fixed: Fluid Toss, Fluid Spread, Digest, Pecking Flurry, Sickle Slash, Acid Spray, Spider Web.\n• Fubruhn\'s locker expansion (Aht Urhgan Whitegate) shows the correct coin cost at 40 and 50 slots.\n• Update through the launcher for the dwquest and dwchat fixes.' }, { title = '2026-10-02: Aht Urhgan raid difficulty', note = '• New bosses Immutable Alexander, Undying Raubahn, Shadowmaster Gessho; Alexander is the server\'s hardest fight.\n• New top rung Aht Urhgan above Promyvion (only these three bosses): 80 Driftmarks per clear, 160 for first clear of the day.\n• Requires an account character to have finished the ToAU story (The Empress Crowned); every party member needs it. Promyvion still needs CoP; each rung checks its own story.\n• Chain trials stop at the highest rung everyone qualifies for.\n• Enter from the raid window (Aht Urhgan row) or type full names: !raid enter alexander ahturhgan or !raid enter aht urhgan raubahn.' }, { title = 'Immutable Alexander (Jade Sepulcher)', note = '• Highest HP of any raid boss at every difficulty.\n• Aegis: he warns physical or magical, then 5 s later blocks part of that type (all of it on the top two difficulties) until the next switch.\n• Stun, sleep, petrify, terror or amnesia as the aegis turns breaks it until the next one.\n• Normal and up: at 75/50/25% he uses Perfect Defense then Divine Judgment on the party.\n• Time limit from 15 min (Easy) down to 8 min (Aht Urhgan); expiry loses the trial.\n• Archaic Gears add on harder difficulties.' }, { title = 'Undying Raubahn (Jade Sepulcher)', note = '• Casts blue magic; blessing rises: 1 (Easy/Normal), 2 (Difficult/Savage), 3 (Promyvion/Aht Urhgan); a lethal hit leaves him at 1 HP.\n• At 1 HP you have a few seconds (10 on Easy, 4 on Aht Urhgan) to stun him for a permanent kill.\n• Otherwise he revives at 30-75% HP and hits harder each time; after the last rise he dies normally.\n• Immortal soldiers add on harder difficulties.' }, { title = 'Shadowmaster Gessho (Talacca Cove)', note = '• He warns he is forming seals; 5 s later he splits into 2-5 shadows and is immune while any stand.\n• Each shadow lasts 25 s (Easy) to 12 s (Aht Urhgan); a surviving shadow uses Happobarai (AoE damage + stun) and vanishes.\n• Stun him while forming seals to prevent shadows.\n• Harder difficulties add extra non-bursting shadows. All three bosses run Easy and up.' }, { title = 'Other changes (2026-10-02)', note = '• Apex and Locus mobs: double EXP and limit points, and as much as 60,000 CP each kill.\n• !squad tutor converts your merit points to squad EXP (10,000 each); no number = preview.\n• Unleashed announcements now have a banner and colour; Uleguerand Range site moved to flat ground.\n• DWPort: Lufaise Meadows and Misareaux Coast unlock at CoP mission 2-1.\n• DWBags Scrolls filter now includes Haste II, Distract, Frazzle, Flurry, Gekka: Ichi, Yain: Ichi.\n• /report includes zones of all party and squad members.' }, { title = '2026-10-01: Break Damage Limit', note = '• New augment: each point raises your 99,999 damage cap by 10,000 (+1 = 109,999; +10 = 199,999; max +90 = 999,999); adds no damage by itself.\n• Stacks across gear; each piece can carry it once.\n• Applies to all damage types (WS, spells, MB, JAs, skillchains, melee, ranged, Lunge, enspells, item effects); pets use your cap; squad members need their own.\n• Enchanter (/quests daily rotation, not every day): Break Damage Limit+1 for 1,000 Drift Coins, any gear slot.\n• Rune MMXXIX (99th Rune, same rarity as others; Rune-only): +2 to +5 on any gear; reusing re-rolls.\n• Battle log caps display at 131,071; bigger hits print a [Break Damage Limit] chat line (max 4 per 2 s) and full damage is dealt.\n• Only DriftwoodXI windows (bags, Enchanter, Augments tab, /spoils) name the augment.\n• Fixed: crash when leaving Al\'Taieu as an Aern revived.' }, { title = '2026-09-26: Nemesis +1 gear and Super Auged', note = '• 240 Nemesis NMs have an item level 119 +1 of their signature item (same look) with four Super Auged augments.\n• Each victory gives the account one trophy (multiple own characters = one); 50 trophies buy the +1.\n• Buy in /nemesis: Trophies column and Buy button in tier tables, Trophies tab sorted by affordability; confirm before spending.\n• Needs launcher 0.36.0 for names/icons; Buy waits until the game shows the item name.\n• Super Auged = stronger augment pool beyond normal caps; 5% of won DWSpoils rolls are Super Auged (1-4 augments), announced, listed in /spoils Super Auged tab.' }, { title = 'Hover Shot, charm, spell damage (2026-09-26)', note = '• RNG learns Hover Shot at 95: 1 h duration, 3 min recast, no movement needed; each completed ranged attack/WS adds a stack, max 25.\n• Per stack: +4% ranged damage, +4 ranged accuracy, -2 enmity, +4 magic accuracy on magical ranged WS; resets on target change; squad RNGs and the Skirmisher preset use it.\n• If you are charmed your squad stays and fights the charmer; mobs can charm squad members (released on charm end, charmer death or zoning); orders wait while charmed, dismiss works.\n• Vs top bosses, Blue Magic, Primal Rend, Holy Mist, Meteorite, Swipe, Lunge and multi-hit mob/pet skills always deal damage; cap 99,999.\n• Spell interruption rate down augments now work; DWPort adds Group by expansion; DWUnleashed History shows Esper Cores paid.' }, { title = 'Window dock (2026-09-26)', note = '• /dw rail shows a column of buttons toggling each DriftwoodXI window; Hub and Options included.\n• /dw options per window: On rail, With /dw, At login, Up/Down ordering; saved per character.\n• Window titles shortened (e.g. Bags), so each resets to default position once.\n• Window commands accept open/close, e.g. /bags open, /bags close.' }, { title = '2026-09-24: Espers and Magicite', note = '• Open with /esper or type !esper; !esper roster lists Espers and prices.\n• Any kill that gives you EXP gives Magicite: 30 counters (8 elements, 22 jobs), character-bound currency, not items.\n• Each kill pays the mob\'s element (or family element, e.g. beasts/lizards Earth, birds Wind, undead/demons Dark, aquans Water), the mob\'s job, and your main job; elementless humanoids pay your job twice.\n• Amount by con: 1 up to Even Match, 2 Tough, 3 Very Tough, 5 Incredibly Tough; NMs x10; all paid characters receive it.\n• 32 Espers: the 31 from FFVI plus Driftwood; mastering Driftwood unlocks a second Esper slot.' }, { title = 'Creating and equipping Espers', note = '• !esper create <name> or the tile\'s Create button; all-or-nothing.\n• Costs: Minor = 300 element, 150 each job, 1 core; Major = 600 element, 300 each job, 1 core; Greater = 1000 element, 500 each job, 1 core; Driftwood 100 of all 30 kinds, 3 cores, all other Espers mastered.\n• Examples: Shiva (Minor, Ice, BLM/RDM) Blizzard I-III, INT, Magic Accuracy, Fast Cast; Cait Sith (Minor, Light, THF/COR) Steal, Treasure Hunter; Carbuncle (Major) Protect, Shell, Haste; Gilgamesh (Greater) Dual Wield, Provoke.\n• One equipped Esper gives its full grants and stat line; unequipping an unmastered one removes grants but keeps attunement.\n• Swapping has no recast; not allowed while engaged.' }, { title = 'Attunement and mastery', note = '• Attunes only while equipped, on EXP-paying kills, weighted like Magicite (NMs x10); progress shown per 10%.\n• Target pace: roughly 1,000 kills of mobs 20-40 levels above you per Esper; Even Match = 1/10 of Incredibly Tough.\n• At 100% it is mastered: grants and stat line stay on every job permanently.\n• Mastered + equipped doubles the stat line (e.g. Refresh +1 to +2, Dual Wield I to II, Fast Cast +1% to +2%).' }, { title = 'Boss rewards, Cores, casting, squad', note = '• Unleashed kill: 0.5% attunement, 25 boss-element + 25 your-job Magicite.\n• DWRaid clear: 0.2%, 10 job. Nemesis defeat: 0.2%, 10 mob-element + 10 job. Gauntlet floor: 0.05%, 5 job.\n• Esper Cores (wallet counter, untradeable) come only from Unleashed: 20% roll per paid account on the present character; 15th dry kill guaranteed.\n• Lent spells/abilities are used via the Grants tab or !esper cast Blizzard III / !esper use Meditate; no target = offensive on current target, beneficial on self; macros like /ma for lent spells are routed while the addon is loaded.\n• Squad members inherit stat lines (mastered ones and the equipped Esper), but not lent spells/abilities.\n• Magicite/attunement cannot be farmed by alts; no Release/Astral Flow summon yet.' }, { title = 'Other changes (2026-09-24)', note = '• Automaton parts are account-wide (fixes empty Equipment menu for Drift Board PUP unlocks).\n• !allpup deploy t now sticks on idle squads; squad COR rolls usable immediately; squad wears JP superior gear.\n• Aspir III (550 JP gift, BLM/GEO) fixed; Path of Darkness Alzadaal lamp fixed.\n• Happo Shuriken craftable (Smithing 107); Waktza Rostrum on DWRaid Materials; Roppo Shuriken x99 on DWRaid ammo for 40 Driftmarks.\n• Lufaise Meadows Unleashed site moved next to the Tavnazian Archipelago outpost.' }, { title = '2026-09-18: Unleashed', note = '• Open with /unleashed (or !unleashed / !unl); shows location, phase, HP and participants.\n• Every 2-3 hours (time hidden) a Legend-tier Nemesis NM appears at one of 22 outdoor sites near an outpost or home point; zone and landmark are announced.\n• It stays passive and invulnerable for 10 minutes, then a wake announcement follows.\n• No claim or party: anyone in the zone can attack, heal or buff, and all of it counts.\n• Takes only 5% damage until 4 different accounts join; stays open after.\n• Only the kill pays; no drops.' }, { title = 'Unleashed rewards and rules', note = '• 45 Drift Coins, +1 per paid account beyond 6, up to 75 (36 accounts).\n• First Unleashed kill per Japanese day pays double (90-150).\n• Qualify with 1 minute on hate list or 1% of its HP in damage.\n• Plus a flat 100 Driftmarks per paid account (not doubled or scaled).\n• Its anchored home point/outpost teleport is free while it stands (/port, !port, counter) if already attuned.\n• Weekly Drift Board contract: answer 3 Unleashed for 90 Drift Coins (counted by pay); leaderboards Unleashed answered and Unleashed top damage.\n• Kill message names top damage and share, top enmity, final blow, first hit, and paid account count.\n• AoE hits anyone nearby; unattended spawns leave with no pay and the next comes in about 1 hour; restarts reset the clock to 2-3 hours.' }, { title = '2026-09-14: The Circuit and Grand Circuit', note = '• Circuit: !raid enter tidebound circuit (or Circuit button) runs a Chain Trial from Easy up, and you keep choosing the next boss.\n• Tier Circuit: !raid enter tidebound savage circuit (or Tier Circuit button) runs every boss at one tier.\n• Ends after 90 s idle or !raid leave; every rung is paid on its kill.\n• Grand Circuit: clear every boss in one run; time from first spawn to last kill feeds leaderboards Grand Circuit, every rung and Grand Circuit, Savage (personal rows).\n• Variety chain now counts all rungs of one boss as one link.\n• All raid bosses: double max HP and +20% attack, accuracy, primary stats and defence.\n• Each venue has three arenas; full venues overflow to the next free one.' }, { title = 'Other changes (2026-09-14)', note = '• BRD reforge fixed: Aoidos\' +2 to Fili, Choral +1 to Brioso.\n• Nemesis Jailer of Faith door fixed; non-augmentable item families no longer show augments; Mercy no longer climbs on no-gear tables.\n• Warehouse and bag windows: Trash Selected and Vendor Selected (one confirmation), per-row Sell.\n• Politics window: phase line, How it works tab, hover help, !politics help; pledge announcements limited to once per 4 hours.\n• Update dwraid, dwleaderboard, dwwarehouse, dwbags, dwpolitics via the launcher.' }, { title = '2026-09-13: Chain Trials and new bosses', note = '• Chain Trials: every difficulty of one boss in one arena, paid per kill.\n• Roster: 18 trials across 13 venues.\n• Fell Shadow Lord live in the Throne Room: siphon on a timer, at each 25% HP, and on his blade.\n• Moonlit Carbuncle (Full Moon Fountain, light): ruby glows, 5 s later Healing Ruby unless he is stunned or asleep.\n• Verglas Shiva (Cloister of Frost): ice spikes grow with hits and can paralyze; timed arena-wide 30 s paralysis.\n• Keraunos Ramuh (Cloister of Storms): shock spikes stun attackers; timed arena-wide damage as a share of max HP (over half at Savage), can kill.\n• Tidebound Colossus, Gravegaze Medusa, Cragmaw Basilisk, Avalanche Tzar raised to mid-roster; Tzar fuse 300/240/180/120 s by tier, 90 s at Promyvion.' }, { title = 'Other changes (2026-09-13)', note = '• New leaderboards: Highest Chocobo Digging Skill, Most Drift Coins Earned, Most Driftmarks Earned (earned only; credited to most-played character).\n• Blue magic learn chance tripled on eligible kills.\n• Gambit share codes keep bard Sings to / Seconds left cells; squad SMN resummons on recast.\n• Haste II confirmed: replaces Haste at 30%, does not stack.\n• DWPolitics Elections tab no longer closes the window.\n• Launcher 0.35.0: controller editor can bind Target Nearby NPC, Jump, Map, Shut Down.' }, { title = '2026-09-10: Any Arena, Any Boss', note = '• Each trial has a home shrine but uses any free shrine when home is full; refusal only when all 27 arenas are busy.\n• Occupancy board shows every shrine\'s arenas plus running copies and free arenas per trial.\n• DWBags (PUP): unlock an automaton part from an alt\'s bag (consumes it, like trading to Tateeya); name an alt\'s automaton on the Gear tab; both need the alt logged out.\n• Aht Urhgan battlefields pay Chunks of Beitetsu once per character per fight: 5 job testimony, 10 quest, 20 story; finishing the story (Empress crowned) pays 135.\n• DWPort needs the Boarding Permit from Faursel (Lower Jeuno), given when The Road to Aht Urhgan is completed.\n• Aht Urhgan opened 21 September 2026 (per a 2026-09-21 update).\n• Update dwraid, dwbags, dwport via the launcher.' }, { title = '2026-09-10: End-Game Balancing Act, Part One', note = '• The first-of-the-day clear of each trial and tier is left as it was; the repeat and chain rules below concern the second clear onward.\n• Day element: the Vana\'diel day changes every 57.6 min through all eight elements; a trial matching the day\'s element pays +50% on its entire clear payout, both base Driftmarks and the first-of-the-day bonus. The board shows the favoured element.\n• Variety chain: a different trial within 90 minutes adds +10% per link up to +50%; repeating a trial in the chain resets it, timeout ends it.\n• Same trial and tier repeats per day: 2nd 75%, 3rd 50%, 4th+ 25% of base; resets at Japanese midnight; all three rules are account-wide.\n• Stones now drop: Byakko, Genbu, Seiryu, Suzaku 3 Pluton + 50% for a 4th; Ru\'Aun, Ve\'Lugannon, Ru\'Avitau pop NMs 1 each.\n• Six Jailers 3 Riftborn Boulders + 50% for a 4th; Jailer of Love 6; Ix\'Aern 2.\n• Aht Urhgan: Tinnin, Sarameya, Tyger 6 Beitetsu; Cerberus, Hydra, Khimaira 4; other Zeni NMs 2; Salvage chariots 4.\n• Kirin, Absolute Virtue, Pandemonium Warden drop all three; normal drops (pool, TH, drop rate, /scan); Materials page still sells them at the same prices.' }, { title = 'Nemesis and other changes (2026-09-10)', note = '• Nemesis grows to 247 NMs (Sky gods and pops, Sea Jailers, Absolute Virtue, 40 Zeni NMs, Aht Urhgan kings, 4 Salvage chariots, 84 more classics).\n• Gil fees halved: Field 10,000, Dungeon 25,000, Legend 75,000; testimonies unchanged.\n• Each chest has a 1-in-10 chance of a Pluton, Beitetsu or Riftborn Boulder (does not affect Mercy).\n• Pop-Items shelf hundred-piece cost: Hunts 2, Sky 3, Kings 4, Kings HQ 5.\n• Squad weapon skills now use the real weapon (were about 75%); 42 more buffs on the gambit enhancing shelf.\n• Launcher account deletion: password + registered email, 72-hour hold.\n• Update dwraid and dwnemesis via the launcher.' }, { title = '2026-09-05: Nemesis launch', note = '• Open /nemesis (or !nemesis / !nem); each row shows wild/arena level, home zone, signature drop and rate, your kills, best time, drops, Enter.\n• Fee is paid per real player at the door; squad alt-trusts are free.\n• Warped to the least busy venue: Throne Room, Chamber of Oracles, Sacrificial Chamber (3 arenas each, 9 runs).\n• One NM, 15-minute limit, at wild level +100 (capped at 175 at launch).\n• On the kill an Armoury Crate appears; each real player gets their own roll of the full drop table.\n• You return to your starting tile; /port and !home work inside.' }, { title = 'Nemesis fees and loot (2026-09-05)', note = '• Field (wild 1-40, arena 101-140): 20,000 gil + 1 Job Testimony.\n• Dungeon (41-70, arena 141-170): 50,000 gil + 3 different testimonies.\n• Legend (71+, arena 171-175): 150,000 gil + 5 different testimonies; one kill per Legend per account every 20 hours from the kill.\n• Uses the 20 Job Testimony items, lowest-numbered first; no refund on wipe or timeout.\n• Drops use the real table and rate with server multiplier; gear gets augments: 1 (60%), 2 (25%), 3 (14%), 4 (1%).\n• Third/fourth augments come from a premium list: Double Attack, Triple Attack, Store TP, Fast Cast, Refresh, Regen, Treasure Hunter, crit rate/damage, Conserve MP.\n• Augmented gear is account-bound (move via DWBags and Warehouse); no Weapon Burst or X-Magic augments.' }, { title = 'Nemesis rules (2026-09-05)', note = '• Mercy: after 8 gearless chests from one NM, the 9th has gear.\n• Ledger tab (per account): kills, fastest kill, gear drops, Mercy count; NMs whose 4-augment drop is unclaimed are marked, and the first claimant is named.\n• Every 4-augment drop is announced server-wide.\n• Needs the dwnemesis addon, gil and testimonies, 1-6 real players or you plus squad; no level cap.\n• Entry refused if anyone is dead, zoning, in a cutscene or another battlefield, level-synced or on a boat.\n• 5-minute cooldown after any exit.\n• Launch roster: 100 NMs incl. 36 Field (Leaping Lizzy, Jaggedy-Eared Jack, Valkurm Emperor, Argus, Golden Bat, Mee Deggi, Quu Domi, Leech King); list is add-only.\n• Wild kings and Pop-Items still available.' }, { title = '2026-08-27: Cloister of Gales and raid retune', note = '• Board: 8 trials, 4 shrines, 12 arenas.\n• Zephyr Seraph: airborne behind blink shadows, may regain one when hit; removing all grounds it for 12 s.\n• Howlmane Manticore: shadows it regains build a gale that speeds it up and is released on the party; deny shadows.\n• Tidebound Colossus 2x HP, +10%; Riptide Behemoth -20% HP, +20%; Wakeshell Adamant -20% HP, +10%; Maelstrom Sovereign slimes -25% damage taken, +25% HP.\n• Gravegaze Medusa below 50%: Stonega (Normal), Stonega II (Difficult), Stonega III (Savage); Easy unchanged.\n• Cragmaw Basilisk re-armor now on a timer instead of per hit.' }, { title = 'Fixes (2026-08-27)', note = '• Bestial Loyalty works for squad BSTs (used before jugs).\n• /dwbags worn status is accurate; Send/Get on an item you already own no longer ships your copy after the refusal.\n• Squad members and their pets no longer block movement; squad avatars no longer go invisible.\n• Raid window greys out collected first-of-the-day bonuses; squad EXP shown per character.\n• Storage tab Mixed display fixed, single command per group, Find tab notes extra matches, Refresh works.\n• Squad honours Call Beast Recast, Call Wyvern Recast, Activate merits.' }, { title = '2026-08-18: Stone and tide', note = '• Raid opens with /raid or !raid; gather party in any city, press Enter, return to your tile afterward.\n• Horlais Peak: Tidebound Colossus (wyverns), Riptide Behemoth (bloodflies).\n• Waughroon Shrine: Wakeshell Adamant (crab adds), Maelstrom Sovereign (splits into slimes).\n• Balga\'s Dais: Gravegaze Medusa (petrifies those facing her; look away on wind-up), Cragmaw Basilisk (party petrify breath, hatchling adds).\n• All four tiers (Easy-Savage) with their own daily first-clear bonus: 24 per day.\n• Three arenas per shrine (9 total); board shows busy arenas and elapsed time; 15-minute fight cap.' }, { title = '2026-08-11: The raid grows', note = '• Horlais Peak: Tidebound Colossus (wyverns on harder tiers) and new Riptide Behemoth (bloodflies when damaged).\n• Easy: boss Lv85, 5 Driftmarks per clear, daily first clear +25. Normal: Lv90, 10, +50. Difficult: Lv95 with adds at 50% HP, 20, +100. Savage: Lv99, twice as durable, 3 adds, 40, +200.\n• Driftmark shop expanded from 3 to 11 shelves.' } } },
    { name = 'Combat and jobs', group = 'Server', desc = 'DriftwoodXI combat, job and enemy changes collected from seven news posts, newest first; where posts disagree, the later one applies. Source: https://xi.driftwoodgaming.com/news/ankabut-crash-fix-and-shinryu-abjurations, https://xi.driftwoodgaming.com/news/blue-magic-overhaul-and-35-percent-gear-haste, https://xi.driftwoodgaming.com/news/a-cleaner-log-wider-rolls-and-a-corsair-who-sang, https://xi.driftwoodgaming.com/news/balance-pass-every-job, https://xi.driftwoodgaming.com/news/black-mage-reparations-endark-ii-and-a-macro-fix, https://xi.driftwoodgaming.com/news/enemy-balance-pass, https://xi.driftwoodgaming.com/news/combat-power-and-stats', steps = { { title = 'Crash fix, Shinryu abjurations and fixes (2026-10-20)', note = '• Ankabut in North Gustaberg [S] crashed the server three times by trying a TP move it lacked; it now uses Acid Spray.\n• Any monster rolling a nonexistent move now skips it rather than crashing the server.\n• Shinryu Abjurations (Head, Body, Hands, Legs, Feet) are sold on the DWRaid Abjuration page.\n• Trade one plus a DWSpoils Bewitched or Voodoo piece to Alphollon C Meriard for Carmine or Carmine +1 (iLvl 119).\n• Client crashes fixed: Rune re-roll of a rank-1 Double/Triple Attack, and dw addon windows displaying a percent sign.\n• Gaze attacks such as Grim Glower now require the monster to face you (a Peiste cannot petrify from behind).\n• Squad Call Wyvern shows its animation and chat line; a second press reports the wyvern is already out.\n• Roshi Jinpachi consumes one Arhat\'s Jinpachi.\n• Locus Ghost Crabs in Bibiki Bay give Magicite and Spoils again.\n• Linkshells discarded via DWBags or DWWarehouse release their names.\n• DWBags Fetch and inventory stacking wait until a synth completes.\n• Enchanter/Exchange: buying an augment for a second ring in the first ring\'s bag slot no longer reports "already settled".\n• Update addons in the launcher for the client fixes and dwcraft; server changes are live. Use /report for problems.' }, { title = 'Blue Magic overhaul (2026-09-25)', note = '• 28 spells that were learnable but uncastable now work, including Fantod, Leafstorm, Mortal Ray and Harden Shell.\n• Now learnable: Venom Shell (Uragnites, Bibiki Bay), Cold Wave (Snolls, Uleguerand Range and Pso\'Xja), Thermal Pulse (Wamouras, in normal combat), Spinal Cleave and Hysteric Barrage (Qutrubs and Lamiae, after their weapon breaks).\n• New spells: Erratic Flutter (self Haste II; Wamouras of Mount Zhayolm), Restoral (strong self cure; Apex cogs, Alzadaal Undersea Ruins), Rail Cannon (light nuke; same cogs), Diffusion Ray (light cone; Chariots in Salvage).\n• Efflux adds its TP bonus and extra damage to the next physical spell; Convergence adds damage and magic accuracy.' }, { title = 'Haste and delay caps (2026-09-25)', note = '• Gear haste cap: 35% (was 25%), allowing 25% from gear plus 10% from Ascension\'s Celerity.\n• Same cap for squad members, hired mercenaries and Battle tab duelists; magic haste and job ability haste caps unchanged.\n• Overall delay cap: 85% (was 80%), so attack rounds can drop to 15% of weapon delay; also applies to squad and mercenaries.' }, { title = 'Puppetmaster (2026-09-25)', note = '• Deploy recast: 3 seconds (was 8.5).\n• Automatons skill up at the player\'s rate: same catch-up bonus, rolls on missed swings/shots, no early cutoff against weak monsters.\n• Animator Z and Neo Animator give the automaton +89 to all seven stats.\n• Animator Z still requires 50 job points spent on Puppetmaster.' }, { title = 'Other changes (2026-09-25)', note = '• Overkill: every ranged attack is a double or triple shot, and ranged delay is halved while active.\n• Spaekona\'s Coat refunds 2% of elemental magic damage as MP; the +4 version and Seidr Cotehardie also have it.\n• Unleashed: for the boss\'s first 90 seconds awake it takes one tenth damage and cannot die; the rally broadcast announces when this starts and ends.\n• Espers: each paid kill prints a Magicite line in that kind\'s colour in the second chat window.\n• Crafting: HQ crystals count toward a recipe\'s crystal.\n• Aht Urhgan missions: Confessions of Royalty and The Black Coffin are always completable; you may retry a failed Shades of Vengeance.\n• Fixed many rare map crashes; pulling warehouse items into a full bag no longer stalls the server.' }, { title = 'Chat, Phantom Rolls and Corsair fixes (2026-09-22)', note = '• DWChat add-on is off by default; /dwchat opens it and /dwchat on enables it.\n• When enabled it colour-codes battle lines by type (damage dealt/taken, healing, buffs gained/lost, exp and other points, items and gil, skill-ups) and folds spam; each is a checkbox and the fold window is a slider.\n• Fancychat (tabbed chat) is now allowed: install it from the launcher\'s Addons tab using its GitHub link.\n• Phantom Roll and Double-Up range: 24 yalms (was 8).\n• "Elemental magic casting time -N%" now works on all 37 pieces that list it (previously 4), at retail values, e.g. Goetia Petasos +2 (Outfitter), Wicce Petasos ranks, the Mallquis set.\n• Squad melee no longer freeze when a healer sits in an earlier squad slot.\n• A squad Corsair with bullets but no gun no longer fires and uses them.\n• Outfitter Costume page: Goblin Belt, Rabbit Belt and Worm Belt, 50 Drift Coins each; each turns you into the creature for one hour.' }, { title = 'Job differences from retail (2026-09-19)', note = '• Jobs not listed behave as on retail. Format: DriftwoodXI (retail).\n• WAR: Warcry lasts 60 s (30 s).\n• MNK: Boost +25% attack per use (+12.5%); Boost base recast 30 s (15 s).\n• MNK: Impetus crit rate bonus caps at 35% (50%).\n• MNK: Formless Strikes lasts 30 s (3 min), base recast 5 min (10 min).\n• MNK: Chakra restores 2x HP (1x).\n• WHM: Club skill rank S- (B+).\n• The post\'s summary also lists Hasso and Seigan at 15 minutes, doubled buff song duration and 1.75x on four magic schools.' }, { title = 'Server-wide multipliers (2026-09-19)', note = '• Weapon skills 1.5x damage; cures 1.5x; blue magic 1.5x damage; items 3x.\n• Enmity from Provoke, Flash, Sentinel and similar tools doubled (flat and percentage).\n• Job ability recasts 15% faster.\n• Elemental magic recast timers are 3x retail; dark, enfeebling and enhancing black magic keep retail recasts.\n• Report balance issues with /report in game or at discord.gg/DriftwoodGaming.' }, { title = 'Elemental magic 1.75x (2026-09-18)', note = '• Elemental magic raised to 1.75x (from 1.25x): tier I–VI nukes, all -ga and -ja, ancient magic, Comet, Meteor, Impact, and all eight helixes including tier II.\n• Applies to you, squad members, trusts, hired mercenaries, and allied pets or charmed monsters.\n• Enemy elemental magic stays at 1.25x.\n• Stated as temporary; planned to settle at 1.5x later.\n• Dark, Divine, Ninjutsu, Blue and healing magic unchanged.' }, { title = 'Endark II, Enlight II and Prophetic Knife (2026-09-18)', note = '• Endark II (DRK, 100 job points spent) and Enlight II (PLD, 100 spent) now cast; existing unlocks already count.\n• They start at double the first tier\'s charge: at capped skill about 129 (vs 64) for Endark II and 126 (vs 63) for Enlight II; the bonus drops by 1 per landed hit.\n• They display as Endark/Enlight, and job point bonuses apply (Attack and Accuracy for Endark, Accuracy for Enlight).\n• Still not in game: the eight SCH storm II spells, Aspir III, Full Cure, Addle II, Distract III, Frazzle III, Refresh III, and the GEO -ra III line.\n• Prophetic Knife now grants Accuracy +35, Magic Accuracy +35, Critical hit rate +10%, and +242 to Dagger, Parrying and Magic Accuracy skill.\n• The Prophetica set bonus (weapon skill damage +10%) is not implemented yet.' }, { title = 'dwmacro 2.3.1 (2026-09-18)', note = '• Fixes /dwmacro remember 3 1 sometimes restoring Book 4, Set 2 after zoning.\n• The step to the neighbouring book and back is now sent as separate commands, checking the client\'s current page before the second.\n• Restores the client refuses (e.g. right after zoning) are retried.\n• A hand-named page uses the slow restore once, then restores instantly on later zone lines.\n• /dwmacro debug lists the steps of the last restore.\n• Update dwmacro through the launcher.' }, { title = 'Enemy balance pass (2026-08-05)', note = '• Ordinary enemies: HP 1.25x retail (was 1.5x); swing rate, stats and TP behaviour unchanged (they still weapon skill 1.5x as often as retail).\n• NMs: keep 2x HP and gain +10% to all base stats.\n• Ordinary enemies gain +4% HP per trust (was 10%), tapering from 4% below level 50 by one step per ten levels to 1% at 100+.\n• A five-trust squad faces trash at about 1.45x HP at the dunes and about 1.30x at endgame (was flat 2x).\n• NMs gain +10% HP per trust at all levels (2.5x with a full squad).\n• Attack and accuracy: +2% per trust (was 5%), for trash and NMs.\n• Only trusts (stock and alt-trusts) scale enemies; human party members never do.' }, { title = 'Core combat rules (2026-07-27)', note = '• Player HP, MP, base stats and TP gain match retail.\n• Sub job gives its full max MP and runs at your full main job level.\n• Enmity cap doubled.\n• 1.5x power: Cure, Divine, Ninjutsu, Blue and Dark magic, and weapon skills.\n• Elemental magic: 1.25x from 2026-08-22; 1.75x for players from 2026-09-18 (enemies 1.25x).\n• Items 3x power.\n• 10x weapon skill and skillchain points toward breaking latents.\n• Stoneskin cap 3x; Blink gives five shadows; spike effects last 4x; elemental debuffs last 2x; Sneak and Invisible last 3x; Aquaveil improved.' }, { title = 'Skills and utility (2026-07-27)', note = '• Melee: each swing, whether it hits or misses, gets a skill-up roll, and any roll under cap succeeds; gains are larger the further below cap you are.\n• Magic skills roll on every cast; skill caps are retail.\n• Parry, Block and Guard skill up in normal combat.\n• All jobs can widescan.\n• Level sync is on, with gear scaling.\n• Mission BCNMs have no level caps.' } } },
    { name = 'Account, storage and economy', group = 'Server', desc = 'DriftwoodXI\'s account-wide storage, player market, conquest exchange and elections, with add-on summaries first and patch notes newest first; where posts disagree, trust the most recent. Source: https://xi.driftwoodgaming.com/features/dwah, https://xi.driftwoodgaming.com/features/dwbags, https://xi.driftwoodgaming.com/features/dwcpx, https://xi.driftwoodgaming.com/features/dwpolitics, https://xi.driftwoodgaming.com/features/dwwarehouse, https://xi.driftwoodgaming.com/news/office-pays-now, https://xi.driftwoodgaming.com/news/dwpolitics, https://xi.driftwoodgaming.com/news/the-player-market, https://xi.driftwoodgaming.com/news/your-warehouse-grows-as-you-do, https://xi.driftwoodgaming.com/news/a-thousand-slots-that-follow-your-account, https://xi.driftwoodgaming.com/news/one-inventory-across-your-account', steps = { { title = 'DWAH', note = '• Type /dwah anywhere to open the Driftwood market: real listing prices, buy orders, remote selling.\n• It uses the same tables as the classic Auction House counter, so both show one market.' }, { title = 'DWBags', note = '• View, send and fetch the gear and items of every character on your account without logging off your main.' }, { title = 'DWCPX', note = '• Type /cpx anywhere for the Conquest Point Exchange: every nation\'s CP shelf and merchant counters, paid in CP or gil.' }, { title = 'DWPolitics', note = '• Type /politics to open the ballot box.\n• Six seats: Crown of Vana\'diel; Mayors of Bastok, San d\'Oria, Windurst and Jeuno; Royal Treasurer.\n• Each is decided by every eligible account on a four-week season: nominations week, campaign week, 72-hour secret ranked-choice poll, count, then governing.' }, { title = 'DWWarehouse', note = '• Type /warehouse anywhere: 1,000 server-held slots shared by your whole account, so any character can withdraw what another stored.\n• Earnable up to 2,000 slots, plus 1,000 more bought with gil.' }, { title = 'Office pays now (2026-09-15)', note = '• Adds a sixth seat (Mayor of Jeuno) and real powers for every office.\n• Office holders now set DWPort fares; of any charge above stock price, half goes to the holder and half is removed from the game, all on a public ledger.\n• Update dwpolitics and dwport in the launcher; the server side is already live.' }, { title = 'Mayor of Jeuno requirements', note = '• Filing fee 1,000,000 gil; Jeuno fame 9; level 75; 20 Drift Board contracts this season.\n• Also requires a finished term as Mayor of Bastok, San d\'Oria or Windurst.' }, { title = 'Office powers', note = '• Every power has a band, a cooldown, a Chronicle entry and an owner veto.\n• Proclamations: any seated holder may broadcast once per 20 hours, picked from a fixed menu (no free text).\n• Fares: Treasurer prices home points and survival guides; a town Mayor prices outposts held by their nation; Mayor of Jeuno prices all warps into Jeuno.\n• Fare band is 1/5 to 20x stock price; a rate may change once per 20 hours.\n• !politics knight <name>: Crown names a Knight of the Realm for the reign, max five at once.\n• !politics holiday: Crown drops the mercenary board cut to its minimum for one day, once per fortnight.\n• !politics amnesty: Crown clears all Wanted marks, once per season.' }, { title = 'Fare revenue and ledger', note = '• Above-stock fare income: 50% paid to the office holder, 50% burned.\n• /politics Revenue tab (or !politics revenue): each seat\'s take and burn for the season and lifetime, total realm burn, recent payments, and rate-change history.\n• If the owner freezes all powers, every fare reverts to stock price.' }, { title = 'DWPort', note = '• Buttons show the actual price including office-set rates.\n• New Runic Portals tab lists six Aht Urhgan staging points; inactive until Treasures of Aht Urhgan opens and you hold the Boarding Permit.' }, { title = 'Aht Urhgan groundwork (not yet reachable)', note = '• !sanction grants the Imperial guard\'s Sanction free.\n• Kills under Sanction earn Imperial Standing.\n• !imperial buys imperial items with standing from anywhere at Ugrihd\'s prices.\n• Salvage can be entered with a permit.' }, { title = 'Launcher 0.35.5', note = '• Adds client titles Mayor of Jeuno and Knight of the Realm.' }, { title = 'Politics launch (2026-09-09)', note = '• New addon; first season opened September 14 with five seats (Crown, Mayors of Bastok, San d\'Oria, Windurst, Royal Treasurer).\n• Open with /politics; every action also works as !politics.' }, { title = 'Season schedule', note = '• Four-week season for all, counted from September 14 00:00 UTC.\n• Week 1 (nominations): eligible players file, pay a fee held until the count, and write a platform.\n• Week 2 (campaign): candidates set pledges; seated officeholders give public endorsements.\n• 72-hour poll: secret ranked ballot in every race; instant runoffs until a majority.\n• Count is automatic at poll end and winners are seated immediately.\n• Mayors and Treasurer run every season; the Crown runs every second season and reigns two.\n• The window shows the current phase and what you can or cannot do.' }, { title = 'Seat powers', note = '• All powers are bounded menu picks with cooldowns, announced server-wide, logged in the Chronicle, and vetoable by the owner.\n• Crown: weekly royal decree, a 24-hour world buff (combat XP, capacity points, fame, 5% off all shops, or free chocobo rentals).\n• Crown: indict a player (Wanted for 72 hours plus a fine) or pardon one.\n• Mayors: week-long festival in their town: 5% off town shops, free town stable rentals, or a fame bonus in the town\'s area.\n• Treasurer: sets mercenary board cut and port-window travel prices within bands.\n• Treasurer: spends the Treasury on a stimulus (pays every account logging in over the next two days) or a two-day Drift Coin bonus on contracts.\n• Treasury income: losers\' filing fees, a cut of refunded pledges, indictment fines; balance and movements are public.' }, { title = 'Requirements to run', note = '• Mayor: town fame 9, level 75 on the filing character, 20 Drift Board contracts this season, account at least 2 weeks old, fee 250,000 gil.\n• Treasurer: 100 in every craft on the filing character, or 25 buy orders filled this season plus 25,000,000 gil lifetime market sales on the account; fee 500,000 gil.\n• Crown: a full term in another seat, plus one of: Gauntlet floor 50 cleared, the Last Verse of Chains of Promathia, or a Legend tier Nemesis kill; account at least 2 months old; fee 5,000,000 gil.\n• Winners get their fee back; losers\' fees go to the Treasury.\n• If the Regent wins (no filings, under five voters, or the Crown could not find its Mayors), all fees are refunded.' }, { title = 'Requirements to vote', note = '• One vote per account per race; account must predate the season and have 3 hours played; staff accounts cannot run or vote.\n• Mayor races: +1 vote at town fame 4, +2 at fame 7.\n• Crown and Treasurer races: +1 vote at 20 Drift Board contracts this season, +2 at 60.\n• Accounts logging in from the same address in a season share one base vote.' }, { title = 'Pledges and claims', note = '• Pledged gil is held by the server; if the candidate wins, it is split evenly among accounts that voted in that race.\n• A losing candidate gets 90% back; the Treasury keeps 10%.\n• Collect refunds, pledge shares, bounties or stimulus with the Claim button or !politics claim on any character.' }, { title = 'Chronicle and titles', note = '• The Chronicle is an append-only, uneditable log of reigns, acts, indictments and pardons, readable from the window.\n• Officeholders display their seat as a title; the launcher update adds the five title names on next launch.' }, { title = 'Quick start', note = '• Update the launcher, log in and open /politics.\n• From September 14, file for a seat if eligible, write a platform, and optionally pledge.\n• Vote in every race during the poll, ranking your choices.\n• Claim what you are owed and read the Chronicle.\n• Season one is Mayors and Treasurer only; the first Crown race is season two.' }, { title = 'The Player Market (2026-08-20)', note = '• /dwah anywhere shows every listing on the server with its real price, searchable and sorted by item level.\n• No listing fee and no expiry; listings stay until sold or cancelled. Seller pays 5% on sale.\n• Buy orders escrow your gil immediately; crafters can fill orders from their bags via the Orders tab and are paid at once; cancelling refunds the remaining escrow.\n• Account-wide: any of your characters can cancel your listings; proceeds go to an account wallet claimable anywhere; goods from filled orders wait in your market box.\n• Supply is player-only with no seeding or restocking; the old shopkeeper stock sells out and gil spent there is burned.\n• !market does everything without the addon.\n• Coffer and chest gil is now 10x retail base, the same with or without squad, split evenly when 2+ players are in the party.' }, { title = 'Warehouse growth (2026-08-17)', note = '• Every account starts at 1,000 slots.\n• +100 once for finishing either level-18 support job quest (Selbina or Mhaura) on any character.\n• +100 for each nation rank 2 through 10 the account reaches for the first time (900 max).\n• Ceiling is 2,000 slots.' }, { title = 'Warehouse growth rules', note = '• Rewards are per account and pay once: a second nation or second character at an already-reached rank adds nothing.\n• Slots are never removed, even if the earning character is deleted.\n• Retroactive: e.g. support quest done and rank 6 shows 1,600 next time you open it.\n• Open with /warehouse or !warehouse; the meter is at the top.' }, { title = 'Warehouse launch (2026-08-07)', note = '• 1,000 account-shared slots opened with /warehouse; stored items leave your bags entirely (not a container, mog safe or mule).\n• Every character on the account draws from the same pool instantly, no delivery box.\n• Search by typing three letters, as in /bags.' }, { title = 'Stash All', note = '• Moves your inventory into the warehouse in one press.\n• Skips rare, exclusive, augmented, equipped, bazaar and pinned items.' }, { title = 'Kits', note = '• A kit is a named material list; pressing it withdraws everything on the list into your bags.\n• Synthesis still only uses items in your actual bags.' }, { title = 'Item rules', note = '• Any item, including exclusive and augmented gear, can be deposited and withdrawn by any of your characters (at launch these were bound to the depositing character).\n• Nothing is reachable by other accounts; augments bought on the Drift Exchange stay untradeable to other players.\n• Rare items: if you already hold one, the warehouse keeps the second.' }, { title = 'Trash button', note = '• Added 9 August 2026: each row has a Trash button that deletes the stored item without needing a free bag slot.' }, { title = 'Opening the warehouse', note = '• /warehouse or /wh toggles the window.\n• dwwarehouse is installed by the launcher in the Default addon set; if absent, enable it in the launcher\'s Addons tab, or use /addon load dwwarehouse for the current session.\n• !warehouse lists contents in chat and every window action can be typed.\n• Each deposit and withdrawal is a single database transaction; the cap is server-owned and future rewards may raise it.' }, { title = 'Account-wide inventory (2026-07-26)', note = '• From any character, view and search every container on every account character and move items without logging in.\n• Squad members equip themselves from their own bags.' }, { title = 'Finding items', note = '• !squad find silk searches inventory, mog safe, satchel, sack, case and all eight wardrobes on every character, including ones never logged in on this computer.\n• !squad who lists every character, their jobs and bag fullness.\n• !squad bag Yakapo, !squad bag Yakapo satchel, !squad bag Yakapo 2 show all bags, one container, or the next page.' }, { title = 'Moving items', note = '• !squad send Yakapo Bronze Sword (optional qty, e.g. Beehive Chip 12) pushes an item to another character; it arrives at their next call.\n• !squad fetch Yakapo Bronze Sword pulls an item into your bags instantly.\n• Typical flow: send, then !squad call.\n• !squad box shows in-transit items; uncollected items sit in that character\'s delivery box at a Mog House.\n• Rare/Ex items that cannot be sent still cannot; items flagged sendable within the account can.\n• Worn items cannot be taken, and you cannot fetch from a summoned or logged-in character.' }, { title = 'Squad auto-gear', note = '• At summon, each slot gets the best item the character can wear (job, level, race, two-handed and dual-wield rules), scored for its role; e.g. a white mage weights MND and cure potency.\n• Useful for characters levelled via the experience relay; their own saved loadout is not changed.\n• !squad gear Yakapo shows what was picked and what it beat.\n• Override: !squad equip Yakapo main Bronze Sword; none empties a slot; auto returns it to the scorer; !squad unpin Yakapo clears all pins.\n• Pins persist through zoning, logouts and restarts.' }, { title = 'DWBags window', note = '• /dwbags shows characters on the left and bags, gear and in-transit items on the right, with icons, account-wide search and move buttons.\n• On by default in the launcher\'s Default addon set; holds no data of its own.\n• !squad menu offers the same actions through in-game dialogs.' }, { title = 'Command list', note = '• !squad who: all characters and bag fullness\n• !squad bag <char> [where] [page]: one character\'s bags\n• !squad find <text>: search all containers on all characters\n• !squad send <char> <item> [qty]: send; arrives at their next call\n• !squad fetch <char> <item> [qty]: pull into your bags\n• !squad box [char]: items in transit\n• !squad gear <char>: chosen gear and what it beat\n• !squad equip <char> <slot> <item>: pin a piece\n• !squad equip <char> <slot> auto: unpin (none leaves the slot empty)\n• Every transfer is a single database transaction.' } } },
    { name = 'Travel and quality of life', group = 'Server', desc = 'DriftwoodXI\'s travel addon (dwport), launcher fixes for camera, controller and UI settings, the new website, and the /dwt quest tracker, with the newest post taking priority. Source: https://xi.driftwoodgaming.com/features/dwport, https://xi.driftwoodgaming.com/news/your-camera-settings-stick-now, https://xi.driftwoodgaming.com/news/your-controller-your-ui, https://xi.driftwoodgaming.com/news/stop-teleporting-twice, https://xi.driftwoodgaming.com/news/the-website-is-open, https://xi.driftwoodgaming.com/news/close-the-wiki-tab', steps = { { title = 'DWPort', note = '• Shows all your unlocked teleports in a single window, priced at fares set by the realm\'s office holders.\n• Opens with /port; tabs cover home points, survival guides, outposts, teleport spells, Unity and Voidwatch warps, and Aht Urhgan Runic Portals.' }, { title = 'Your camera settings stick now (2026-08-12)', note = '• Bug: camera movement under Config → Mouse/Cam. reverted to Inverted on every launch.\n• Cause: the launcher pinned some machine-wide game settings to values from the machine it was built on.\n• Fix: settings the launcher does not manage now pass through to your own machine, so Mouse/Cam. changes survive a relog.\n• Restart the launcher to install the update automatically.' }, { title = 'Your controller and your UI are yours again (2026-08-11)', note = '• The launcher no longer overwrites controller buttons at launch; by default your Windows-side FFXI pad config is used, or you can map buttons in the launcher.\n• UI size, font quality, texture quality and other options are now real settings; the forced 1600×900 UI (blurry on 1440p/4K) is removed.\n• After server maintenance, /squad gains a checkbox "Trusts engage when you draw your weapon."\n• On: trusts join as soon as you engage. Off (default, retail behaviour): they wait until your first hit lands.\n• Restart the launcher to update; existing settings carry over.' }, { title = 'Stop teleporting twice: the travel window (2026-08-02)', note = '• The dwport addon ships with the server, is enabled in the Default set, and opens with /port or a bare !port.\n• Unlocked destinations appear in tabs, locked ones are greyed, and fees match what the NPC charges.' }, { title = 'Stop teleporting twice: the travel window — What it does', note = '• Home button: the free !home warp.\n• Home points: every attuned crystal at the crystal\'s fee (free within your own city\'s group; cheaper anywhere with Rhapsody in White).\n• Survival guides: every registered book, 1,000 gil each.\n• Outposts: every region your outpost warp reaches; most are available from the start.\n• Teleport: the six Teleport spells and three Recalls; one click casts if you or a white mage in your squad can actually cast it (crystal attuned, spell learned, level reached, enough MP), and the MP is spent.\n• A search box filters all tabs, a star pins favourites to the top, and your last five trips appear as buttons under the header.' }, { title = 'Stop teleporting twice: the travel window — What it deliberately does not do', note = '• It never unlocks anything: unvisited crystals, unread books, outpost regions without the supply run, and uncastable spells stay greyed with the reason shown.\n• Typed commands work without the window: !port list hp, !port go sg 42, !port jeuno, !port home.\n• The launcher downloads dwport automatically; if the window will not open, enable dwport in the launcher\'s Addons tab or type /addon load dwport.' }, { title = 'The website is open (2026-07-31)', note = '• xi.driftwoodgaming.com is live: create an account, download the launcher, reset a lost password, and read posts without installing anything.' }, { title = 'The website is open — What is on it', note = '• Accounts are created only on the website (username, email, password); the launcher only signs in.\n• The launcher download lists its SHA-256 so you can verify the file.\n• Password reset sends you an emailed link to set a new password.\n• All news posts are readable in a browser with no account.' }, { title = 'The website is open — Why the email address matters', note = '• Your email is used only for account recovery; there is no mailing list and nothing else is sent.\n• Use an address you will keep, since a password you cannot reset means a character you cannot reach.' }, { title = 'The website is open — Sending people here', note = '• The site covers the server\'s rates, the base game plus Rise of the Zilart launch content, the one-account-per-player rule, and the squad system.\n• You still play through the launcher, which keeps itself and its addons updated.' }, { title = 'Close the wiki tab (2026-07-28)', note = '• /dwt opens the quest tracker with four tabs: active quests, active missions, and completed quests and missions.\n• Opening an active entry lists its steps in order: finished steps dimmed, the current step highlighted, the rest after it.\n• Steps are built from this server\'s own quest scripts, and the current step is chosen from your real quest flags and key items.\n• If your position cannot be determined, no step is lit; a quest without a written guide shows only its name.\n• Guides exist for all 443 missions and quests currently available.\n• Enabled by default in the launcher\'s addon set; typing !dwt sync shows the data the window receives.\n• Report right away any lit step that disagrees with what the quest requires.' } } },
    { name = 'Client and launcher', group = 'Server', desc = 'How to get the DriftwoodXI launcher (Windows or Linux AppImage), run the game under Wine by hand, fix common launch failures, and what each launcher release added. Where news posts disagree, the newer one applies. Source: https://xi.driftwoodgaming.com/download, https://xi.driftwoodgaming.com/download/linux, https://xi.driftwoodgaming.com/news/get-a-working-client, https://xi.driftwoodgaming.com/news/playing-on-linux, https://xi.driftwoodgaming.com/news/defender-false-positive, https://xi.driftwoodgaming.com/news/hd-packs-one-toggle-away, https://xi.driftwoodgaming.com/news/the-black-screen-after-zoning, https://xi.driftwoodgaming.com/news/windows-defender-false-alarm, https://xi.driftwoodgaming.com/news/hd-mods-without-touching-a-file, https://xi.driftwoodgaming.com/news/streamer-mode-hides-your-login, https://xi.driftwoodgaming.com/news/the-launcher-installs-ashita-now, https://xi.driftwoodgaming.com/news/verify-your-game-files, https://xi.driftwoodgaming.com/news/the-launcher-keeps-itself-current, https://xi.driftwoodgaming.com/news/launcher-in-testing', steps = { { title = 'Download — Windows launcher v0.36.17', note = '• The download page lists a SHA-256 for the installer; compute yours in PowerShell to compare.\n• The installer is unsigned, so SmartScreen shows "Windows protected your PC": pick More info, then Run anyway.\n• A matching SHA-256 is the stronger proof the file is genuine.\n• You need an FFXI client on the current retail build; if PlayOnline won\'t update it, follow Get a working client.' }, { title = 'Download — Linux AppImage v0.36.17', note = '• Mark the AppImage executable (chmod +x) and run it.\n• The game itself still runs in Wine, so set up a Wine prefix with the retail client first (see Linux step 1).' }, { title = 'Linux 1 — Before you start', note = '• Install the retail client in a Wine prefix: the Lutris Final Fantasy XI installer, or a plain 64-bit prefix plus the PlayOnline installer; let PlayOnline finish its ~10 GB update.\n• Prefer a plain Wine/Lutris prefix over Steam Proton.\n• Register an account; the loader prompts for it.\n• Install the Microsoft Visual C++ 2015-2022 runtime in the prefix (winetricks); without it the game quits 1-2 s after start with msvcp140.dll.?_Throw_Cpp_error.\n• Tools needed: unzip, curl, jq, winetricks.' }, { title = 'Linux 2 — Install the Ashita bundle', note = '• Download the newest zip from the content repo\'s bundles folder; ashita.json names the current file and its SHA-256.\n• mkdir -p ~/.wine/drive_c/DriftwoodXI/Ashita\n• unzip -q DriftwoodXI-Ashita-*.zip -d ~/.wine/drive_c/DriftwoodXI/Ashita\n• Contents: Ashita v4 (Ashita-cli.exe), loader at bootloader/xiloader.exe, sandbox and DAT-overlay POL plugins, winefix, and all DriftwoodXI add-ons current at the bundle date.' }, { title = 'Linux 3 — Write the boot ini', note = '• Copy config/boot/example-privateserver.ini to config/boot/driftwood.ini and replace its top part; leave the remaining [ashita.boot] lines as in the example.\n• [ashita.launcher] autoclose = 1 name = DriftwoodXI [ashita.boot] file = .\\\\bootloader\\\\xiloader.exe command = --server xi.driftwoodgaming.com gamemodule = ffximain.dll script = driftwood.txt args =\n• With sandbox = 0 (example default), settings come from the prefix registry; edit them with FFXI Config in the prefix.\n• European client: add --lang EU to command.' }, { title = 'Linux 4 — Write the script', note = '• Copy scripts/default.txt to scripts/driftwood.txt.\n• After /load screenshot, add /load winefix, then /addon load <name> for each add-on you want.\n• Add-ons: dwah, dwarena, dwbags, dwcon, dwcpx, dwcraft, dwengage, dwfame, dwfishing, dwgambits, dwhub, dwjobs, dwleaderboard, dwmacro, dwmerc, dwmerits, dwnemesis, dwparse, dwpolitics, dwport, dwquest, dwraid, dwreport, dwscan, dwspoils, dwsquad, dwtoau, dwtod, dwtracker, dwunleashed, dwwarehouse, dwchat, dwesper.\n• All are server add-ons on the allowed list; dwgmpanel is staff-only and not bundled.' }, { title = 'Linux 5 — Launch', note = '• cd ~/.wine/drive_c/DriftwoodXI/Ashita then wine Ashita-cli.exe driftwood.ini\n• Enter username and password at the terminal prompt, or set command = --server xi.driftwoodgaming.com --user NAME --pass PASSWORD (stores the password as plain text).\n• Lutris: executable Ashita-cli.exe, arguments driftwood.ini, working directory the Ashita folder, prefix = your client\'s prefix.' }, { title = 'Linux 6 — Update add-ons by hand', note = '• Run this after every content patch (patches are announced in news):\n• cd ~/.wine/drive_c/DriftwoodXI/Ashita feed=https://raw.githubusercontent.com/DriftwoodGaming/DriftwoodXI-Content/main/content.json curl -fsSL "$feed" | jq -r \'.packages[] | .id + " " + .url\' | while read -r id url; do curl -fsSL "$url" -o "/tmp/$id.zip" && rm -rf "addons/$id" && unzip -qo "/tmp/$id.zip" -d addons/ done\n• Each zip has a single <id>/ folder; the manifest lists a SHA-256 per package.' }, { title = 'Linux 7 — Missing without the launcher', note = '• No automatic add-on/Ashita updates, saved accounts or one-click profiles.\n• No DAT text overlay: repurposed items (e.g. Outfitter\'s job capes) show retail names/descriptions; cosmetic only.\n• No game-settings or gamepad screens (use FFXI Config) and no HD texture packs.' }, { title = 'Linux 8 — Troubleshooting', note = '• "Failed to locate profileServerPortAddress2!" or POL-0033 at the lobby: loader signature doesn\'t match your PlayOnline build (Windows too); report your polcore.dll version on Discord.\n• Exit 2-3 s after "Ashita injected and installed! Enjoy!" with msvcp140.dll.?_Throw_Cpp_error@std@@YAXH@Z: install Microsoft\'s C++ runtime in the prefix.\n• Black window or crash on start: test the script with and without /load winefix; check Ashita\'s boot log in its logs folder.\n• Crash at character select or during zone load with "Unhandled page fault on write access to 00000018": listed as a known symptom, no fix given.\n• Launch Log shows "core overlay skipped: block carries item id 0": update the launcher to v0.32.6+.\n• Verify Game Files reports ~1,000 differences: check the manifest date in Settings; retail patches about monthly and rewrites ~1,000 DATs, so an outdated manifest flags a correct client.' }, { title = 'Linux 9 — Steam Deck', note = '• Game Mode symptom: launcher opens, Play gives a white window, client is waiting on PlayOnline\'s accept/decline screen.\n• Get it working in Desktop Mode first (removes gamescope).\n• The PlayOnline user agreement before character select must be accepted manually.\n• Use windowed: Settings → Game settings → Screen mode → Windowed at 1280×800 (default is borderless at native size), or set it in FFXI Config.\n• FFXI is Direct3D 8; DXVK\'s D3D8 support is separate from D3D9, so a "DXVK enabled" prefix may still use Wine\'s OpenGL; wined3d or a deliberate d3d8-to-d3d9 setup are both fine.\n• Game Mode only: try gamescope window-sizing flags; staff haven\'t tested on a Deck, so post working flags on Discord.' }, { title = 'Get a working client (2026-09-11)', note = '• Check your build: PlayOnline Viewer → Check Files; you need FINAL FANTASY XI Ver.30260904_1 (also shown in the launcher\'s top bar after a launch).\n• If behind and you have a PlayOnline login, start FFXI from the viewer to patch; without a login, Check Files only verifies and won\'t update.\n• Update the launcher to 0.33.0+, which keeps Ashita\'s files current and restores item names in the Market, bags and Warehouse.\n• The website page also covers the Defender false alarm, the PlayOnline "repairing" loop, the loader signature error and false Verify Game Files differences.\n• No Square Enix account or subscription needed; for help bring build number, launcher version and Launch Log to Discord.' }, { title = 'Linux guide published (2026-09-05)', note = '• The Linux by-hand guide went up; at that time the game ran under Wine but the launcher did not (an AppImage came later).\n• The launcher\'s Windows-only tool calls were moved behind one platform layer.' }, { title = 'Windows Defender quarantine (2026-08-25)', note = '• Symptom: "Launch failed - Ashita-cli exited with code 1" because Defender quarantined driftwood-xiloader.exe; Microsoft confirmed it clean after an August 15 submission.\n• Open Windows Security → Virus and threat protection → Protection history.\n• Select the item naming driftwood-xiloader.exe → Actions → Restore, then choose Allow on device.\n• Launch normally; Allow is required because the launcher refreshes the file each launch and it would be quarantined again.\n• The launcher now explains a Defender removal and flags a missing loader before login; a code-signed loader is planned.' }, { title = 'Defender false alarm (2026-08-15)', note = '• A definition update flagged driftwood-xiloader.exe as Trojan:Win32/Bearfoos.A!ml.\n• The loader is built from the open-source LandSandBoat xiloader and matched source control bit-for-bit.\n• After Microsoft fixes the definition (usually a few days), the launcher restores the loader automatically.\n• To play sooner: Protection history → Bearfoos entry → Restore / Allow.' }, { title = 'HD packs in launcher 0.26.0 (2026-08-23)', note = '• Settings → Alternate graphics has two toggles.\n• NextHD Textures: HD world, characters and UI; ~3.5 GB download, 7 GB on disk.\n• XICombinedMaps: all zone maps redrawn and labeled, from the updated 2020 maps, FFXI Remapster and Moop\'s labeled Remapster; ~0.8 GB.\n• Off by default; switching off gives stock files on the next launch.\n• Downloaded only when enabled, resumable; disabling keeps files; Remove download frees the space.\n• Hand-installed XIPivot mods stay and take priority; visuals only, Verify Game Files still passes.' }, { title = 'Black screen after zoning fixed (2026-08-16)', note = '• Symptom: zoning into a black world with players and chat visible but no ground and no movement.\n• Cause: launcher defaulted to uncompressed textures (~4x the memory), exceeding the old client\'s memory cap, which also leaks between zones.\n• Fix: texture quality reset once to High (compressed) for everyone; choosing Uncompressed afterwards is respected.\n• If it recurs: restart the client before long sessions (especially Dynamis); HD packs use the same memory; report on Discord.\n• Same patch fixed a zone crash caused by a charmed player using Call Squad in Dynamis.\n• Restart the launcher to install the update.' }, { title = 'XIPivot in launcher 0.20.0 (2026-08-12)', note = '• Toggle XIPivot on in the launcher\'s Addons tab (off by default); it overlays mods in memory and never edits game files.\n• Put each mod\'s folder, as packaged, into polplugins\\DATs in your Ashita install.\n• In game, type /pivot to enable overlays and set their order; the higher entry wins when two mods replace the same file.\n• Only your client\'s visuals change, not anything server-side.' }, { title = 'Streamer mode, launcher 0.9.2 (2026-08-05)', note = '• Fixes leaks: the Home account picker showed "Display name (yourlogin)" and the text under PLAY named the account.\n• Display names, login usernames and character names are now blurred on Home, Accounts and Addons; hover to read.\n• Names are stripped from launch log text, including loader output; toasts and avatars no longer reveal them.\n• The Windows-drawn account dropdown shows initials, e.g. M•••• (z••••).\n• Enable in Settings → Privacy (off by default).' }, { title = 'Install Ashita button, launcher 0.9.0 (2026-08-04)', note = '• The first-run wizard\'s Install Ashita button fetches the official bundle (Ashita v4, xiloader, plugins, full add-on set) into a launcher-owned folder.\n• Settings → Paths has Install Ashita plus Browse for your own install.\n• Downloads must match the published size and SHA-256; a failed install is fully cleaned up.\n• Errors now say whether Ashita is missing or the path is wrong, and which button fixes it.\n• An already working Ashita folder is left alone; files it didn\'t create are never overwritten.' }, { title = 'Verify Game Files, launcher 0.9.1 (2026-08-04)', note = '• Manifest of a known-good install: 65,063 files, 13.87 GB, each with size and SHA-256; the check takes a few minutes.\n• HD packs and other DAT mods show up as differences, which is expected.\n• If FFXI isn\'t detected, use Browse in the wizard or Settings → Game files → Change folder; the folder is validated as an FFXI install.' }, { title = 'Self-updating launcher (2026-07-31)', note = '• Checks for a new launcher at start and every few hours, downloads in the background, then asks for a restart.\n• Server add-ons (dwbags, dwsquad, dwgambits, dwjobs, dwmerc, dwparse, dwtracker, dwreport, dwmacro and later ones) must match the server; the launcher installs them and repairs damaged ones.\n• Folders you installed or edited yourself are untouched; updates for them appear as an offer with a button.\n• Failed updates keep the old version; downloads are checked against a published fingerprint and unpacked separately first.\n• Settings → DriftwoodXI addons shows your version and a toggle for manual updating.' }, { title = 'Launcher features (2026-07-22)', note = '• Accounts saved locally; passwords encrypted with Windows DPAPI and never shown.\n• Lists every add-on/plugin with author and version; toggles rewrite a launcher-owned boot script, and your default.txt is only read once.\n• Install an add-on from a GitHub repository URL; its source is recorded for update checks.\n• Default resolution, screen mode and other settings, with per-account overrides.\n• First-run wizard locates the install and verifies files.\n• Self-updates, auto-refreshing server status and news, a Play button that reflects whether the server is up, and a Credits page.' } } },
    { name = 'Add-on versions (launcher feed)', group = 'Server', desc = 'Version list and short descriptions of the add-ons that the DriftwoodXI launcher installs, as listed in its public content feed. Source: https://github.com/DriftwoodGaming/DriftwoodXI-Content (content.json, ashita.json)', steps = { { title = 'Content feed 2026.10.28 (33 add-ons)', note = '• dwah 1.11.1: player market.\n• dwarena 1.1.3: Gauntlet alliance wave survival, floors 1-50.\n• dwbags 1.33.2: account-wide bag viewer, item moves, squad gearing.\n• dwchat 1.1.3: colour-coded, condensed chat log with Window 2 routing and filters; disabled by default.\n• dwcon 1.3.3: shows /check difficulty and level of nearby enemies.\n• dwcpx 1.4.3: Conquest Point Exchange; buy from any nation\'s CP shelf or merchant remotely with CP or gil.\n• dwcraft 1.7.9: crafting skills, ranks, specialization budget, account-wide recipe book (incl. DWWarehouse), skill-up costs, session tally, per-character crafts.\n• dwengage 1.2.0: auto-targets the party\'s next enemy after your target dies.\n• dwesper 1.2.3: Espers, Magicite, and the spells/abilities they grant.\n• dwfame 1.1.3: fame per area as bars, plus a guide.\n• dwfishing 1.3.3: costed 0-110 fishing route; fish, bait, rods and spots at server rates.\n• dwgambits 1.17.0: visual gambit editor for squads.\n• dwhub 1.1.2: one window listing all server add-ons with open/load buttons, plus an orderable side rail.\n• dwjobs 1.2.4: click to change party members\' main and sub jobs.\n• dwleaderboard 1.3.3: leaderboards for job levels, gil, kills, no-death streaks, storage, crafts, market.\n• dwmacro 2.3.1: keeps your macro book and set after zoning or relogging.\n• dwmerc 1.5.3: mercenary board store.\n• dwmerits 1.4.3: merit totals, raise/lower beyond the stock menu, job points, three Ascension pages.\n• dwnemesis 1.8.0: +100 famous NMs in a private arena; personal chest; augmented drops.\n• dwparse 1.2.3: damage/healing parser; commands /parse or /dwparse.\n• dwpolitics 1.4.3: elections, voting, pledges, governing, the Chronicle.\n• dwport 1.7.3: one-click access to all unlocked teleports.\n• dwquest 1.41.0: Drift Board with daily, weekly and server-wide contracts, Drift Coins and ledger, Accepted tab, augment Enchanter and reference, Outfitter, ArmsDealer, Pop-Items, Jeweler, Special shelf, one-time Primer.\n• dwraid 1.25.0: raid trials, tiers and driftmarks.\n• dwreport 1.2.1: in-game bug reports that include game state.\n• dwscan 1.6.3: target level, drops at server rates, resistances, aggro, quests.\n• dwspoils 1.5.1: augmented gear from normal kills, Runes, disenchanting into Runes, four-augment hall, Super Auged finds.\n• dwsquad 1.9.4: squad roster of your characters; tabs Main, States, Stats, Exp.\n• dwtoau 1.3.6: squad ToAU tools for BLU spells, PUP automaton, COR rolls.\n• dwtod 1.0.7: timed-pop NM status and server respawn timers.\n• dwtracker 1.3.1: quest and mission tracker.\n• dwunleashed 1.2.0: roaming world boss location, wake timer, last five responders.\n• dwwarehouse 1.19.2: account-wide virtual storage.' }, { title = 'Ashita bundle', note = '• Bundle 20260920-1151; Ashita core 4.3.2.1.' } } },
}

return S
